/* Recipe database for Kusina Consult — 500 recipes (50 per category), from the group's recipe document. */
const CATEGORIES=[{"key": "main-pork", "label": "Pork", "group": "Main Dishes"}, {"key": "main-beef", "label": "Beef", "group": "Main Dishes"}, {"key": "main-chicken", "label": "Chicken", "group": "Main Dishes"}, {"key": "main-seafood", "label": "Seafood", "group": "Main Dishes"}, {"key": "main-fish", "label": "Fish", "group": "Main Dishes"}, {"key": "side", "label": "Side Dishes", "group": "More"}, {"key": "appetizer", "label": "Appetizers", "group": "More"}, {"key": "soup", "label": "Soups", "group": "More"}, {"key": "dessert", "label": "Desserts", "group": "More"}, {"key": "beverage", "label": "Beverages", "group": "More"}];
const RECIPES=[{"title":"Pork Menudo with Bell Pepper","category":"main-pork","description":"A colorful Filipino tomato stew made with tender pork, liver, hotdogs, carrots, potatoes, and bell peppers. It's a favorite for family gatherings and special occasions.","ingredients":["2 lbs pork shoulder, diced","10 oz pork liver, diced","1 pc red bell pepper, cut into squares","1 pc green bell pepper, cut into squares","2 pcs medium carrots, diced","2 pcs medium potatoes, diced","4 pcs hotdogs, sliced","8 oz tomato sauce","2 pcs medium onions, chopped","5 cloves garlic, chopped","3 pcs dried bay leaves","3 tbsp soy sauce","1 tbsp beef powder","1½ cups cooking oil","2 cups water","1 tsp sugar","Fish sauce and ground black pepper to taste"],"steps":["Combine pork and soy sauce in a bowl. Marinate for 10 minutes.","Heat oil. Fry carrots and potatoes until brown. Set aside. Sauté hotdogs for 1–1½ minutes. Set aside.","In the same pan, sauté half the onion. Add liver and cook until lightly browned. Set aside.","Sauté garlic and remaining onion. Add marinated pork and sauté until light brown.","Pour in tomato sauce and water. Bring to a boil. Add bay leaves and beef powder. Simmer until pork is tender.","Return hotdogs and liver. Cook for 3 minutes. Add bell peppers, carrots, and potatoes. Cook for 1 minute.","Add sugar. Season with fish sauce and pepper. Serve with rice."],"id":"r001"},{"title":"Spicy Pork Ribs Adobo","category":"main-pork","description":"Meaty pork ribs simmered in a tangy, savory, and slightly spicy adobo sauce. The meat becomes tender and full of bold flavor.","ingredients":["1½ lbs pork ribs, cut into pieces","6 cloves garlic, minced","¼ cup soy sauce","3 tbsp white vinegar","2 tbsp oyster sauce","1 tsp chili flakes (adjust to taste)","3–5 pcs Thai chili peppers, sliced","1 tsp whole black peppercorns, cracked","1 tsp salt","½ cup lemon-lime soda","1 cup water","2 tbsp cooking oil"],"steps":["Season pork ribs with salt. Heat oil in a pan and brown the ribs on all sides. Set aside.","In the same pan, sauté garlic until fragrant.","Pour in soy sauce, vinegar, oyster sauce, lemon-lime soda, and water. Bring to a boil.","Add peppercorns, return the ribs. Cover and simmer over low heat for 45–60 minutes until tender.","Add chili flakes and Thai chilies. Simmer uncovered until sauce thickens and coats the ribs.","Serve hot with steamed rice."],"id":"r002"},{"title":"Honey Garlic Pork Chops","category":"main-pork","description":"Juicy pork chops seared and coated in a glossy, sweet, and savory honey-garlic glaze. Quick to make and absolutely delicious!","ingredients":["4 pcs pork chops (about 1-inch thick)","4 cloves garlic, minced","3 tbsp honey","2 tbsp soy sauce","1 tbsp calamansi juice or vinegar","2 tbsp cooking oil","Salt and ground black pepper to taste"],"steps":["Pat pork chops dry. Season both sides with salt and pepper.","Heat oil in a pan over medium-high heat. Sear pork chops 3–4 minutes per side until golden brown. Set aside.","In the same pan, sauté garlic over low heat until fragrant (about 30 seconds).","Stir in honey, soy sauce, and calamansi juice. Simmer for 1–2 minutes until slightly thickened.","Return pork chops to the pan. Coat well with the glaze. Cook for 2 more minutes.","Serve with rice or vegetables."],"id":"r003"},{"title":"Pata Humba (Braised Pork Hocks)","category":"main-pork","description":"A Visayan favorite pork hock is slowly braised in a sweet-savory soy sauce until the meat is fall-off-the-bone tender. Rich, sticky, and flavorful.","ingredients":["2 lbs pork hocks (pata), cleaned","¼ cup soy sauce","⅓ cup vinegar","1 onion, chopped","6 cloves garlic, crushed","½ cup brown sugar","3 cups water","¼ cup dried banana blossoms, soaked","¼ cup dried mushrooms, soaked (optional)","3 pcs. dried bay leaves","1 tsp whole black peppercorns","2 tbsp cooking oil","Salt to taste"],"steps":["Marinate pork in soy sauce, vinegar, garlic, onion, and peppercorns for 1 hour.","Heat oil. Pan-fry pork until golden brown on all sides.","Pour in the marinade and water. Add bay leaves, banana blossoms, and mushrooms. Bring to a boil.","Lower heat. Cover and simmer for 1–1 1⁄2 hours until the meat is very tender.","Add brown sugar. Simmer uncovered until sauce thickens. Season with salt.","Serve with plenty of hot rice."],"id":"r004"},{"title":"Fried Pork Belly Liempo (Lechon Kawali)","category":"main-pork","description":"Crispy, golden-brown deep-fried pork belly with incredibly crunchy skin and juicy meat inside. Served with a tangy liver sauce.","ingredients":["2 lbs pork belly (liempo)","4 cups water","2 tbsp salt","1 tsp whole peppercorns","3 pcs dried bay leaves","3 cups cooking oil (for deep frying)","## Liver Sauce","½ cup liver spread","¼ cup vinegar","¼ cup water","2 cloves garlic, minced","1 tbsp brown sugar","Salt and pepper to taste"],"steps":["Place pork belly in a pot with water, salt, peppercorns, and bay leaves. Boil for 45–60 minutes until tender.","Remove pork. Pat dry thoroughly with paper towels. Air-dry for 1–2 hours (or overnight in the fridge) until completely dry.","Heat oil in a deep pan. Carefully deep-fry pork over medium heat until golden and crispy.","For the sauce: Sauté garlic. Add liver spread, vinegar, water, and sugar. Simmer for 3–5 minutes. Season to taste.","Slice pork. Serve with the dipping sauce."],"id":"r005"},{"title":"Pork Estofado","category":"main-pork","description":"Pork braised in soy sauce, vinegar, and sugar, tender and caramelized. Similar to adobo but sweeter.","ingredients":["2 lbs pork belly or shoulder","½ cup soy sauce","¼ cup vinegar","½ cup brown sugar","1 cup water","6 cloves garlic","2 bay leaves","2 saba bananas, peeled","2 tbsp oil"],"steps":["Brown pork. Add soy sauce, vinegar, sugar, water, garlic, bay leaves.","Simmer for 45 mins. Add bananas, cook for 15 more mins until sauce thickens."],"id":"r006"},{"title":"Pork Hock and Mung Beans with Vermicelli (Ginisang Monggo with Pata at Sotanghon)","category":"main-pork","description":"A hearty, comforting mung bean soup with tender pork hocks and soft vermicelli noodles. Perfect for rainy days!","ingredients":["1 lb pork hock (pata), cut into pieces","1 cup dried mung beans (monggo), soaked overnight","50g vermicelli noodles (sotanghon), soaked","1 onion, chopped","4 cloves garlic, minced","2 pcs tomatoes, chopped","6–7 cups water or pork broth","2 tbsp fish sauce","2 tbsp cooking oil","1 cup malunggay leaves or spinach","Salt and pepper to taste"],"steps":["Boil mung beans in water until skins burst and beans soften. Set aside.","Heat oil. Sauté garlic, onion, and tomatoes. Add pork and brown lightly.","Add water or broth. Bring to a boil. Simmer for 45 minutes until the pork is tender.","Add cooked mung beans. Simmer for 15 more minutes.","Add vermicelli noodles and cook for 3–5 minutes until soft.","Stir in malunggay leaves. Turn off heat. Season with fish sauce, salt, and pepper. Serve hot."],"id":"r007"},{"title":"Pork Ribs Caldereta","category":"main-pork","description":"Rich, tomato-based stew with tender pork ribs, potatoes, carrots, and bell peppers. Often topped with cheese for extra richness.","ingredients":["2 lbs pork ribs, cut into pieces","1 onion, chopped","4 cloves garlic, minced","1 cup tomato sauce","2 cups water or broth","1 pc potato, cubed and fried","1 pc carrot, cubed","1 pc red bell pepper, sliced","½ cup liver spread","¼ cup grated cheese (optional)","3 tbsp cooking oil","Salt and pepper to taste"],"steps":["Heat oil. Brown pork ribs on all sides. Set aside.","Sauté garlic and onion. Add tomato sauce and water/broth. Bring to a boil.","Return ribs. Cover and simmer over low heat for 1 hour until tender.","Add potatoes, carrots, and bell pepper. Cook until vegetables are tender.","Stir in liver spread and cheese. Simmer for 5 more minutes. Season to taste.","Serve with rice."],"id":"r008"},{"title":"Kinamatisang Baboy","category":"main-pork","description":"A simple, comforting pork soup cooked with ripe tomatoes and vegetables. Light, flavorful, and easy to digest.","ingredients":["1½ lbs pork belly or ribs, cut into pieces","4–5 ripe tomatoes, chopped","1 onion, chopped","4 cloves garlic, minced","6 cups water","1 bunch string beans (sitaw), cut","1 bunch pechay or bok choy","2 tbsp fish sauce","2 tbsp cooking oil","Salt and pepper to taste"],"steps":["Heat oil. Sauté garlic and onion until soft. Add tomatoes and cook until they soften and release juice.","Add pork and cook until meat turns light brown.","Pour in water. Bring to a boil. Skim off any scum. Lower heat and simmer for 45 minutes until pork is tender.","Add string beans. Cook for 3–5 minutes.","Add pechay/bok choy. Turn off heat. Cover and let residual heat cook the greens.","Season with fish sauce, salt, and pepper. Serve hot."],"id":"r009"},{"title":"Batchoy Tagalog","category":"main-pork","description":"A rich, traditional Filipino soup made with pork, liver, blood, and chili leaves. Savory, slightly spicy, and deeply nourishing. Different from the noodle batchoy of Iloilo, this one is soup-based without noodles.","ingredients":["1 lb pork loin or shoulder, sliced thinly","½ lb pork liver, sliced","½ cup fresh pork blood (optional)","1 onion, chopped","5 cloves garlic, minced","1 thumb ginger, julienned","6 cups water","2–3 tbsp fish sauce","3–4 pcs long green chili (siling pangsigang)","1 cup chili leaves (dahon ng sili) or malunggay","2 tbsp cooking oil","Salt and pepper to taste"],"steps":["Heat oil. Sauté garlic, onion, and ginger until fragrant.","Add pork slices and sauté until lightly browned.","Add liver and cook briefly until it changes color but don't overcook.","Pour in water. Bring to a boil. Lower heat and simmer 30 minutes until pork is tender.","Stir in pork blood (if using). Simmer for 5–8 minutes until it firms up.","Add green chili and chili leaves. Turn off heat immediately. The residual heat is enough to cook the leaves.","Season with fish sauce, salt, and pepper. Serve hot with rice."],"id":"r010"},{"title":"Bicol Express","category":"main-pork","description":"Rich and creamy dish from the Bicol region, pork belly simmered in coconut milk, shrimp paste, and plenty of chili peppers. Spicy, savory, and indulgent.","ingredients":["2 lbs pork belly, cut into thin cubes","2 tbsp cooking oil","1 large onion, chopped","6 cloves garlic, minced","2 tbsp bagoong alamang (shrimp paste)","2 cups coconut milk (gata)","1 cup coconut cream (kakang gata)","6–8 pieces green chili (siling haba), sliced","3–5 pieces siling labuyo (optional, for extra heat)","½ tsp ground black pepper"],"steps":["Heat oil in a pan. Sauté onion and garlic until soft and fragrant.","Add pork belly and cook until lightly browned.","Stir in shrimp paste and cook for 1 minute. Pour in coconut milk. Bring to a boil.","Lower heat and simmer for 30–40 minutes until pork is tender and liquid reduces.","Add coconut cream and chili peppers. Simmer for another 10–15 minutes until the sauce thickens and the oil starts to separate.","Season with pepper. Serve with plenty of hot rice."],"id":"r011"},{"title":"Pork BBQ Skewers","category":"main-pork","description":"Sweet, savory, and slightly smoky grilled pork on sticks is a Filipino favorite at fiestas and street stalls everywhere.","ingredients":["2 lbs pork shoulder, thinly sliced and pounded slightly","½ cup soy sauce","½ cup banana ketchup","¼ cup brown sugar","6 cloves garlic, minced","2 tbsp calamansi or lemon juice","1 tsp ground black pepper","1 tbsp sesame oil (optional)","Bamboo skewers (soaked in water)"],"steps":["In a bowl, mix soy sauce, ketchup, sugar, garlic, calamansi juice, pepper, and sesame oil until smooth.","Add pork slices and coat well. Marinate in the refrigerator for at least 3 hours or overnight.","Thread pork onto the soaked bamboo skewers.","Grill over medium-hot coals for 3–4 minutes per side, basting with leftover marinade.","Cook until caramelized and cooked through. Serve hot with rice or dipping sauce."],"id":"r012"},{"title":"Sisig","category":"main-pork","description":"Crispy, savory chopped pork face and belly on a sizzling plate. Kapampangan favorite!","ingredients":["1 lb pork belly","1 lb pork face/jowl","1 onion, minced","3 cloves garlic, minced","3 tbsp mayonnaise","2 tbsp calamansi juice","1 tbsp soy sauce","1 tsp liquid seasoning","Chili peppers to taste","Salt & pepper"],"steps":["Boil pork for 1 hour until tender. Grill or fry until crispy. Chop finely.","Sauté onion and garlic. Add chopped pork.","Stir in soy sauce, liquid seasoning, calamansi juice, and mayonnaise.","Serve on a sizzling plate with chilies and an egg on top."],"id":"r013"},{"title":"Pork Tocino","category":"main-pork","description":"Sweet, cured pork bright red and caramelized. The ultimate Filipino breakfast with rice and egg!","ingredients":["2 lbs pork shoulder, sliced thinly","½ cup brown sugar","¼ cup soy sauce","3 tbsp calamansi juice","4 cloves garlic, minced","1 tsp salt","¼ tsp prague powder (optional, for color)"],"steps":["Mix all marinade ingredients. Massage into pork thoroughly.","Pack tightly in a container. Cure in the fridge for 3–5 days.","To cook: Pan-fry with a little water until liquid evaporates, then oil comes out and pork caramelizes. Serve with garlic rice and egg."],"id":"r014"},{"title":"Pork Pochero","category":"main-pork","description":"Hearty tomato-based stew with pork, bananas, and vegetables. Sweet-savory comfort food.","ingredients":["2 lbs pork, cubed","2 tbsp oil","1 onion, chopped","4 cloves garlic, minced","2 cups tomato sauce","2 cups water","2 potatoes, quartered","2 saba bananas, peeled","1 cup green beans","1 cup cabbage, chopped","Salt & pepper"],"steps":["Brown pork: set aside. Sauté onion and garlic.","Add tomato sauce and water. Return pork, simmer for 40 minutes.","Add potatoes and saba. Cook for 15 mins. Add beans and cabbage. Simmer for 5 more mins. Season well."],"id":"r015"},{"title":"Binagoongang Baboy","category":"main-pork","description":"Pork belly braised in shrimp paste. Salty, savory, and delicious with rice.","ingredients":["2 lbs pork belly, cubed","2 tbsp oil","1 onion, chopped","6 cloves garlic, minced","½ cup bagoong alamang (rinsed)","2 tomatoes, chopped","1–2 tbsp sugar","3 bay leaves","5 siling labuyo","¼ cup vinegar","2 cups water"],"steps":["Brown pork in oil; set aside. Sauté onion and garlic.","Add bagoong and tomatoes. Cook for 2 minutes until soft.","Return pork. Add sugar, bay leaves, chili, vinegar, and water.","Bring to boil, lower heat. Simmer for 30–45 minutes until tender. Serve with rice."],"id":"r016"},{"title":"Pork Sinantomas","category":"main-pork","description":"Pork and tomatoes braised until meltingly tender. Simple but incredibly flavorful.","ingredients":["2 lbs pork belly, cubed","4 ripe tomatoes, chopped","1 onion, chopped","6 cloves garlic, crushed","¼ cup soy sauce","½ cup water","2 tbsp oil","Salt & pepper"],"steps":["Brown pork: set aside. Sauté garlic, onion, and tomatoes until soft.","Return pork. Add soy sauce and water. Simmer for 45–60 mins until pork is tender and the sauce thickens. Season to taste."],"id":"r017"},{"title":"Pork Asado","category":"main-pork","description":"Sweet and savory braised pork. Chinese-Filipino favorite tender and flavorful.","ingredients":["2 lbs pork shoulder or belly","¼ cup soy sauce","¼ cup hoisin sauce","2 tbsp oyster sauce","¼ cup brown sugar","6 cloves garlic, crushed","1 star anise","1 cup water","2 tbsp oil"],"steps":["Brown pork on all sides. Add all sauces, sugar, garlic, star anise, and water.","Bring to a boil, lower heat, cover. Simmer for 1 hour until the pork is very tender.","Uncover, turn heat up, reduce sauce until thick and glossy. Slice and serve."],"id":"r018"},{"title":"Pork Guisanti","category":"main-pork","description":"Simple sautéed pork with onions and garlic quick, humble, and delicious.","ingredients":["1 lb pork belly or loin, sliced thin","2 tbsp oil","1 large onion, sliced","4 cloves garlic, minced","2 tbsp soy sauce","1 tbsp oyster sauce","¼ cup water","Pepper to taste"],"steps":["Sauté garlic until golden. Add onion, cook until soft.","Add pork, stir-fry until no longer pink.","Add soy sauce, oyster sauce, and water. Simmer for 5–8 minutes until the pork is tender and the sauce coats the meat."],"id":"r019"},{"title":"Pork Chop Stew","category":"main-pork","description":"Tender pork chops simmered in rich tomato sauce with vegetables. Comfort on a plate.","ingredients":["4–6 pork chops","2 tbsp oil","1 onion, chopped","3 cloves garlic, minced","1 cup tomato sauce","1 cup water","2 potatoes, cubed","1 carrot, sliced","Salt & pepper","Flour for dusting"],"steps":["Season pork chops, dust lightly with flour. Brown in hot oil; set aside.","Sauté onion and garlic. Add tomato sauce and water. Return chops. Simmer for 25 mins.","Add potatoes and carrots. Simmer for 15 more mins until tender."],"id":"r020"},{"title":"Pork Giniling","category":"main-pork","description":"Seasoned ground pork with potatoes and carrots. Budget-friendly family meal.","ingredients":["1 lb ground pork","2 tbsp oil","1 onion, chopped","3 cloves garlic, minced","2 tomatoes, chopped","1 potato, diced","1 carrot, diced","½ cup frozen peas","2 tbsp soy sauce","¼ cup water"],"steps":["Heat oil in a pan over medium heat. Sauté onion until soft and translucent, then add garlic and cook until fragrant.","Add the ground pork. Break it apart with a spoon as it cooks, and stir-fry until it turns light brown and is no longer pink.","Add the chopped tomatoes. Cook for 2–3 minutes until they soften and release their juices.","Stir in the diced potato and carrot. Pour in the soy sauce and water. Cover the pan and simmer for 12–15 minutes until the vegetables are tender and the liquid reduces slightly.","Add the frozen peas. Cook for another 2–3 minutes.","Season with salt and pepper to taste. Serve hot with steamed rice."],"id":"r021"},{"title":"Pork and Bamboo Shoots Ginataan","category":"main-pork","description":"Creamy coconut milk stew tender pork and mild bamboo shoots with a gentle crunch. Unique and delicious!","ingredients":["500g pork belly, cubed","2 cups fresh or canned bamboo shoots, sliced and rinsed well","2 tbsp oil","1 onion, chopped","4 cloves garlic, minced","2 cups coconut milk","1 cup coconut cream","2 siling haba","Fish sauce to taste"],"steps":["Brown pork; set aside. Sauté onion and garlic.","Add bamboo shoots and cook for 3 minutes. Pour in coconut milk. Simmer for 20 minutes.","Add coconut cream, chilies, and pork. Simmer for 10 more minutes until the sauce thickens. Season with fish sauce. Serve with rice."],"id":"r022"},{"title":"Pata Tim (Braised Pork Hock)","category":"main-pork","description":"Pork hock slowly braised in soy sauce, vinegar, and spices until tender and flavorful. Dark, glossy, and delicious.","ingredients":["1 kg pork pata","½ cup soy sauce","⅓ cup cane vinegar","½ cup brown sugar","6–8 cups water","1 large onion, quartered","8 cloves garlic, crushed","2 bay leaves","1 tsp whole peppercorns","2 pieces star anise","2 saba bananas or bok choy (for serving)","1 tbsp cooking oil"],"steps":["Blanch the pork hock in boiling water for 5 minutes. Drain and rinse well. Pat dry.","Heat oil in a deep pot. Brown the pork on all sides over medium heat. Remove and set aside.","In the same pot, sauté garlic and onion until fragrant.","Return pork to the pot. Add soy sauce, vinegar, sugar, peppercorns, bay leaves, star anise, and water.","Bring to a boil. Lower heat, cover, and simmer for 1.5–2 hours until meat is tender.","Uncover and continue simmering for 20–30 minutes more until the sauce reduces and thickens.","Serve with steamed rice and blanched saba or bok choy on the side."],"id":"r023"},{"title":"Pepper Pork Belly","category":"main-pork","description":"Crispy pork belly coated in a glossy, peppery sauce. Savory, slightly sweet, and wonderfully peppery.","ingredients":["1 kg pork belly, cubed","3 tbsp cornstarch","1 egg, beaten","Oil for frying"],"steps":["Pat pork cubes dry. Toss with beaten egg, then coat lightly in cornstarch. Shake off excess.","Deep-fry pork in batches over medium-high heat until golden and crispy, about 6–8 minutes. Drain on paper towels.","Make the sauce: In a pan, melt butter. Sauté garlic and onion until fragrant.","Add water/broth, soy sauce, oyster sauce, sugar, and plenty of black pepper. Stir well and bring to a simmer.","Thicken with cornstarch slurry, stir until sauce bubbles and thickens.","Toss in the crispy fried pork. Stir quickly to coat everything evenly. Serve immediately while hot and crispy."],"id":"r024"},{"title":"Sinarsahang Pork Ribs","category":"main-pork","description":"Pork ribs simmered in a rich tomato and garlic sauce. Simple, hearty, and flavorful.","ingredients":["2 tbsp oil","1 onion, chopped","6 cloves garlic, minced","4 ripe tomatoes, chopped (or 1 cup tomato sauce)","1 cup water","2 tbsp soy sauce","1 tbsp fish sauce","1 tsp sugar","Salt & pepper to taste"],"steps":["Heat oil in a pot. Brown pork ribs on all sides; set aside.","In the same pot, sauté onion and garlic until soft. Add tomatoes and cook until they break down into a sauce.","Return ribs to the pot. Add water, soy sauce, fish sauce, and sugar.","Bring to a boil, lower heat, cover, and simmer for 45–60 minutes until ribs are tender.","Remove the lid and simmer for 10 minutes more to thicken the sauce. Season with salt and pepper to taste. Serve hot with rice."],"id":"r025"},{"title":"Pork Longganisa","category":"main-pork","description":"Filipino pork sausage can be sweet or garlicky. Perfect breakfast companion!","ingredients":["1 kg ground pork (with some fat)","¼ cup vinegar","6 cloves garlic, minced","3 tbsp brown sugar","1 tbsp salt","1 tsp black pepper","1 tbsp soy sauce","Hog casings or plastic wrap"],"steps":["Combine ground pork with all ingredients. Mix well until sticky. Let rest 1 hour for flavors to blend.","Form into sausages use casings or shape by hand on squares of plastic wrap, twisting the ends to seal.","Pan-fry over medium heat for 8–10 minutes, turning often, until cooked through and golden. Serve with rice and vinegar dip."],"id":"r026"},{"title":"Pork Sinigang sa Miso","category":"main-pork","description":"A twist on classic sinigang rich and creamy miso paste adds depth to the sour tamarind broth. Hearty and comforting.","ingredients":["1 kg pork belly or ribs, cubed","1 onion, quartered","2 tomatoes, quartered","6 cups water","1 pack sinigang mix","3 tbsp miso paste","1 cup radish, sliced","1 cup sitaw","1 cup eggplant, sliced","1 cup kangkong leaves","2 siling haba","Fish sauce to taste"],"steps":["Bring pork, onion, tomatoes, and water to a boil. Skim foam. Simmer for 45 minutes.","Stir in miso paste until fully dissolved. Add sinigang mix.","Add radish → sitaw → eggplant. Cook 3 minutes between each.","Add kangkong and chili. Turn off heat. Season with fish sauce. Serve hot."],"id":"r027"},{"title":"Pork Adobo sa Gata","category":"main-pork","description":"Creamy version of everyone's favorite adobo coconut milk transforms it into something rich and luxurious.","ingredients":["1 kg pork belly, cubed","½ cup soy sauce","⅓ cup vinegar","1 cup coconut milk","½ cup coconut cream","8 cloves garlic, crushed","2 bay leaves","1 tsp peppercorns","1 tbsp oil"],"steps":["Brown pork in oil. Add soy sauce, vinegar, garlic, bay leaves, and peppercorns. Do not stir.","Bring to a boil, lower heat, simmer for 30 minutes.","Pour in coconut milk. Simmer uncovered 20 minutes more, stirring occasionally.","Add coconut cream. Simmer for 10 minutes until sauce thickens and oil separates. Serve with rice."],"id":"r028"},{"title":"Pork and Pechay Stir-Fry","category":"main-pork","description":"Tender pork slices with fresh pechay in a light garlic-soy sauce. Quick and healthy.","ingredients":["500g pork loin, thinly sliced","1 bunch pechay, separated","2 tbsp oil","4 cloves garlic, minced","½ cup water","1 tbsp oyster sauce","1 tsp soy sauce","½ tsp cornstarch + 2 tbsp water"],"steps":["Heat oil. Brown pork slices quickly;set aside.","In the same pan, sauté garlic until fragrant. Add pechay stalks, stir-fry for 1 minute.","Return pork. Add water, oyster sauce, and soy sauce. Simmer for 2 minutes.","Add pechay leaves. Thicken with cornstarch slurry. Stir until sauce bubbles. Serve immediately."],"id":"r029"},{"title":"Crispy Pata Kare-Kare","category":"main-pork","description":"The best of both world's crispy fried pork hock served with rich, creamy peanut sauce.","ingredients":["1 kg pork pata (hock)","Oil for deep frying","## Peanut Sauce","¼ cup peanut butter","1 cup annatto water (or 1 tsp annatto powder dissolved in 1 cup water)","½ cup coconut milk or pork broth","2 tbsp cornstarch dissolved in ¼ cup water","Salt & pepper","Vegetables: Bok choy, pechay, string beans, eggplant, banana heart"],"steps":["Boil pork pata in salted water with garlic, peppercorns, and onion for 1.5–2 hours until tender. Drain and air-dry thoroughly (very important!).","Deep-fry over medium-high heat until golden and crispy. Set aside.","Make the sauce: Simmer annatto water, coconut milk, and peanut butter. Stir until smooth. Thicken with cornstarch slurry. Season.","Blanch or steam the vegetables until tender-crisp.","Place crispy pata on a platter. Arrange vegetables around it. Pour hot peanut sauce over the meat. Serve with bagoong on the side."],"id":"r030"},{"title":"Crispy Pata Dinakdakan","category":"main-pork","description":"Ilocano specialty crispy pork hock tossed in a spicy vinegar-onion sauce. Crispy, tangy, and bold!","ingredients":["1 kg pork pata","Oil for frying","## Sauce","½ cup cane vinegar","1 red onion, minced","4 cloves garlic, minced","2 tbsp ginger, minced","3–5 siling labuyo, chopped","1 tsp salt","½ tsp pepper","1 tbsp fish sauce","¼ cup pork broth (reserved from boiling)"],"steps":["Boil pork pata in salted water for 1.5 hours until tender. Drain, pat very dry, and air-dry for 1 hour.","Deep-fry until golden and super crispy. Drain and chop into pieces.","Make the sauce: Combine vinegar, onion, garlic, ginger, chilies, salt, pepper, fish sauce, and broth in a bowl. Mix well.","Toss the crispy pork in the sauce just before serving so it stays crunchy. Serve immediately."],"id":"r031"},{"title":"Quick Pan-fried Pork Chops","category":"main-pork","description":"Juicy, tender pork chops with a simple soy-calamansi glaze. Ready in 15 minutes! Perfect for busy weekdays.","ingredients":["4 pork chops","3 tbsp soy sauce","2 tbsp calamansi juice","1 tbsp brown sugar","3 cloves garlic, minced","¼ tsp pepper","1 tbsp oil"],"steps":["Marinate pork chops in soy sauce, calamansi juice, sugar, garlic, and pepper for 10–15 minutes.","Heat oil in a pan over medium heat.","Pan-fry pork chops for 3–4 minutes per side until golden and cooked through.","Pour any remaining marinade into the pan with 2 tbsp water. Simmer for 1 minute to make a quick sauce. Spoon over chops. Serve with rice."],"id":"r032"},{"title":"Igadu","category":"main-pork","description":"Ilocano classic tender pork and liver strips in a savory-sour sauce with bell peppers and peas. Colorful and flavorful.","ingredients":["500g pork loin or tenderloin, cut into thin strips","250g pork liver, cut into strips","2 tbsp oil","1 onion, chopped","4 cloves garlic, minced","½ cup bell peppers (red & green), sliced","¼ cup green peas","¼ cup vinegar","2 tbsp soy sauce","¼ cup water","Salt & pepper","Calamansi juice (toss liver in this first)"],"steps":["Toss liver in a little calamansi juice; set aside.","Heat oil. Sauté onion and garlic. Add pork strips and cook until lightly browned.","Add vinegar do not stir for 2 minutes. Add soy sauce and water. Simmer 10 minutes.","Add liver, bell peppers, and peas. Cook only 3–5 minutes so liver stays tender. Season well. Serve hot with rice."],"id":"r033"},{"title":"Pork Picadillo","category":"main-pork","description":"Savory minced pork with potatoes, carrots, and raisins. Like a Filipino-style hash  great for breakfast or any meal!","ingredients":["500g ground pork","2 tbsp oil","1 onion, chopped","4 cloves garlic, minced","2 tomatoes, chopped","1 potato, diced","1 carrot, diced","¼ cup raisins","¼ cup tomato sauce","¼ cup water","Salt & pepper"],"steps":["Heat oil. Sauté onion and garlic. Add ground pork and cook until browned.","Add tomatoes and cook until soft.","Stir in tomato sauce and water. Add potatoes, carrots, and raisins.","Simmer for 15 minutes until vegetables are tender and sauce thickens. Season well. Serve with rice or fried eggs."],"id":"r034"},{"title":"Crispy Bagnet","category":"main-pork","description":"The pride of Ilocos pork belly boiled then deep-fried until shatteringly crisp. Golden, bubbly, and irresistible!","ingredients":["1 kg pork belly slab","8 cups water","2 tbsp salt","1 tbsp peppercorns","6 cloves garlic, crushed","3 bay leaves","Oil for deep frying","## Dipping Sauce","2 medium tomatoes, chopped","1 small red onion, minced","2 tbsp soy sauce","2 tbsp cane vinegar","1 tsp sugar","1 siling labuyo, chopped (optional)"],"steps":["Place pork belly in a large pot with water, salt, peppercorns, garlic, and bay leaves. Bring to a boil.","Lower heat and simmer for 45–60 minutes until meat is tender but not falling apart. Do not overcook or it will be hard to fry.","Carefully remove pork from the water. Poke the skin all over thoroughly with a fork the more holes, the crispier it gets!","Rub about 1 teaspoon of salt all over the pork, especially on the skin.","Air-dry completely - this is the most important step! Place on a wire rack and let it air-dry for at least 2–3 hours, or overnight in the refrigerator if you have time. The skin must be completely dry for it to bubble and crisp up.","When ready, heat cooking oil in a deep pan or wok to medium heat (about 325°F/160°C). Carefully lower the pork belly into the oil.","Fry slowly for 15–20 minutes, turning occasionally, until the skin is golden brown, puffed up, and crispy all over. If the oil gets too hot, lower the heat.","Remove from oil and drain on a wire rack or paper towels for a few minutes.","Make the dipping sauce: In a small bowl, mix together the chopped tomatoes, minced onion, soy sauce, vinegar, sugar, and chili. Stir well.","Slice the bagnet into serving pieces while hot. Serve immediately with the dipping sauce on the side and plenty of steamed rice."],"id":"r035"},{"title":"Paksiw na Baboy","category":"main-pork","description":"Pork belly braised in vinegar, garlic, and peppercorns. Tangy, savory, and deeply flavorful, a classic Ilocano favorite.","ingredients":["1 kg pork belly, cubed","½ cup cane vinegar","¼ cup soy sauce","6 cloves garlic, crushed","1 onion, chopped","1 tsp peppercorns","2 bay leaves","1–2 tbsp brown sugar","1 cup water","2 tbsp oil","2 siling haba"],"steps":["Heat oil. Brown pork cubes on all sides; set aside.","In the same pot, sauté garlic and onion until fragrant.","Return pork. Add vinegar, soy sauce, peppercorns, bay leaves, sugar, water, and chilies. Do not stir for 2 minutes.","Bring to a boil. Lower heat, cover, and simmer for 45–60 minutes until pork is tender.","Uncover and simmer for 10 more minutes to thicken the sauce. Serve with hot rice."],"id":"r036"},{"title":"Pork Kilawin","category":"main-pork","description":"Ilocano specialty pork cooked in vinegar and spices without fire. Tangy, fresh, and spicy like a Filipino ceviche but with cooked pork.","ingredients":["1 kg pork belly or shoulder, boiled then cubed very small","½ cup cane vinegar","1 red onion, minced","6 cloves garlic, minced","2 tbsp ginger, minced","4–5 siling labuyo, chopped","1 tsp salt","½ tsp pepper","1 tbsp fish sauce","¼ cup pork broth (reserved from boiling)"],"steps":["Boil pork until tender. Drain, chop finely while hot. Let cool slightly.","In a bowl, whisk together vinegar, salt, pepper, fish sauce, and pork broth.","Add onion, garlic, ginger, and chilies. Mix well.","Toss in the warm pork. Stir thoroughly. Let it sit for 15–20 minutes before serving so the flavors absorb. Serve as pulutan or with rice."],"id":"r037"},{"title":"Pork Hamonado","category":"main-pork","description":"Sweet, pineapple-infused pork that melts in your mouth. Golden, tender, and kid-approved!","ingredients":["1 kg pork shoulder or belly, cubed","1 cup pineapple juice","½ cup brown sugar","¼ cup soy sauce","6 cloves garlic, crushed","1 onion, quartered","2 bay leaves","1 cup water","1 cup pineapple chunks","2 tbsp oil"],"steps":["Marinate pork in pineapple juice, soy sauce, garlic, and sugar for 1 hour.","Heat oil. Brown pork on all sides; set aside.","In the same pot, sauté onion. Return pork and pour in the marinade. Add water and bay leaves.","Bring to a boil. Lower heat, cover, and simmer 45–60 minutes until tender.","Add pineapple chunks. Simmer 10 more minutes uncovered until sauce thickens. Serve with rice."],"id":"r038"},{"title":"Pork Chop Steak","category":"main-pork","description":"Juicy pork chops simmered in a rich onion-soy sauce gravy. Tender, savory, and ready in 30 minutes!","ingredients":["4–6 pork chops","3 tbsp soy sauce","2 tbsp calamansi juice","4 cloves garlic, minced","¼ tsp pepper","2 tbsp oil","2 large onions, sliced into rings","½ cup water"],"steps":["Marinate pork chops in soy sauce, calamansi juice, garlic, and pepper for 15 minutes.","Heat oil. Pan-fry chops 3–4 minutes per side until golden; set aside.","In the same pan, sauté onion rings until soft and translucent. Add water and any remaining marinade. Simmer for 3 minutes.","Return pork chops to the pan. Simmer gently 3–5 minutes until cooked through and the sauce thickens slightly. Serve topped with onions and gravy."],"id":"r039"},{"title":"Spare Ribs Hamonado","category":"main-pork","description":"Pork ribs braised in sweet pineapple juice. Tender, fruity, and sticky.","ingredients":["1 kg pork spare ribs, cut into pieces","1 cup pineapple juice","½ cup brown sugar","¼ cup soy sauce","6 cloves garlic, crushed","1 cup water","1 cup pineapple chunks","2 tbsp oil"],"steps":["Marinate ribs in pineapple juice, soy sauce, and garlic for 1 hour.","Brown ribs in oil. Pour in marinade and water. Simmer for 45–50 minutes until tender.","Add pineapple chunks. Simmer for 10 more minutes until the sauce thickens. Serve with rice."],"id":"r040"},{"title":"Coke Pork Adobo","category":"main-pork","description":"A popular twist! Cola gives adobo a rich sweetness and beautiful caramel color. Surprisingly delicious.","ingredients":["1 kg pork belly, cubed","½ cup soy sauce","⅓ cup vinegar","1 cup Coca-Cola (regular)","6 cloves garlic, crushed","2 bay leaves","1 tsp peppercorns","1 tbsp oil"],"steps":["Brown pork; set aside. Sauté garlic.","Return pork. Add soy sauce, vinegar, Coke, bay leaves, and peppercorns. Do not stir.","Bring to a boil. Lower heat, simmer 45–60 minutes until tender and sauce reduces to a thick glaze. Serve with rice."],"id":"r041"},{"title":"Pork Tandoori-Style","category":"main-pork","description":"Filipino-style roasted pork marinated in yogurt and spices, then baked until tender and fragrant. A delicious fusion dish!","ingredients":["1 kg pork shoulder, cubed","½ cup plain yogurt","3 tbsp lemon or calamansi juice","6 cloves garlic, minced","1 tbsp ginger, grated","1 tbsp curry powder","1 tsp paprika","1 tsp cumin","1 tsp salt","½ tsp pepper","1 tbsp oil"],"steps":["Mix yogurt, lemon juice, garlic, ginger, and all spices. Add pork and coat well. Marinate for 2–4 hours.","Arrange on a baking sheet. Drizzle with oil.","Bake at 375°F (190°C) for 45–55 minutes until cooked through and edges are slightly charred. Serve with rice or flatbread."],"id":"r042"},{"title":"Pork Inasal","category":"main-pork","description":"Bacolod-style grilled pork bright, lemony, and garlicky. Basted with achuete oil for that beautiful golden glow!","ingredients":["1 kg pork shoulder or belly, cut into serving pieces","½ cup calamansi juice","¼ cup soy sauce","8 cloves garlic, minced","1 onion, minced","2 tbsp lemongrass, finely chopped","¼ cup brown sugar","1 tsp achuete powder dissolved in ¼ cup oil (for basting)","Salt & pepper"],"steps":["Mix calamansi juice, soy sauce, garlic, onion, lemongrass, sugar, salt, and pepper. Add pork and marinate for 3–4 hours or overnight.","Grill over medium-hot coals for 15–20 minutes per side, basting often with achuete oil, until cooked through and nicely charred. Serve with rice and soy-calamansi dip."],"id":"r043"},{"title":"Crispy Bagbagis (Crispy Pork Intestine)","category":"main-pork","description":"Deep-fried pork intestines are incredibly crispy and golden. A classic Filipino favorite pulutan!","ingredients":["1 kg pork intestines, cleaned thoroughly","8 cups water","3 tbsp salt","1 tbsp vinegar","6 cloves garlic","1 tbsp peppercorns","Oil for deep frying","Dip: vinegar + onion + chili + salt"],"steps":["Boil intestines in salted water with vinegar, garlic, and peppercorns for 45–60 minutes until tender. Drain very well.","Air-dry completely for 2–3 hours.","Deep-fry over medium-high heat until golden and very crispy. Drain.","Serve hot with spicy vinegar dip."],"id":"r044"},{"title":"Pork Baby Back Ribs Nilaga","category":"main-pork","description":"Simple boiled ribs soup nourishing, clear broth with corn and vegetables. Gentle and satisfying.","ingredients":["1 kg pork baby back ribs","8 cups water","1 onion, quartered","2 ears corn, cut into pieces","2 potatoes, cubed","1 cup cabbage, chopped","2 stalks celery, sliced","1 tsp whole peppercorns","Fish sauce to taste"],"steps":["Bring ribs and water to a boil. Skim off foam.","Add onion and peppercorns. Lower heat, simmer 45–60 minutes until tender.","Add corn and potatoes. Cook for 15 minutes. Add cabbage. Simmer for 5 more minutes. Season with fish sauce. Serve hot."],"id":"r045"},{"title":"Pork Belly in Oyster Sauce with Mushrooms","category":"main-pork","description":"Tender pork belly braised in a rich oyster sauce gravy with fresh mushrooms. Savory, earthy, and elegant.","ingredients":["1 kg pork belly, cubed","2 tbsp oil","1 onion, sliced","4 cloves garlic, minced","2 cups fresh mushrooms, halved","½ cup oyster sauce","¼ cup soy sauce","1 cup water","1 tsp sugar","1 tbsp cornstarch + 2 tbsp water (slurry)","Spring onions for garnish"],"steps":["Heat oil. Sear pork belly until golden brown. Set aside.","In the same pan, sauté garlic and onion. Add mushrooms and cook for 3–4 minutes.","Return pork. Add oyster sauce, soy sauce, sugar, water, bay leaves, and pepper. Bring to a boil.","Lower heat, cover, and simmer for 40–45 minutes until tender.","Stir in cornstarch mixture. Cook 2–3 minutes until the sauce thickens.","Garnish with spring onions. Serve hot with rice."],"id":"r046"},{"title":"Pork Parmesan","category":"main-pork","description":"Breaded pork cutlets topped with tomato sauce and melted cheese. Crispy, cheesy, and family-approved!","ingredients":["4 pork chops, pounded thin","½ cup breadcrumbs","¼ cup grated Parmesan cheese","½ cup flour","1 egg, beaten","1 cup tomato sauce","½ cup shredded mozzarella cheese","Oil for frying"],"steps":["Dredge pork in flour → dip in egg → coat in breadcrumbs mixed with Parmesan.","Pan-fry 3–4 minutes per side until golden. Place in a baking dish.","Top each with tomato sauce and mozzarella. Bake at 375°F (190°C) for 10–15 minutes until the cheese melts. Serve hot."],"id":"r047"},{"title":"Lechon Sisig","category":"main-pork","description":"The ultimate Kapampangan dish crispy lechon or pork belly chopped and tossed in a zesty, savory dressing. Sizzling hot!","ingredients":["500g crispy lechon kawali or roasted pork, chopped","1 large onion, minced","4 cloves garlic, minced","3 tbsp mayonnaise","2 tbsp calamansi juice","1 tbsp soy sauce","1 tsp liquid seasoning","2–3 siling labuyo, chopped","1 egg (optional topping)"],"steps":["Sauté onion and garlic until soft. Add chopped crispy pork. Toss 1–2 minutes.","Stir in mayonnaise, calamansi juice, soy sauce, liquid seasoning, and chilies. Mix well.","Transfer to a sizzling plate. Top with raw egg if desired. Serve immediately while hot and crispy!"],"id":"r048"},{"title":"Adobong Dilaw (Yellow Adobo)","category":"main-pork","description":"A distinct regional version turmeric gives it a beautiful golden color and earthy flavor. Tangy and savory!","ingredients":["1 kg pork belly, cubed","½ cup soy sauce","⅓ cup vinegar","1 tbsp turmeric powder","¾ cup water","8 cloves garlic, crushed","2 bay leaves","1 tbsp oil"],"steps":["Brown pork; set aside. Sauté garlic.","Mix soy sauce, vinegar, turmeric, and water. Pour into the pot. Add bay leaves. Do not stir. Bring to a boil.","Return pork. Simmer for 45–60 minutes until tender and the sauce thickens. Serve hot."],"id":"r049"},{"title":"Gising-Gising","category":"main-pork","description":"Gising-Gising means \"Wake up, wake up!\" a delicious vegetable dish cooked in creamy coconut milk, ground pork, shrimp paste, and spicy chilies. Traditionally made with winged beans (sigarilyas) or Baguio beans, it's rich, creamy, and just spicy enough to \"wake up\" your taste buds!","ingredients":["400g pork belly, cubed","2 tbsp oil","1 onion, chopped","4 cloves garlic, minced","2 tbsp bagoong alamang","2 cups coconut milk","1 cup coconut cream","2 cups sitaw, cut into 2-inch pieces","4–6 siling labuyo, chopped"],"steps":["Prepare the beans: Wash the sigarilyas or Baguio beans. Trim the ends and cut into 1-inch pieces. Set aside.","Sauté aromatics: Heat oil in a pan or wok over medium heat. Sauté onion until soft and translucent (about 3–5 mins). Add garlic and ginger and cook until fragrant, about 1 minute.","Cook the pork: Add ground pork. Break it apart with your spoon and cook until it turns light brown and is no longer pink (about 5–7 mins).","Add flavorings: Stir in the shrimp paste (bagoong alamang) and chopped chilies. Cook for 1–2 minutes until fragrant.","Pour coconut milk: Pour in the coconut milk. Bring to a gentle boil, then lower the heat. Simmer uncovered for about 8–10 minutes to let the flavors blend and the sauce thickens slightly. Stir occasionally.","Add the beans: Add your chopped sigarilyas or Baguio beans. Simmer for 5–7 minutes only, don't overcook! The beans should remain tender-crisp with a nice crunch, not mushy.","Finish & serve: Taste and adjust seasoning add more bagoong for saltiness or chilies for heat. Serve hot with plenty of steamed rice!","BEEF:"],"id":"r050"},{"title":"Bistek Tagalog (Filipino Beef Steak)","category":"main-beef","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g lean beef sirloin (sliced thinly)","1/3 cup calamansi juice","1/4 cup low-sodium soy sauce","2 large white onions (cut into rings)","4 cloves garlic (minced)","1/2 cup water","1 tbsp canola oil","freshly ground black pepper"],"steps":["Marinate sliced beef in calamansi juice, low-sodium soy sauce, garlic, and black pepper for at least 30 minutes.","Heat canola oil in a wide skillet over medium-high heat. Sear beef slices in batches for 1 to 2 minutes per side; remove and set aside.","In the same pan, sauté white onion rings for 2 minutes until tender-crisp; remove half for garnish.","Pour reserved marinade and water into the pan; bring to a simmer for 5 minutes.","Return seared beef to the skillet, simmer for 3 minutes until tender, and top with reserved onion rings before serving."],"note":"Acidic calamansi juice tenderizes lean beef cuts without needing high-fat marbling, while low-sodium soy sauce keeps blood pressure parameters controlled.","id":"r051"},{"title":"Beef Caldereta (Classic Tagalog Beef Stew)","category":"main-beef","prep":"20 mins","cook":"1 hr 15 mins","servings":"6","ingredients":["600g beef chuck or flank (cubed)","1 cup tomato sauce","2 tbsp liver spread","1/2 cup grated low-fat cheese","1 red bell pepper (chopped)","1 green bell pepper (chopped)","1 potato (cubed)","1 carrot (cubed)","1/2 cup pitted green olives","1 onion","4 cloves garlic","2 cups water","1 tbsp oil"],"steps":["Sear beef cubes in oil over medium-high heat until browned; set aside.","Sauté garlic and onion in the pan until translucent. Add tomato sauce, liver spread, and water; bring to a boil.","Return beef to the pot, cover, lower heat, and simmer for 45 to 50 minutes until meat is tender.","Add potatoes, carrots, olives, and bell peppers; cook for 15 minutes until vegetables are tender.","Stir in low-fat cheese until melted and incorporated into the thick sauce."],"note":"Rich source of heme iron and zinc from lean beef, combined with lycopene from tomato base and vitamin A from root vegetables.","id":"r052"},{"title":"Beef Mechado","category":"main-beef","prep":"20 mins","cook":"1 hr","servings":"5","ingredients":["600g lean beef round (sliced into thick chunks)","1 cup tomato sauce","3 tbsp soy sauce","3 tbsp calamansi juice","1 large potato (cubed)","1 red bell pepper (sliced)","1 onion (quartered)","3 bay leaves","1 tsp peppercorns","2 cups beef stock or water","1 tbsp oil"],"steps":["Marinate beef chunks in soy sauce and calamansi juice for 20 minutes.","Heat oil in a deep pot; sear beef chunks for 3 minutes until surface is browned.","Pour in tomato sauce, beef stock, marinade liquid, bay leaves, and peppercorns. Bring to a boil.","Lower heat, cover, and simmer for 40 to 45 minutes until beef is tender.","Add potatoes and bell peppers; simmer uncovered for 12 minutes until sauce thickens and potatoes are tender."],"note":"Trimming external fat cuts saturated fat content while preserving high biological value iron essential for oxygen transport.","id":"r053"},{"title":"Beef Nilaga (Boiled Beef Soup Main)","category":"main-beef","prep":"15 mins","cook":"1 hr 30 mins","servings":"6","ingredients":["700g beef shank or brisket","1 small cabbage (quartered)","1 bunch saba bananas (halved)","2 potatoes (quartered)","1 onion (quartered)","1 tsp whole peppercorns","8 cups water","sea salt to taste"],"steps":["Blanch beef in boiling water for 5 minutes; drain and rinse to remove impurities.","In a large pot, combine blanched beef, onion, peppercorns, and 8 cups of water. Bring to a boil, cover, reduce heat, and simmer for 1 hour until meat is tender.","Add potatoes and saba bananas; simmer for 15 minutes.","Add cabbage wedges, turn off heat, cover, and let steam for 3 minutes. Season with sea salt."],"note":"Clear broth method avoids added cooking oils; saba bananas provide resistant starch and potassium for electrolyte balance.","id":"r054"},{"title":"Beef Bulalo (Batangas Style Marrow & Shank Stew)","category":"main-beef","prep":"15 mins","cook":"2 hrs","servings":"6","ingredients":["1 kg beef shank with bone marrow","2 sweet cobs of corn (cut into thirds)","1 head cabbage (quartered)","1/2 lb Baguio beans","1 onion","1 tsp peppercorns","10 cups water","salt"],"steps":["Place beef shank in a deep stockpot with 10 cups of water, onion, and peppercorns.","Bring to a rolling boil, skimming off float impurities for the first 15 minutes.","Reduce heat to low, cover, and simmer for 1.5 to 2 hours until beef is fork-tender.","Add sweet corn pieces and cook for 15 minutes.","Fold in Baguio beans and cabbage; cook for 3 minutes. Season with salt."],"note":"High collagen broth supporting joint health; portioning bone marrow allows control over saturated lipid consumption.","id":"r055"},{"title":"Beef Pochero (Filipino Beef Stew with Plantains & Chickpeas)","category":"main-beef","prep":"20 mins","cook":"1 hr 15 mins","servings":"6","ingredients":["600g beef brisket (cubed)","2 ripe Saba bananas (sliced)","1 cup cooked chickpeas (garbanzos)","1 cup tomato sauce","1 bunch pechay","1 potato (cubed)","1 onion","3 cloves garlic","2 cups water","1 tbsp oil"],"steps":["Sauté garlic and onion in oil; add beef cubes and sear until lightly browned.","Pour in tomato sauce and water; simmer covered for 45 to 50 minutes until beef is tender.","Add potatoes, chickpeas, and saba plantain slices; cook for 12 minutes.","Fold in pechay leaves, remove from heat, and cover for 2 minutes before serving."],"note":"Chickpeas and plantains boost soluble dietary fiber and complex carbohydrates, promoting lower glycemic response.","id":"r056"},{"title":"Beef Pares (Braised Beef Stew)","category":"main-beef","prep":"20 mins","cook":"1 hr 20 mins","servings":"5","ingredients":["600g beef flank/brisket (cubed)","2 star anise","3 tbsp low-sodium soy sauce","2 tbsp brown sugar or stevia","1 thumb ginger (sliced)","4 cloves garlic (minced)","1 onion","3 cups beef stock","1 tbsp cornstarch","1 tbsp oil","scallions"],"steps":["Sauté ginger, garlic, and onion in oil until fragrant. Add beef and sear for 5 minutes.","Add soy sauce, star anise, brown sugar, and beef stock. Bring to a boil.","Lower heat, cover, and simmer for 1 hour until beef is melt-in-your-mouth tender.","Slurry cornstarch with 2 tbsp water; stir into boiling stew until sauce becomes thick and glossy. Garnish with scallions."],"note":"Star anise and ginger provide natural bioactive compounds that aid gastric motility when consuming dense red meat.","id":"r057"},{"title":"Beef Tapa (Homemade Lean Beef Tapa)","category":"main-beef","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["500g lean beef sirloin (sliced paper-thin)","3 tbsp cane vinegar","1 tbsp low-sodium soy sauce","6 cloves garlic (minced)","1/2 tsp black pepper","1/2 tsp sea salt","1 tbsp oil"],"steps":["Combine vinegar, low-sodium soy sauce, minced garlic, pepper, and sea salt in a glass container.","Marinate thin beef slices for at least 1 hour (or overnight in the refrigerator).","Heat oil in a non-stick skillet over high heat.","Stir-fry marinated beef slices rapidly for 4 to 5 minutes until liquid evaporates and meat edges turn lightly crisp."],"note":"Eliminating industrial sodium preservatives found in commercial tapa yields a high-protein breakfast or main course suitable for hypertension management.","id":"r058"},{"title":"Beef Kare-Kare (Peanut Stew with Lean Beef & Vegetables)","category":"main-beef","prep":"20 mins","cook":"1 hr 30 mins","servings":"6","ingredients":["600g beef chuck/tripe (cleaned and cubed)","1/2 cup natural unsweetened peanut butter","2 tbsp toasted rice flour","1 tbsp annatto seeds (soaked in 1/4 cup warm water for color)","1 eggplant (sliced)","1 bunch sitaw","1 banana blossom (sliced)","3 cups beef broth","sautéed bagoong on the side"],"steps":["Boil beef in 4 cups water for 1 hour until tender; reserve 3 cups broth.","In a deep pot, combine reserved beef broth, strained annatto water, and natural peanut butter; whisk until smooth.","Add cooked beef and toasted rice flour slurry; simmer over medium heat for 10 minutes until sauce thickens.","Steam eggplant, sitaw, and banana blossom separately; arrange over beef and peanut sauce before serving with light bagoong."],"note":"Natural unsweetened peanut butter delivers heart-healthy monounsaturated fats; steaming vegetables separately preserves thermolabile micronutrients.","id":"r059"},{"title":"Beef Morcon (Stuffed Beef Roll)","category":"main-beef","prep":"30 mins","cook":"1 hr 15 mins","servings":"6","ingredients":["600g beef flank steak (pounded thin into a flat sheet)","2 hard-boiled eggs (quartered)","1 carrot (cut into sticks)","2 hotdogs or sausage strips","2 dill pickles (sliced)","1 cup tomato sauce","1/4 cup soy sauce","2 tbsp calamansi juice","2 cups water","butcher twine"],"steps":["Marinate flat beef sheet in soy sauce and calamansi juice for 20 minutes.","Lay beef flat; arrange eggs, carrots, sausage, and pickles in the center.","Roll beef tightly into a cylinder and tie securely with butcher twine.","Sear rolled beef in a pot, pour tomato sauce and water, cover, and simmer for 1 hour until tender.","Remove twine, slice into rounds, and serve topped with reduced pot sauce."],"note":"High protein density dish providing a complete spectrum of essential amino acids, Vitamin B12, and iron.","id":"r060"},{"title":"Beef Asado (Kapampangan Braised Beef)","category":"main-beef","prep":"15 mins","cook":"1 hr 10 mins","servings":"5","ingredients":["600g beef round (cut into wide slabs)","1/2 cup tomato sauce","3 tbsp soy sauce","3 tbsp calamansi juice","1 bay leaf","1 potato (wedged)","1 white onion (sliced into rings)","1 tbsp oil"],"steps":["Marinate beef in soy sauce and calamansi juice for 30 minutes.","Pan-sear beef slabs in oil for 2 minutes per side; remove.","Add tomato sauce, bay leaf, marinade liquid, and 1.5 cups water to the pot. Bring to a boil.","Return beef, cover, and simmer over low heat for 55 minutes until tender.","Add potato wedges during the last 15 minutes. Garnish with fresh onion rings."],"note":"Citrus marination hydrolyzes dense muscle connective tissue, improving protein digestibility.","id":"r061"},{"title":"Beef Menudo","category":"main-beef","prep":"20 mins","cook":"50 mins","servings":"5","ingredients":["500g lean beef sirloin (diced small)","100g beef liver (diced small)","1 potato (diced)","1 carrot (diced)","1 red bell pepper (diced)","1 cup tomato sauce","1/2 cup green peas","1 onion","3 cloves garlic","1 tbsp oil"],"steps":["Sauté garlic and onion in oil; add diced beef and sear for 5 minutes.","Pour tomato sauce and 1 cup water; simmer covered for 30 minutes until beef is tender.","Add beef liver, potatoes, and carrots; simmer for 10 minutes.","Stir in red bell pepper and green peas; cook for 5 minutes until sauce thickens."],"note":"Incorporating beef liver supplies bioavailable heme iron, preformed Vitamin A (retinol), and B-complex vitamins.","id":"r062"},{"title":"Beef Stroganoff Tagalog Style","category":"main-beef","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g lean beef tenderloin (strips)","1 cup button mushrooms (sliced)","1/2 cup low-fat Greek yogurt or light cream","1 tbsp Worcestershire sauce","1 tbsp calamansi juice","1 onion","2 cloves garlic","1 tbsp oil","black pepper"],"steps":["Season beef strips with calamansi juice, pepper, and Worcestershire sauce.","Sauté garlic and onion in oil over high heat; add beef strips and sear quickly for 3 to 4 minutes.","Add sliced mushrooms and cook for 3 minutes.","Reduce heat to low, fold in low-fat Greek yogurt/light cream, and warm through for 2 minutes without boiling."],"note":"Substituting high-fat heavy cream with Greek yogurt reduces saturated fat while adding probiotic benefits and extra protein.","id":"r063"},{"title":"Beef Binallay / Sinantolan with Beef Strips","category":"main-beef","prep":"20 mins","cook":"30 mins","servings":"4","ingredients":["400g lean beef strips","2 cups fresh santol fruit pulp (grated and squeezed)","1 cup light coconut milk","2 green chilies","1 onion","3 cloves garlic","1 tbsp oil","salt"],"steps":["Sauté garlic and onion in oil; add beef strips and brown for 4 minutes.","Stir in grated santol pulp and toss for 3 minutes.","Pour light coconut milk and add green chilies; simmer covered over medium-low heat for 20 minutes until oil separates lightly and beef is tender. Season with salt."],"note":"Santol pulp provides high pectin and soluble fiber, creating a sour-savory profile rich in dietary fiber.","id":"r064"},{"title":"Beef Salpicao","category":"main-beef","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["500g beef tenderloin (cubed)","10 cloves garlic (minced)","2 tbsp Worcestershire sauce","1 tbsp low-sodium soy sauce","1 tbsp olive oil","1 tsp red pepper flakes","black pepper"],"steps":["Marinate beef cubes in Worcestershire sauce, soy sauce, and black pepper for 15 minutes.","Heat olive oil in a skillet over medium-low heat; fry half of the minced garlic until golden brown and crispy. Set crispy garlic aside.","Turn heat to high; add remaining garlic and beef cubes with marinade.","Sear rapidly for 3 to 4 minutes until beef is cooked to desired doneness. Top with crispy garlic."],"note":"Fast, high-heat searing retains intrinsic moisture in tenderloin while olive oil delivers monounsaturated fatty acids.","id":"r065"},{"title":"Beef Bicol Express","category":"main-beef","prep":"20 mins","cook":"40 mins","servings":"5","ingredients":["500g lean beef brisket (sliced into small strips)","1.5 cups light coconut milk","6 green long chilies (sliced)","2 red bird's eye chilies","1 tbsp sautéed bagoong (shrimp paste)","1 thumb ginger","1 onion","4 cloves garlic","1 tbsp oil"],"steps":["Sauté ginger, garlic, and onion in oil. Add beef strips and sear for 5 minutes.","Stir in bagoong and cook for 2 minutes.","Pour light coconut milk, add green and red chilies, and bring to a simmer.","Reduce heat to medium-low, cover, and cook for 30 minutes until beef is tender and coconut sauce reduces."],"note":"Capsaicin from red and green chilies stimulates metabolic rate and gastric secretions while light coconut milk manages overall lipid density.","id":"r066"},{"title":"Beef Rendang (Mindanao / Maranao Style)","category":"main-beef","prep":"25 mins","cook":"1 hr 30 mins","servings":"6","ingredients":["600g beef chuck (cubed)","1 cup toasted grated coconut (palapa/kerisik)","1.5 cups light coconut milk","2 stalks lemongrass","1 thumb galangal/ginger","1 thumb turmeric","4 cloves garlic","1 onion","chilies","salt"],"steps":["Blend lemongrass, galangal, turmeric, garlic, onion, and chilies into a spice paste.","In a deep pot, sauté spice paste until aromatic; add beef cubes and coat thoroughly.","Pour light coconut milk and simmer covered over low heat for 1 hour until beef is soft.","Stir in toasted grated coconut; cook uncovered, stirring continuously, until liquid evaporates and dark spice coating adheres to the beef."],"note":"Rich in turmeric curcumin and galangal polyphenols, offering powerful anti-inflammatory benefits in a dense protein format.","id":"r067"},{"title":"Beef Kulma (Tausug Spiced Beef Curry)","category":"main-beef","prep":"20 mins","cook":"1 hr 15 mins","servings":"5","ingredients":["600g beef sirloin (cubed)","1 cup light coconut milk","1/2 cup tomato sauce","1/4 cup unsweetened peanut butter","1 tbsp curry powder","1 cinnamon stick","1 onion","3 cloves garlic","1 tbsp oil","salt"],"steps":["Sauté garlic and onion in oil; add curry powder and cinnamon stick, toasting for 1 minute.","Add beef cubes and sear for 5 minutes.","Pour in tomato sauce, light coconut milk, and 1 cup water; simmer covered for 50 minutes until beef is tender.","Whisk in peanut butter and simmer for 10 minutes until sauce thickens into a rich gravy."],"note":"Unique combination of tomato lycopene, peanut monounsaturated fats, and spices providing high satiety and nutrient density.","id":"r068"},{"title":"Beef Pinakbet (Ilocano Style with Beef Strips)","category":"main-beef","prep":"20 mins","cook":"25 mins","servings":"5","ingredients":["300g lean beef strips","1 cup squash (cubed)","1 eggplant (sliced)","1 bunch sitaw","1 bittermelon/ampalaya (sliced)","1 okra (halved)","2 tomatoes","1 tbsp fish sauce or light bagoong","1 tbsp oil"],"steps":["Sear beef strips in oil until browned; remove and set aside.","In the same pan, sauté tomatoes and onion until soft. Add squash and 1/2 cup water; simmer for 5 minutes.","Add sitaw, ampalaya, eggplant, okra, and fish sauce.","Return seared beef to the pan, cover, and steam vegetables over medium heat for 10 minutes until tender-crisp."],"note":"Dense vegetable variety supplies a spectrum of phytonutrients, including charantin from ampalaya for blood glucose regulation.","id":"r069"},{"title":"Beef Chopsuey Main","category":"main-beef","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["300g lean beef tenderloin (thinly sliced)","1 cup cauliflower florets","1 carrot (sliced)","1 cup snow peas","1 bell pepper (sliced)","1 cup cabbage (chopped)","1 cup beef broth","1 tbsp cornstarch","1 tbsp low-sodium soy sauce","1 tbsp oil"],"steps":["Stir-fry beef slices in oil over high heat for 3 minutes; remove and set aside.","Sauté garlic and onion; add carrots and cauliflower with half the broth, cooking for 3 minutes.","Add snow peas, bell pepper, and cabbage.","Mix cornstarch, remaining broth, and soy sauce; pour into pan and simmer until thick. Fold in seared beef slices before serving."],"note":"Cruciferous vegetables deliver high dietary fiber and glucosinolates paired with easy-to-digest lean beef protein.","id":"r070"},{"title":"Beef Estofado","category":"main-beef","prep":"20 mins","cook":"1 hr 10 mins","servings":"5","ingredients":["600g beef shank/chuck (cubed)","2 ripe Saba bananas (sliced)","1 sweet potato (cubed)","1/3 cup cane vinegar","3 tbsp low-sodium soy sauce","2 tbsp sugar or stevia","1 bay leaf","1 tsp peppercorns","1 tbsp oil"],"steps":["Sear beef cubes in oil in a pot; add garlic, soy sauce, vinegar, bay leaf, and peppercorns.","Pour 2 cups of water, bring to a boil, then lower heat, cover, and simmer for 50 minutes until beef is tender.","In a separate skillet, lightly pan-fry saba banana slices and sweet potato cubes.","Add fried bananas and sweet potatoes to the beef stew with sugar; simmer uncovered for 10 minutes until sauce reduces."],"note":"Sweet potatoes and plantains provide potassium and complex carbohydrates to balance the savory-sweet braise.","id":"r071"},{"title":"Beef Hamonado","category":"main-beef","prep":"15 mins","cook":"1 hr 15 mins","servings":"5","ingredients":["600g beef round (cut into thick steaks)","1 cup unsweetened pineapple juice","1/2 cup pineapple tidbits","3 tbsp soy sauce","2 tbsp brown sugar or stevia","1 onion","3 cloves garlic","1 tbsp oil"],"steps":["Marinate beef in pineapple juice and soy sauce for 30 minutes.","Sear beef steaks in oil in a deep pot; set aside.","Sauté garlic and onion in the pot, pour in marinade and sugar, and bring to a boil.","Return beef, cover, and simmer over low heat for 50 minutes until tender.","Add pineapple tidbits and simmer uncovered for 10 minutes until sauce thickens into a glaze."],"note":"Pineapple juice bromelain breaks down tough beef collagen naturally while reducing refined sugar dependency.","id":"r072"},{"title":"Beef Halang-Halang (Spicy Visayan Beef Stew)","category":"main-beef","prep":"15 mins","cook":"45 mins","servings":"4","ingredients":["500g lean beef brisket (sliced)","2 thumbs ginger (julienned)","1.5 cups light coconut milk","3 long green chilies","2 red chilies (chopped)","2 cups papaya or chayote (cubed)","1 tbsp oil","salt"],"steps":["Sauté ginger, garlic, and onion in oil until highly aromatic.","Add beef slices and sear for 5 minutes.","Pour light coconut milk and 1 cup water; simmer covered for 30 minutes until beef is tender.","Add chayote/papaya cubes and chilies; cook for 10 minutes until vegetables are soft. Season with salt."],"note":"High ginger and chili concentration promotes circulation and metabolic rate, balanced by digestible protein.","id":"r073"},{"title":"Beef Sinampalukan (Beef in Tamarind Leaves)","category":"main-beef","prep":"20 mins","cook":"1 hr 15 mins","servings":"5","ingredients":["600g beef rib or brisket","1 cup fresh young tamarind leaves (sampalok leaves)","1 thumb ginger","2 tomatoes (quartered)","1 onion","2 green chilies","6 cups water","1 tbsp oil","salt"],"steps":["Sauté ginger, onion, and tomatoes in oil; add beef pieces and sear for 5 minutes.","Pour water and bring to a boil; cover and simmer for 50 minutes until beef is tender.","Add fresh tamarind leaves and green chilies; simmer for 10 minutes to release natural sour juice. Season with salt."],"note":"Young tamarind leaves offer fresh botanical acidity rich in Vitamin C and antioxidants without sodium additives.","id":"r074"},{"title":"Beef Pochero Fish-Style (Beef & Saba Stew)","category":"main-beef","prep":"15 mins","cook":"1 hr","servings":"4","ingredients":["500g lean beef sirloin (cubed)","2 Saba bananas","1 cup cabbage","1 carrot","1/2 cup garbanzo beans","1 cup tomato sauce","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Sear beef cubes in oil; add garlic, onion, tomato sauce, and 1.5 cups water.","Simmer covered for 40 minutes until beef is tender.","Add carrots, garbanzos, and sliced saba bananas; simmer for 10 minutes.","Add cabbage, turn off heat, cover, and steam for 3 minutes before serving."],"note":"Potent single-dish balance delivering complex carbohydrates, plant protein, and lean beef amino acids.","id":"r075"},{"title":"Beef Sarciado","category":"main-beef","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["500g beef sirloin (sliced)","3 ripe tomatoes (diced)","2 eggs (beaten)","4 cloves garlic","1 onion","1/2 cup water","1 tbsp oil","salt and pepper"],"steps":["Sear beef slices in oil for 4 minutes; remove and set aside.","In the same pan, sauté garlic, onion, and tomatoes until soft and juicy.","Pour in water and return beef; simmer for 15 minutes.","Pour beaten eggs evenly over the dish; let set slightly, then gently fold into the tomato gravy."],"note":"Combining beef with egg enrichment provides high choline levels and a complete essential amino acid score.","id":"r076"},{"title":"Beef Tausi (Beef in Salted Black Bean Sauce)","category":"main-beef","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g lean beef sirloin (sliced)","2 tbsp salted black beans (tausi, rinsed)","1 green bell pepper (sliced)","1 thumb ginger (julienned)","3 cloves garlic","1 onion","1 tbsp oyster sauce","1/2 cup water","1 tbsp oil"],"steps":["Stir-fry beef slices in oil over high heat for 3 minutes; remove and set aside.","In the same pan, sauté ginger, garlic, onion, and rinsed tausi for 2 minutes.","Pour in water and oyster sauce; add green bell pepper and simmer for 3 minutes.","Return beef slices to the pan and toss for 2 minutes until sauce coats the meat."],"note":"Rinsing fermented black beans cuts excessive sodium while preserving deep umami flavor and soy phytonutrients.","id":"r077"},{"title":"Beef Almondegas (Beef Meatballs with Patola & Misua)","category":"main-beef","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["300g lean ground beef","1 egg","2 tbsp whole wheat breadcrumbs","1 medium patola (sponge gourd, sliced)","50g misua noodles","5 cups beef broth","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Mix ground beef, egg, breadcrumbs, salt, and pepper; form into 12 small meatballs.","Sauté garlic and onion in oil in a pot; pour beef broth and bring to a boil.","Drop meatballs into boiling broth and cook for 8 minutes until they float.","Add patola slices and misua noodles; simmer for 3 minutes until noodles are tender."],"note":"Hydrating, digestible soup featuring fiber-rich patola gourd and controlled lean beef portioning.","id":"r078"},{"title":"Beef Tapa Skewers (Grilled Appetizer / Main)","category":"main-beef","prep":"20 mins","cook":"10 mins","servings":"4","ingredients":["500g beef sirloin (cubed)","3 tbsp calamansi juice","2 tbsp low-sodium soy sauce","4 cloves garlic (minced)","1 tsp honey","wooden skewers"],"steps":["Marinate beef cubes in calamansi juice, soy sauce, garlic, and honey for 1 hour.","Thread beef cubes onto soaked wooden skewers.","Preheat the grill or griddle pan to high heat.","Grill skewers for 2 to 3 minutes per side, basting with remaining marinade, until cooked through."],"note":"Portion-controlled skewer format limits total red meat intake while delivering high protein density.","id":"r079"},{"title":"Beef Tocino (Homemade Salt-Cured Beef)","category":"main-beef","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g lean beef sirloin (thinly sliced)","2 tbsp annatto water (for color)","2 tbsp cane sugar or stevia","1 tbsp coarse sea salt","1/4 tsp garlic powder","1/2 cup water","1 tbsp oil"],"steps":["Mix annatto water, sugar, sea salt, and garlic powder; rub thoroughly onto beef slices. Refrigerate for 24 hours.","Place marinated beef and 1/2 cup water in a pan; simmer over medium heat until water evaporates.","Add 1 tbsp oil and pan-fry beef slices for 3 to 4 minutes until caramelized."],"note":"Homemade curing avoids synthetic sodium nitrates and artificial red dyes found in commercial cured meats.","id":"r080"},{"title":"Beef Salpicao with Mushrooms","category":"main-beef","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["400g beef tenderloin (cubed)","1.5 cups fresh button mushrooms (halved)","8 cloves garlic (minced)","2 tbsp Worcestershire sauce","1 tbsp olive oil","black pepper"],"steps":["Marinate beef cubes in Worcestershire sauce and black pepper for 10 minutes.","Sauté half of the garlic in olive oil until golden brown; remove for garnish.","Add remaining garlic, beef cubes, and button mushrooms to the pan over high heat.","Stir-fry for 4 minutes until beef is seared and mushrooms are cooked. Top with crispy garlic."],"note":"Button mushrooms add ergothioneine antioxidants and dietary fiber while extending protein bulk without extra calories.","id":"r081"},{"title":"Beef Chop Suey with Broccoli","category":"main-beef","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["300g lean beef strips","2 cups broccoli florets","1 carrot (sliced)","1 bell pepper","1 cup beef broth","1 tbsp cornstarch","1 tbsp oyster sauce","1 tbsp oil"],"steps":["Sear beef strips in oil for 3 minutes; remove.","Stir-fry carrots and broccoli florets in the same pan with 3 tbsp water for 3 minutes.","Mix beef broth, cornstarch, and oyster sauce; pour into pan with bell pepper.","Simmer until thick, fold in seared beef strips, and serve warm."],"note":"Broccoli provides sulforaphane and Vitamin C, which increases non-heme and heme iron bioaccessibility.","id":"r082"},{"title":"Beef Patty in Mushroom Gravy","category":"main-beef","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["400g lean ground beef","1 egg","2 tbsp whole wheat breadcrumbs","1 cup mushrooms (sliced)","1 cup beef stock","1 tbsp flour","1 tbsp light butter","garlic and onion"],"steps":["Mix ground beef, egg, breadcrumbs, salt, and pepper; form into 4 thick patties.","Pan-sear patties in a non-stick skillet for 4 minutes per side; set aside.","Melt butter in the pan, add flour, and whisk for 1 minute. Slowly pour beef stock while whisking.","Add mushrooms and simmer for 3 minutes until gravy thickens; return patties to coat."],"note":"Lean ground beef patties provide portion-controlled protein enriched with whole grain binders.","id":"r083"},{"title":"Beef Teriyaki Tagalog","category":"main-beef","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["500g lean beef sirloin (thinly sliced)","3 tbsp low-sodium soy sauce","2 tbsp calamansi juice","2 tbsp honey","1 tsp sesame seeds","1 tsp sesame oil","1 tbsp oil"],"steps":["Whisk soy sauce, calamansi juice, and honey into a glaze.","Heat oil in a wok over high heat; stir-fry beef slices for 3 minutes.","Pour in glaze and toss rapidly for 2 minutes until beef is coated and sticky.","Drizzle with sesame oil and sprinkle toasted sesame seeds before serving."],"note":"Citrus calamansi balances sweet honey glaze, offering a local twist with controlled sodium parameters.","id":"r084"},{"title":"Beef Meatball Stew with Misua","category":"main-beef","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["350g lean ground beef","1 egg","50g misua noodles","1 cup patola or zucchini (sliced)","4 cups beef broth","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Form ground beef, egg, salt, and pepper into small meatballs.","Sauté garlic and onion in oil; pour beef broth and bring to a boil.","Drop meatballs into boiling broth and cook for 8 minutes.","Add zucchini/patola and misua noodles; cook for 3 minutes until tender."],"note":"Comforting, low-fat noodle soup suitable for convalescent care or easy protein digestion.","id":"r085"},{"title":"Beef Bicol Express (Mild Coconut Beef)","category":"main-beef","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["400g lean beef strips","1.5 cups light coconut milk","3 green chilies (sliced)","1 tbsp light bagoong","1 thumb ginger","1 onion","3 cloves garlic","1 tbsp oil"],"steps":["Sauté ginger, garlic, and onion in oil; add beef strips and sear for 4 minutes.","Add light bagoong and stir-fry for 2 minutes.","Pour light coconut milk and green chilies; simmer covered for 25 minutes until beef is tender and sauce reduces."],"note":"Moderate chili application provides metabolic stimulation while light coconut milk reduces overall saturated fat.","id":"r086"},{"title":"Beef Liver & Steak Sauté (Bistek Atay at Daging)","category":"main-beef","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["300g lean beef sirloin","200g beef liver (sliced)","1/3 cup calamansi juice","3 tbsp low-sodium soy sauce","2 white onions (sliced into rings)","4 cloves garlic","1 tbsp oil"],"steps":["Marinate beef steak and liver in calamansi juice, soy sauce, and pepper for 20 minutes.","Sear liver slices in oil for 2 minutes per side; set aside. Sear beef steak slices for 3 minutes; set aside.","Sauté onion rings in the pan for 2 minutes; add marinade liquid and 1/2 cup water, simmering for 4 minutes.","Return beef and liver to pan, toss for 2 minutes, and serve warm."],"note":"Exceptional micronutrient density delivering peak levels of Vitamin A, Vitamin B12, folate, and iron.","id":"r087"},{"title":"Beef Pastil (Maguindanao Shredded Beef)","category":"main-beef","prep":"20 mins","cook":"30 mins","servings":"5","ingredients":["500g beef flank (boiled and shredded)","4 cloves garlic (minced)","1 onion (minced)","1 thumb ginger (minced)","2 tbsp low-sodium soy sauce","1 tbsp oil","warm banana leaves for wrapping"],"steps":["Boil beef flank until soft; cool and shred finely using two forks.","Sauté ginger, garlic, and onion in oil until golden.","Add shredded beef and soy sauce; stir-fry continuously over medium-low heat for 15 minutes until dry and aromatic.","Serve spooned over steamed brown or white rice wrapped in wilted banana leaves."],"note":"Traditional Mindanao preservation method yields portion-controlled, high-protein seasoned meat.","id":"r088"},{"title":"Beef Adobo sa Patis","category":"main-beef","prep":"15 mins","cook":"50 mins","servings":"4","ingredients":["500g beef brisket (cubed)","1/3 cup cane vinegar","2 tbsp fish sauce (patis)","6 cloves garlic (crushed)","1 bay leaf","1/2 tsp peppercorns","1 cup water","1 tbsp oil"],"steps":["Combine beef, garlic, patis, vinegar, bay leaf, peppercorns, and water in a pot.","Bring to a boil uncovered for 5 minutes without stirring.","Cover, lower heat, and simmer for 40 minutes until beef is tender.","Add oil and simmer uncovered for 5 minutes to brown meat and reduce sauce."],"note":"Clear, soy-sauce-free adobo variant focusing on fish sauce umami and acetic acid tenderization.","id":"r089"},{"title":"Beef Adobo sa Puti (White Beef Adobo)","category":"main-beef","prep":"10 mins","cook":"50 mins","servings":"4","ingredients":["500g lean beef chuck (cubed)","1/2 cup cane vinegar","8 cloves garlic (crushed)","1 tsp peppercorns","2 green chilies","1 cup water","1 tsp sea salt","1 tbsp oil"],"steps":["Place beef, crushed garlic, peppercorns, salt, vinegar, and water in a wide pot.","Simmer uncovered over medium heat for 5 minutes.","Add green chilies, cover, reduce heat to low, and cook for 40 minutes until meat is tender.","Drizzle oil and sear meat lightly in the pan during the final 5 minutes."],"note":"Soy-free white adobo provides classic acetic tang while keeping sodium strictly controlled via sea salt measurement.","id":"r090"},{"title":"Roasted Beef with Local Herbs & Root Vegetables","category":"main-beef","prep":"20 mins","cook":"45 mins","servings":"5","ingredients":["600g beef tenderloin roast","2 sweet potatoes (cubed)","1 carrot (cubed)","2 stalks lemongrass (minced)","4 cloves garlic","1 tbsp olive oil","salt and pepper"],"steps":["Rub beef roast with olive oil, minced lemongrass, garlic, salt, and black pepper.","Arrange sweet potatoes and carrots around beef in a baking dish.","Roast in the oven at 200°C (400°F) for 35 to 45 minutes until internal beef temperature reaches 60°C (140°F for medium-rare).","Rest meat for 10 minutes before slicing thin; serve with roasted root vegetables."],"note":"Roasting lean tenderloin with olive oil and root crops delivers high protein alongside complex carbohydrates and beta-carotene.","id":"r091"},{"title":"Beef & Broccoli in Oyster Sauce","category":"main-beef","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["400g lean beef sirloin (thinly sliced)","3 cups broccoli florets","2 tbsp oyster sauce","1 tbsp low-sodium soy sauce","1 tbsp cornstarch","1 thumb ginger","1 tbsp oil"],"steps":["Marinate beef slices in soy sauce and cornstarch for 10 minutes.","Blanch broccoli florets in boiling water for 60 seconds; plunge into ice water and drain.","Stir-fry ginger and marinated beef in oil over high heat for 3 to 4 minutes.","Add oyster sauce and blanched broccoli; toss for 2 minutes until hot and coated."],"note":"High-fiber, nutrient-dense green vegetable pairing that aids digestion and enhances mineral absorption.","id":"r092"},{"title":"Crispy Baked Beef Cutlets","category":"main-beef","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g thin beef sirloin cutlets (pounded)","1/2 cup whole wheat breadcrumbs","1/4 cup cornstarch","1 egg (beaten)","1 tsp garlic powder","salt and pepper","cooking spray"],"steps":["Season beef cutlets with garlic powder, salt, and pepper.","Dredge in cornstarch, dip into beaten egg, and coat thoroughly with whole wheat breadcrumbs.","Arrange cutlets on a wire rack over a baking sheet; spray lightly with cooking spray.","Bake at 200°C (400°F) for 18 to 20 minutes until golden and crispy."],"note":"Oven-baking cutlets with whole wheat breadcrumbs provides a crispy coating with significantly less saturated fat than deep frying.","id":"r093"},{"title":"Beef Sinigang sa Mangga (Beef Sour Soup with Green Mango)","category":"main-beef","prep":"15 mins","cook":"1 hr 10 mins","servings":"5","ingredients":["600g beef brisket (cubed)","1 green unripe mango (peeled and grated)","1 bunch kangkong","1 radish (sliced)","1 onion","2 tomatoes","6 cups water","1 tbsp fish sauce"],"steps":["Boil grated green mango, onion, and tomatoes in 6 cups water for 15 minutes to create sour base.","Add beef brisket cubes; cover and simmer for 50 minutes until meat is tender.","Add sliced radish and cook for 5 minutes.","Fold in kangkong leaves, season with fish sauce, turn off heat, and cover for 2 minutes."],"note":"Raw green mango delivers natural Vitamin C and tartaric acids, replacing processed souring powders.","id":"r094"},{"title":"Beef Sinigang sa Bayabas (Beef in Guava Broth)","category":"main-beef","prep":"20 mins","cook":"1 hr 15 mins","servings":"5","ingredients":["600g beef rib or chuck","6 ripe guavas (peeled, quartered, seeded)","1 bunch kangkong","1 radish (sliced)","1 onion","6 cups water","1 tbsp fish sauce"],"steps":["Boil ripe guavas and onion in 6 cups of water for 20 minutes until soft.","Mash guavas in the pot and strain liquid through a sieve to extract pulp, discarding seeds.","Return guava broth to a boil, add beef, cover, and simmer for 50 minutes until tender.","Add radish and kangkong; season with fish sauce and cook for 3 minutes before serving."],"note":"Guava base provides exceptionally high natural Vitamin C and dietary fiber with a mild sweet-sour flavor profile.","id":"r095"},{"title":"Beef & Cabbage Stir-Fry Tagalog","category":"main-beef","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["350g lean ground beef or beef strips","3 cups green cabbage (shredded)","1 carrot (julienned)","1 onion","3 cloves garlic","1 tbsp low-sodium soy sauce","1 tbsp oil","black pepper"],"steps":["Sauté garlic and onion in oil; add ground beef and cook for 5 minutes until browned.","Add julienned carrots and low-sodium soy sauce; toss for 2 minutes.","Add shredded cabbage and black pepper; stir-fry over high heat for 3 to 4 minutes until cabbage is tender-crisp."],"note":"Economical, high-fiber main dish loaded with glucosinolates from cabbage and iron from lean beef.","id":"r096"},{"title":"Sizzling Beef Sisig (Low-Fat Plate)","category":"main-beef","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["400g lean beef flank (boiled and finely chopped)","1 red onion (diced)","2 green chilies (chopped)","2 tbsp light mayonnaise or Greek yogurt","2 tbsp calamansi juice","1 tbsp low-sodium soy sauce","1 tsp oil"],"steps":["Sauté chopped beef in a pan with 1 tsp oil over high heat for 4 minutes to crisp edges.","Add red onion, green chilies, soy sauce, and calamansi juice; toss for 2 minutes.","Remove from heat and stir in light mayonnaise or Greek yogurt until creamy.","Transfer to a hot plate and serve with fresh calamansi wedges."],"note":"Replaces high-fat pork offal sisig with lean beef flank and Greek yogurt, dropping saturated fat by over 60%.","id":"r097"},{"title":"Beef Stew with Kamote & Beans","category":"main-beef","prep":"15 mins","cook":"1 hr","servings":"5","ingredients":["500g beef chuck (cubed)","2 orange sweet potatoes (kamote, cubed)","1 cup Baguio green beans","1 cup tomato sauce","1 onion","2 cloves garlic","2 cups water","1 tbsp oil"],"steps":["Sear beef cubes in oil; add garlic, onion, tomato sauce, and water.","Simmer covered for 45 minutes until beef is tender.","Add sweet potato cubes and green beans; cook for 12 minutes until sweet potatoes are soft and sauce thickens."],"note":"Orange kamote provides rich beta-carotene (Vitamin A precursor) and complex carbohydrates to complement red meat protein.","id":"r098"},{"title":"Beef & Mushroom Mechado","category":"main-beef","prep":"20 mins","cook":"1 hr","servings":"5","ingredients":["500g lean beef sirloin (cubed)","1.5 cups fresh button mushrooms","1 cup tomato sauce","2 tbsp soy sauce","2 tbsp calamansi juice","1 potato (cubed)","1 onion","1 tbsp oil"],"steps":["Marinate beef in soy sauce and calamansi juice for 15 minutes.","Sear beef in oil; add tomato sauce and 1.5 cups water, simmering covered for 40 minutes.","Add potato cubes and fresh button mushrooms; simmer for 15 minutes until sauce reduces and potatoes are tender."],"note":"Mushrooms provide umami depth and beta-glucan fiber, lowering overall calorie density while maintaining satiety.","id":"r099"},{"title":"Broiled Beef Tenderloin with Calamansi Ponzu","category":"main-beef","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["500g beef tenderloin steaks (150g each)","1 tsp sea salt","1/2 tsp black pepper","3 tbsp low-sodium soy sauce","2 tbsp fresh calamansi juice","1 tsp grated ginger"],"steps":["Season tenderloin steaks with sea salt and black pepper.","Preheat the oven broiler or griddle pan to high heat.","Broil steaks for 4 to 5 minutes per side for medium-rare doneness.","Whisk low-sodium soy sauce, calamansi juice, and grated ginger; serve as a fresh ponzu dipping sauce alongside sliced beef."],"note":"Lean tenderloin broiling eliminates extra oil; citrus ponzu dip supplies active vitamin C and antioxidants without heavy gravy calories. CHICKEN:","id":"r100"},{"title":"Classic Chicken Adobo","category":"main-chicken","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["600g skinless chicken thigh cuts","4 tbsp cane vinegar","3 tbsp low-sodium soy sauce","6 cloves garlic (crushed)","1 tsp whole black peppercorns","2 dried bay leaves","1/2 cup water","1 tbsp vegetable oil"],"steps":["Combine chicken, garlic, soy sauce, peppercorns, and bay leaves in a bowl. Marinate for at least 20 minutes.","Heat oil in a pan; remove chicken from marinade and sear over medium-high heat until light brown.","Pour in remaining marinade and water. Bring to a boil.","Add cane vinegar, reduce heat, and simmer uncovered for 10 minutes without stirring.","Cover and simmer for an additional 15 minutes until chicken is tender and sauce reduces."],"note":"Skinless chicken thighs maintain moisture while significantly lowering saturated fat compared to traditional skin-on cuts.","id":"r101"},{"title":"Chicken Tinola (Ginger Broth with Papaya)","category":"main-chicken","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g chicken breast/thigh pieces","2 thumbs ginger (julienned)","4 cloves garlic","1 onion","1 green papaya (wedged)","2 cups malunggay (moringa) leaves","1 tbsp oil","4 cups rice washing or water","1 tbsp patis (fish sauce)"],"steps":["Sauté ginger, garlic, and onion in oil until fragrant.","Add chicken pieces and sear for 5 minutes; season with patis.","Pour in rice washing or water, bring to a boil, then simmer over low heat for 15 minutes.","Add green papaya wedges and cook for 8 minutes until tender.","Stir in malunggay leaves, turn off heat, cover, and let steam for 2 minutes before serving."],"note":"Rich in bioavailable iron, calcium, and gingerol to support digestion and immune function.","id":"r102"},{"title":"Chicken Afritada","category":"main-chicken","prep":"20 mins","cook":"30 mins","servings":"5","ingredients":["500g skinless chicken","2 medium potatoes (cubed)","1 carrot (cubed)","1 red bell pepper (sliced)","1 cup tomato sauce","1 cup water","1 onion","3 cloves garlic","1 bay leaf","1 tbsp oil","salt and pepper"],"steps":["Heat oil; pan-fry potatoes and carrots until edges are lightly browned. Set aside.","In the same pan, sauté garlic and onion. Add chicken and cook until no longer pink.","Pour in tomato sauce, water, and add bay leaf. Bring to a boil, then simmer for 20 minutes.","Add browned potatoes, carrots, and bell peppers. Simmer for another 8 minutes until sauce thickens."],"note":"Tomato paste and sauce deliver high levels of lycopene, an antioxidant enhanced by cooking in small amounts of heart-healthy oil.","id":"r103"},{"title":"Chicken Inasal (Bacolod Style Grilled Chicken)","category":"main-chicken","prep":"20 mins (plus marinating)","cook":"25 mins","servings":"4","ingredients":["600g chicken quarters","3 tbsp coconut vinegar","2 tbsp calamansi juice","2 tbsp lemongrass (minced)","1 thumb ginger (minced)","4 cloves garlic (minced)","1 tbsp annatto oil (for basting)","salt and pepper"],"steps":["Combine coconut vinegar, calamansi juice, lemongrass, ginger, garlic, salt, and pepper. Marinate chicken for at least 2 hours or overnight.","Preheat the grill or oven to medium-high heat.","Grill chicken for 10–12 minutes per side, basting frequently with annatto oil until fully cooked and lightly charred."],"note":"Grilling allows excess surface fat to drip away, while citrus-vinegar marinades help reduce heterocyclic amine (HCA) formation during cooking.","id":"r104"},{"title":"Chicken Pastel (Filipino Chicken Stew)","category":"main-chicken","prep":"20 mins","cook":"30 mins","servings":"5","ingredients":["500g chicken breast (cubed)","1/2 cup low-fat evaporated milk","1 carrot (sliced)","1 potato (cubed)","1/2 cup mushrooms (sliced)","1/2 cup green peas","1 tbsp butter","1 onion","salt and pepper"],"steps":["Melt butter in a pot; sauté onion and cubed chicken until chicken turns white.","Add carrots and potatoes with 1/2 cup water; cover and simmer for 15 minutes.","Stir in mushrooms, green peas, and low-fat evaporated milk.","Simmer gently over low heat for 8 minutes until sauce thickens. Season to taste."],"note":"Swapping heavy cream for low-fat evaporated milk preserves texture while controlling total caloric density.","id":"r105"},{"title":"Chicken Curry (Filipino Coconut Curry)","category":"main-chicken","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g skinless chicken thigh cuts","1.5 cups light coconut milk","1 tbsp yellow curry powder","1 red bell pepper (cubed)","1 potato (cubed)","1 carrot (cubed)","1 onion (chopped)","3 cloves garlic (minced)","1 thumb ginger (julienned)","1 tbsp oil","salt and pepper"],"steps":["Heat oil in a pan; brown potato and carrot cubes lightly, then remove and set aside.","Sauté garlic, onion, and ginger in the same pan until aromatic.","Add chicken pieces and cook until light golden on the outside.","Stir in curry powder until well coated, then pour light coconut milk. Bring to a simmer.","Add potatoes, carrots, and bell peppers. Cover and simmer over medium-low heat for 15 minutes until chicken and vegetables are tender. Season with salt and pepper."],"note":"Using light coconut milk combined with potassium-rich root vegetables balances fat content while maintaining a velvety sauce rich in anti-inflammatory turmeric.","id":"r106"},{"title":"Pininyahang Manok (Chicken in Pineapple Sauce)","category":"main-chicken","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g skinless chicken","1 cup unsweetened pineapple tidbits (reserve juice)","1/2 cup low-fat evaporated milk","1 red bell pepper (sliced)","1 carrot (sliced)","1 onion (diced)","3 cloves garlic (minced)","1 tbsp oil","salt and pepper"],"steps":["Marinate chicken in reserved pineapple juice for 15 minutes. Drain well.","Heat oil in a pot; sauté garlic and onion until soft, then add chicken and sear for 5 minutes.","Pour in pineapple juice and simmer covered for 12 minutes until chicken is tender.","Add carrots, bell peppers, pineapple tidbits, and low-fat evaporated milk. Simmer gently over low heat for 5 minutes without boiling vigorously."],"note":"Unsweetened pineapple provides natural bromelain enzymes that aid protein digestion while eliminating added refined sugars.","id":"r107"},{"title":"Chicken Binakol (Chicken in Coconut Water Broth)","category":"main-chicken","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g chicken cuts","3 cups fresh buko (young coconut) water","1 cup buko meat (strips)","1 green papaya (wedged)","2 thumbs ginger (julienned)","1 stalk lemongrass (bruised)","1 onion (sliced)","2 cups chili leaves or spinach","1 tbsp patis"],"steps":["In a pot, sear chicken with ginger, onion, and lemongrass for 5 minutes until chicken changes color.","Pour in fresh coconut water and bring to a boil. Reduce heat and simmer for 15 minutes.","Add green papaya wedges and simmer for 8 minutes until soft.","Stir in buko meat strips, chili leaves, and fish sauce. Turn off heat, cover, and let steam for 2 minutes before serving."],"note":"A hydrating, electrolyte-rich soup featuring natural potassium from coconut water with zero added cooking oils.","id":"r108"},{"title":"Chicken Asado (Kapampangan Style)","category":"main-chicken","prep":"15 mins (plus marinating)","cook":"35 mins","servings":"4","ingredients":["500g chicken cuts","3 tbsp calamansi juice","3 tbsp tomato paste","2 tbsp soy sauce","1 potato (quartered)","1 red onion (sliced)","3 bay leaves","1 cup water","1 tbsp oil"],"steps":["Marinate chicken in calamansi juice, soy sauce, and tomato paste for 30 minutes.","Fry potato quarters in oil until lightly golden; set aside.","Sauté onions in the remaining oil, then add chicken (reserve marinade) and brown slightly.","Pour in reserved marinade, water, and bay leaves. Simmer covered for 25 minutes until chicken is tender.","Add fried potatoes, simmer for 5 minutes until sauce thickens, and serve warm."],"note":"Citrus juice and tomato paste combine high vitamin C with lycopene, promoting tissue repair and cardiovascular support.","id":"r109"},{"title":"Chicken Piyanggang (Tausug Black Coconut Chicken)","category":"main-chicken","prep":"25 mins","cook":"35 mins","servings":"4","ingredients":["600g chicken cuts","1/2 cup burnt coconut paste (pamapa itum)","1 cup light coconut milk","2 thumbs ginger","2 stalks lemongrass","4 cloves garlic","1 onion","1 tbsp oil","salt"],"steps":["Pound ginger, garlic, onion, lemongrass, and burnt coconut paste into a smooth rub.","Coat chicken evenly with half of the spice paste and marinate for 20 minutes.","Heat oil in a deep skillet; sauté remaining paste until aromatic, then add chicken cuts.","Pour in light coconut milk and simmer covered over medium-low heat for 25 minutes until tender and dark sauce reduces."],"note":"Unique charcoal-roasted coconut paste delivers rich polyphenols and aromatic depth without requiring high sodium.","id":"r110"},{"title":"Chicken Halang-Halang (Spiced Coconut Chicken)","category":"main-chicken","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g chicken breast/thighs (chopped small)","1 cup light coconut milk","2 thumbs ginger (julienned)","3 green chili peppers (sliced)","1 red chili (minced)","1 stalk lemongrass (bruised)","1 onion","2 cups dahon ng sili (chili leaves)","1 tbsp oil"],"steps":["Sauté ginger, onion, and lemongrass in oil until fragrant.","Add chicken pieces and cook until the exterior turns white.","Pour light coconut milk and add sliced chilies. Simmer for 15 minutes over low heat.","Fold in green chili leaves, turn off heat, cover, and let steam 2 minutes before serving."],"note":"High capsaicin content from fresh chilies helps boost metabolic rate, complemented by anti-inflammatory gingerols.","id":"r111"},{"title":"Chicken Pochero","category":"main-chicken","prep":"20 mins","cook":"35 mins","servings":"5","ingredients":["600g chicken cuts","2 saba bananas (halved)","1 garbanzo beans can (drained)","1 carrot (sliced)","1 small cabbage (quartered)","1 cup tomato sauce","1 onion","2 cloves garlic","1 tbsp oil","2 cups water","salt"],"steps":["Pan-fry saba bananas in oil for 2 minutes per side until golden; remove and set aside.","Sauté garlic and onion in the pan. Add chicken cuts and sear for 5 minutes.","Add tomato sauce and water; simmer covered for 20 minutes.","Add carrots, garbanzo beans, and fried saba bananas; cook for 8 minutes.","Add cabbage quarters, turn off heat, cover pot, and let steam for 3 minutes."],"note":"Garbanzo beans deliver soluble plant fiber and low-GI complex carbohydrates that help stabilize post-meal glucose.","id":"r112"},{"title":"Chicken Mechado","category":"main-chicken","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g skinless chicken cuts","1 cup tomato sauce","1 potato (cubed)","1 bell pepper (sliced)","2 tbsp calamansi juice","2 tbsp soy sauce","1 onion","3 cloves garlic","1 bay leaf","1 tbsp oil","1 cup water"],"steps":["Marinate chicken cuts in calamansi juice and soy sauce for 15 minutes.","Lightly brown potato cubes in oil; set aside.","Sauté garlic and onion in remaining oil, then add chicken and cook for 5 minutes.","Add tomato sauce, water, and bay leaf. Simmer covered for 20 minutes until chicken is soft.","Toss in potatoes and bell peppers, cooking 5 minutes until sauce reduces to a thick glaze."],"note":"Citrus marinade tenderizes lean chicken protein while keeping added cooking fats low.","id":"r113"},{"title":"Chicken Guisado with Misua","category":"main-chicken","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["200g chicken breast (shredded)","2 bundles misua noodles","1 patola (sponge gourd, sliced)","4 cloves garlic (minced)","1 onion (chopped)","5 cups chicken broth","1 tbsp oil","patis and pepper"],"steps":["Heat oil in a pot; sauté garlic and onion until golden brown.","Add shredded chicken and stir-fry for 3 minutes until cooked through.","Pour in chicken broth and bring to a boil; lower heat and simmer for 5 minutes.","Add patola slices and misua noodles. Cook for 2 minutes until noodles soften. Season to taste."],"note":"Extremely soft, easy-to-digest comfort soup that pairs hydrating patola gourds with lean protein.","id":"r114"},{"title":"Chicken BBQ Skewers (Filipino Style)","category":"main-chicken","prep":"20 mins (plus marinating)","cook":"15 mins","servings":"4","ingredients":["500g boneless skinless chicken thighs (cubed)","3 tbsp cane vinegar","2 tbsp banana ketchup","1 tbsp soy sauce","4 cloves garlic (minced)","1 tbsp brown sugar","1 tsp black pepper","bamboo skewers"],"steps":["Whisk vinegar, banana ketchup, soy sauce, garlic, brown sugar, and pepper in a bowl.","Marinate chicken cubes for at least 1 hour. Thread onto soaked bamboo skewers.","Grill skewers over medium-hot coals or stove-top grill pan for 12–15 minutes, turning and basting occasionally with marinade until cooked through."],"note":"Portioned skewers paired with lean chicken thighs deliver controlled protein intake without heavy deep-frying.","id":"r115"},{"title":"Chicken Chopsuey","category":"main-chicken","prep":"20 mins","cook":"12 mins","servings":"5","ingredients":["250g chicken breast (sliced)","1 cup cauliflower florets","1 carrot (sliced)","1 cup snow peas","1 bell pepper","1 cup cabbage","1 cup chicken broth","1 tbsp cornstarch","1 tbsp oyster sauce","1 tbsp oil","garlic and onion"],"steps":["Heat oil in a wok; sauté garlic, onion, and sliced chicken breast until opaque.","Add hard vegetables (carrots, cauliflower) with 1/2 cup broth; cover and cook for 3 minutes.","Add snow peas, bell pepper, and cabbage.","Mix remaining broth with cornstarch and oyster sauce; pour into wok and toss rapidly over high heat for 2 minutes until sauce thickens."],"note":"High-density cruciferous vegetable stir-fry rich in glucosinolates, dietary fiber, and Vitamin C.","id":"r116"},{"title":"Chicken Menudo","category":"main-chicken","prep":"20 mins","cook":"30 mins","servings":"5","ingredients":["400g chicken breast (cubed)","100g chicken liver (cubed)","1 potato (cubed)","1 carrot (cubed)","1/2 cup raisin","1 cup tomato sauce","1 bell pepper","1 onion","2 cloves garlic","1 tbsp oil","salt and pepper"],"steps":["Sauté garlic and onion in oil, then add chicken breast and liver cubes. Cook for 5 minutes.","Add tomato sauce and 1/2 cup water; simmer covered for 15 minutes.","Toss in potatoes, carrots, raisins, and bell peppers.","Cook for 10 minutes over medium heat until vegetables are tender and sauce thickens. Season to taste."],"note":"Incorporating chicken liver boosts organic heme iron, Vitamin A, and folate density significantly.","id":"r117"},{"title":"Chicken Kaldereta","category":"main-chicken","prep":"20 mins","cook":"35 mins","servings":"5","ingredients":["600g chicken cuts","1 cup tomato sauce","2 tbsp liver spread","1 potato (cubed)","1 carrot (cubed)","1 red bell pepper (sliced)","1/2 cup green peas","1 chili (minced)","1 onion","3 cloves garlic","1 tbsp oil"],"steps":["Lightly sear potatoes and carrots in oil; remove and set aside.","Sauté garlic, onion, and minced chili in the pan, then add chicken cuts and brown slightly.","Add tomato sauce and 1 cup water; simmer for 20 minutes until chicken is tender.","Stir in liver spread, potatoes, carrots, bell pepper, and green peas. Simmer 8 minutes until the sauce is thick and glossy."],"note":"Liver spread adds richness, iron, and B-vitamins without needing heavy cream or excess butter.","id":"r118"},{"title":"Chicken Nilaga","category":"main-chicken","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g chicken cuts","1 small cabbage (quartered)","1 saba banana (sliced)","1 potato (quartered)","1 onion (quartered)","1 tsp peppercorns","5 cups water","patis to taste"],"steps":["Combine chicken cuts, onion, peppercorns, and water in a deep stockpot. Bring to a boil.","Lower heat and simmer covered for 15 minutes, skimming off surface foam.","Add potatoes and saba banana slices; simmer for 10 minutes until soft.","Add cabbage quarters and patis; turn off heat, cover, and let steam 3 minutes before serving."],"note":"Simple clear-broth preparation delivering gentle hydration, potassium from saba, and digestible protein.","id":"r119"},{"title":"Chicken Lugaw (Filipino Rice Porridge)","category":"main-chicken","prep":"10 mins","cook":"30 mins","servings":"4","ingredients":["1 cup jasmine rice","200g chicken breast (strips)","2 thumbs ginger (julienned)","4 cloves garlic (minced)","1 onion","6 cups chicken broth","1 tbsp oil","scallions and toasted garlic for garnish"],"steps":["Sauté ginger, garlic, and onion in oil until fragrant. Add chicken strips and cook for 3 minutes.","Add jasmine rice and stir for 2 minutes to toast grains slightly.","Pour chicken broth, bring to a boil, then reduce heat to low. Simmer covered for 25 minutes, stirring occasionally until rice grains break down into a thick porridge.","Garnish with scallions and toasted garlic."],"note":"Gentle macro profile offering easily absorbed complex carbohydrates and soothing gingerol for digestive rest.","id":"r120"},{"title":"Chicken Arroz Caldo","category":"main-chicken","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["1 cup glutinous rice (malagkit)","400g bone-in chicken cuts","2 thumbs ginger (julienned)","1 tsp safflower (kasubha)","4 cloves garlic","1 onion","6 cups water","2 boiled eggs","calamansi wedges"],"steps":["Sauté garlic, onion, and ginger in a pot. Add chicken cuts and cook until light brown.","Add glutinous rice and kasubha; stir-fry for 2 minutes.","Pour in water and bring to a boil. Lower heat and simmer for 25 minutes, stirring frequently until rice is thick and creamy.","Serve hot topped with sliced boiled egg, crispy garlic, and fresh calamansi juice."],"note":"Kasubha delivers bioflavonoids while fresh calamansi provides active Vitamin C to enhance non-heme iron absorption.","id":"r121"},{"title":"Chicken Sopas (Macaroni Soup)","category":"main-chicken","prep":"15 mins","cook":"25 mins","servings":"5","ingredients":["1 cup elbow macaroni","200g chicken breast (shredded)","1 carrot (diced)","1 cup cabbage (shredded)","1/2 cup low-fat evaporated milk","1 onion","2 cloves garlic","5 cups chicken stock","1 tbsp light butter"],"steps":["Sauté garlic and onion in light butter. Add shredded chicken and carrots; cook 3 minutes.","Pour in chicken stock and bring to a boil.","Add elbow macaroni and cook al dente for 8 minutes.","Add cabbage and low-fat evaporated milk. Simmer gently over low heat for 2 minutes without boiling. Season to taste."],"note":"Comforting recovery soup balancing protein and digestible carbohydrates with reduced saturated fat.","id":"r122"},{"title":"Chicken Embutido (Steamed Meatloaf)","category":"main-chicken","prep":"25 mins","cook":"45 mins","servings":"8","ingredients":["500g lean ground chicken","1/2 cup carrots (minced)","1/2 cup raisins","1/2 cup red bell pepper (minced)","2 eggs","1/4 cup breadcrumbs","2 hard-boiled eggs (sliced)","salt and pepper"],"steps":["Combine ground chicken, carrots, raisins, bell pepper, raw eggs, breadcrumbs, salt, and pepper in a bowl.","Spread mixture onto aluminum foil sheets. Arrange boiled egg slices along the center.","Roll foil tightly into log shapes and seal ends securely.","Steam over medium heat for 45 minutes. Cool completely before slicing."],"note":"Steaming lean poultry meatloaf avoids added cooking oils while hiding nutrient-dense vegetables inside.","id":"r123"},{"title":"Chicken Lumpia (Spring Rolls)","category":"main-chicken","prep":"30 mins","cook":"15 mins","servings":"6","ingredients":["400g lean ground chicken","1 cup carrots (minced)","1 cup jicama or bean sprouts (minced)","1 onion (minced)","1 egg","spring roll wrappers","1 tbsp oil for pan-frying"],"steps":["Mix ground chicken, carrots, jicama, onion, egg, salt, and pepper thoroughly.","Spoon 1 tbsp mixture onto lumpia wrapper, roll tightly, and seal edges with water.","Pan-fry or air-fry at 180°C for 12–15 minutes until golden brown and thoroughly cooked."],"note":"Air-frying or light pan-frying cuts total lipid absorption by over 60% compared to traditional deep frying.","id":"r124"},{"title":"Chicken Bola-Bola","category":"main-chicken","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["400g lean ground chicken","1/2 cup carrots (grated)","1/4 cup scallions (chopped)","1 egg","2 tbsp oat flour or cornstarch","1 tsp garlic powder","salt and pepper"],"steps":["Combine all ingredients in a mixing bowl until sticky and uniform.","Shape into 1.5-inch meatballs.","Pan-sear in a lightly greased non-stick skillet over medium heat for 10–12 minutes, turning frequently until golden brown."],"note":"Using oat flour increases soluble beta-glucan fiber while keeping meatballs bound cleanly without refined wheat flour.","id":"r125"},{"title":"Chicken Adobo sa Gata (Adobo in Coconut Cream)","category":"main-chicken","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["500g skinless chicken cuts","1 cup light coconut milk","4 tbsp cane vinegar","3 tbsp soy sauce","6 cloves garlic (crushed)","2 green chilies","2 bay leaves","1 tsp peppercorns"],"steps":["Marinate chicken in garlic, vinegar, soy sauce, bay leaves, and peppercorns for 20 minutes.","Simmer chicken and marinade in a pot for 15 minutes until tender.","Pour in light coconut milk and add green chilies.","Simmer uncovered for 15 minutes over low heat until sauce reduces to a rich coconut-adobo glaze."],"note":"Combining vinegar acidity with light coconut milk lowers fat density while delivering traditional creamy adobo flavor.","id":"r126"},{"title":"Chicken Skinless Longganisa","category":"main-chicken","prep":"20 mins (plus chilling)","cook":"12 mins","servings":"4","ingredients":["500g ground chicken","2 tbsp garlic (minced)","2 tbsp brown sugar","1 tbsp cane vinegar","1 tbsp soy sauce","1 tsp smoked paprika","1/2 tsp black pepper"],"steps":["Combine ground chicken with minced garlic, sugar, vinegar, soy sauce, paprika, and pepper.","Shape mixture into small sausage cylinders and chill for 1 hour to set shape.","Pan-fry in a non-stick skillet with 2 tbsp water over medium heat until water evaporates and sausages brown in their natural juices."],"note":"Skinless poultry preparation reduces saturated fat content by avoiding traditional pork fat trimmings.","id":"r127"},{"title":"Chicken Tapa","category":"main-chicken","prep":"15 mins (plus marinating)","cook":"10 mins","servings":"4","ingredients":["400g chicken breast (sliced thin)","4 cloves garlic (minced)","2 tbsp calamansi juice","2 tbsp low-sodium soy sauce","1 tsp brown sugar","1/2 tsp coarse black pepper"],"steps":["Combine garlic, calamansi juice, low-sodium soy sauce, sugar, and pepper in a bowl.","Marinate chicken breast slices for at least 4 hours or overnight.","Pan-sear marinated chicken strips in a lightly greased non-stick skillet over high heat for 3–4 minutes per side."],"note":"Low-sodium soy sauce and calamansi juice create a tangy cured flavor profile suitable for glycemic and hypertensive control.","id":"r128"},{"title":"Chicken Tocino (Homemade Salt-Cured)","category":"main-chicken","prep":"15 mins (plus curing)","cook":"15 mins","servings":"4","ingredients":["500g chicken thigh meat (skinless, boneless)","2 tbsp annatto oil","2 tbsp cane vinegar","2 tbsp honey or coco sugar","1 tsp sea salt","1 tsp garlic powder"],"steps":["Mix annatto oil, vinegar, honey, salt, and garlic powder in a sealable container.","Coat chicken pieces thoroughly and cure in the refrigerator for 24 hours.","Cook cured chicken in a pan with 1/2 cup water until liquid evaporates, then glaze in its own rendered juices for 3 minutes."],"note":"Natural annatto oil replaces artificial red food dyes (Allura Red) while honey replaces heavy refined white sugar.","id":"r129"},{"title":"Chicken Sisig (Low-Fat Grilled Chicken)","category":"main-chicken","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["400g grilled skinless chicken thighs (finely chopped)","1 red onion (diced)","2 green chilies (minced)","2 tbsp calamansi juice","1 tbsp light mayonnaise or Greek yogurt","1 tsp soy sauce"],"steps":["Grill chicken thighs until cooked through and lightly charred; chop finely.","Toss chopped chicken with diced red onion, green chilies, calamansi juice, soy sauce, and light mayonnaise/yogurt.","Transfer to a hot skillet for 2 minutes to serve sizzling."],"note":"Utilizing grilled lean thigh cuts and Greek yogurt reduces saturated fat by up to 70% compared to traditional pork head sisig.","id":"r130"},{"title":"Chicken Bistek (Filipino Beef Steak Style)","category":"main-chicken","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["500g chicken breast (sliced into cutlets)","3 tbsp calamansi juice","3 tbsp low-sodium soy sauce","2 large white onions (sliced into rings)","1 tbsp oil","1/2 cup water","pepper"],"steps":["Marinate chicken cutlets in calamansi juice, soy sauce, and pepper for 20 minutes.","Sauté onion rings in oil until translucent but crisp; remove half for garnish.","Add chicken slices to the pan and sear for 3 minutes per side.","Pour remaining marinade and water; simmer for 8 minutes until sauce reduces. Top with reserved onion rings."],"note":"High-protein, ultra-low-fat interpretation of a classic Filipino entree supporting lean muscle maintenance.","id":"r131"},{"title":"Chicken Stroganoff Tagalog","category":"main-chicken","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g chicken breast (strips)","1 cup mushrooms (sliced)","1/2 cup low-fat plain Greek yogurt","1 tbsp Worcestershire sauce","1 onion","2 cloves garlic","1 tbsp olive oil","parsley"],"steps":["Sauté garlic and onion in olive oil, then add chicken strips and cook until browned.","Add sliced mushrooms and Worcestershire sauce; cook for 4 minutes.","Turn heat to low and fold in low-fat Greek yogurt gently until warm (do not boil). Season with pepper and garnish with parsley."],"note":"Greek yogurt delivers a creamy sauce packed with probiotics and protein while eliminating heavy sour cream.","id":"r132"},{"title":"Chicken Guisado with Sayote","category":"main-chicken","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["200g chicken breast (sliced thin)","2 chayotes (sayote, peeled and sliced)","3 cloves garlic","1 onion","1 tomato (diced)","1 tbsp oil","1 cup water","salt and pepper"],"steps":["Heat oil; sauté garlic, onion, and tomato until soft.","Add chicken slices and cook for 4 minutes.","Add sayote slices and water; cover and simmer for 6–8 minutes until chayote is tender-crisp. Season with salt and pepper."],"note":"Low-calorie, high-water-content side stew rich in potassium and soluble fiber for digestive health.","id":"r133"},{"title":"Chicken Sotanghon Soup","category":"main-chicken","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["100g glass noodles (sotanghon)","200g chicken breast (shredded)","1 carrot (julienned)","1 tbsp annatto oil","4 cloves garlic (fried)","1 onion","5 cups chicken stock","scallions"],"steps":["Soak sotanghon noodles in cold water for 10 minutes; drain.","Heat annatto oil in a pot; sauté garlic and onion, then add shredded chicken.","Pour chicken stock and bring to a boil. Add carrots and soaked sotanghon noodles.","Simmer for 5 minutes until noodles are translucent. Serve topped with fried garlic and scallions."],"note":"Mung-bean-based glass noodles provide a gluten-free alternative with a lower glycemic response than refined wheat noodles.","id":"r134"},{"title":"Chicken Macaroni Salad (Filipino Style)","category":"main-chicken","prep":"20 mins","cook":"10 mins","servings":"6","ingredients":["2 cups elbow macaroni (cooked)","1 cup shredded cooked chicken breast","1/2 cup pineapple tidbits (drained)","1/2 cup carrots (diced small)","1/3 cup light mayonnaise","2 tbsp low-fat yogurt","salt and pepper"],"steps":["Boil macaroni in salted water until al dente; drain and cool completely.","In a large bowl, whisk light mayonnaise and low-fat yogurt together.","Fold in cooked macaroni, shredded chicken, carrots, and pineapple tidbits.","Chill in the refrigerator for 2 hours before serving."],"note":"Cutting mayonnaise with yogurt maintains traditional creaminess while drastically reducing overall caloric density.","id":"r135"},{"title":"Chicken Sinampalukan (In Tamarind Leaves)","category":"main-chicken","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["500g chicken cuts","1 cup fresh young tamarind leaves (dahon ng sampalok)","2 thumbs ginger (julienned)","1 onion","2 tomatoes","2 green chilies","5 cups water","1 tbsp oil"],"steps":["Heat oil; sauté ginger, onion, and tomatoes. Add chicken and sear for 5 minutes.","Pour water and bring to a boil. Lower heat and simmer for 20 minutes.","Add fresh tamarind leaves and green chilies; simmer for 8 minutes until sour flavor infuses into broth. Season with salt."],"note":"Fresh tamarind leaves impart an authentic sour flavor loaded with Vitamin C and natural fruit acids without commercial sodium packs.","id":"r136"},{"title":"Chicken Inihaw na Pecho","category":"main-chicken","prep":"15 mins (plus marinating)","cook":"20 mins","servings":"2","ingredients":["2 chicken breast quarters (pecho, skinless)","3 tbsp calamansi juice","2 tbsp soy sauce","1 tbsp garlic (minced)","1 tsp black pepper","1 tsp annatto oil (for basting)"],"steps":["Score chicken breast lightly; marinate in calamansi juice, soy sauce, garlic, and pepper for 1 hour.","Preheat an outdoor grill or ribbed pan to medium-high heat.","Grill chicken for 8–10 minutes per side, basting occasionally with annatto oil until internal temperature reaches 74°C (165°F)."],"note":"Ultra-lean protein source prepared with minimal basting fat, perfect for athletic macro requirements.","id":"r137"},{"title":"Chicken Salpicao","category":"main-chicken","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["400g chicken breast (cubed)","8 cloves garlic (minced)","2 tbsp Worcestershire sauce","1 tbsp low-sodium soy sauce","1 tbsp olive oil","1 tsp chili flakes","black pepper"],"steps":["Marinate cubed chicken in Worcestershire sauce, soy sauce, and black pepper for 15 minutes.","Heat olive oil in a skillet over medium-low heat; fry garlic until crispy and golden. Set aside half for garnish.","Turn heat to high; add chicken cubes and chili flakes. Stir-fry rapidly for 5–7 minutes until caramelized and tender. Top with crispy garlic."],"note":"Garlic delivers allicin for vascular support, while fast high-heat stir-frying seals in lean chicken juices.","id":"r138"},{"title":"Chicken Adobo sa Patis","category":"main-chicken","prep":"10 mins","cook":"30 mins","servings":"4","ingredients":["500g chicken cuts","4 tbsp cane vinegar","2.5 tbsp fish sauce (patis)","6 cloves garlic (crushed)","1 tsp whole peppercorns","2 bay leaves","1/2 cup water","1 tbsp oil"],"steps":["Sear chicken cuts and crushed garlic in oil for 5 minutes.","Add fish sauce, peppercorns, bay leaves, and water. Bring to a boil.","Pour cane vinegar; simmer uncovered for 10 minutes without stirring.","Cover and simmer 15 minutes longer until sauce reduces and coats chicken."],"note":"Clear adobo variation leveraging fish sauce for intense umami while avoiding soy allergens.","id":"r139"},{"title":"Chicken Relleno (Baked Stuffed Chicken)","category":"main-chicken","prep":"45 mins","cook":"1 hour","servings":"8","ingredients":["1 whole deboned chicken","300g ground chicken","1/4 cup ham (diced)","1/4 cup raisins","1/4 cup carrots (diced)","2 hard-boiled eggs","1 egg (beaten)","salt and pepper"],"steps":["Mix ground chicken, ham, raisins, carrots, beaten egg, salt, and pepper in a bowl.","Stuff half the mixture into deboned chicken. Place whole boiled eggs along the center, then add remaining stuffing.","Sew cavity shut with kitchen twine and truss legs.","Bake at 180°C (350°F) for 1 hour until golden brown and cooked through."],"note":"High-protein festive dish roasted without heavy frying batters, loaded with micronutrient-dense fillings.","id":"r140"},{"title":"Chicken Hamonado","category":"main-chicken","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["500g skinless chicken cuts","1 cup unsweetened pineapple juice","1/2 cup pineapple chunks","2 tbsp soy sauce","1 tbsp brown sugar","1 onion","2 bay leaves","1 tbsp oil"],"steps":["Sauté onion in oil, then sear chicken cuts for 5 minutes.","Add pineapple juice, soy sauce, brown sugar, and bay leaves.","Bring to a boil, cover, and simmer over low heat for 25 minutes until chicken is tender.","Stir in pineapple chunks and cook 5 minutes uncovered until sauce thickens into a sweet glaze."],"note":"Using unsweetened fruit juice creates a classic sweet-savory glaze with reduced refined sugars.","id":"r141"},{"title":"Chicken Patty with Gravy","category":"main-chicken","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["400g lean ground chicken","1 egg","1/4 cup breadcrumbs","1/2 onion (minced)","1 cup mushroom gravy (made with low-sodium chicken broth, cornstarch, and mushrooms)","1 tbsp oil"],"steps":["Mix ground chicken, egg, breadcrumbs, onion, salt, and pepper. Form into 4 thick patties.","Pan-sear patties in oil for 5 minutes per side until cooked through; transfer to platter.","In the same pan, simmer mushrooms, low-sodium broth, and cornstarch slurry until thick. Pour gravy over patties."],"note":"A lean poultry alternative to traditional beef salisbury steak with lower saturated fat.","id":"r142"},{"title":"Chicken Stir-Fry with Baguio Beans","category":"main-chicken","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["300g chicken breast (strips)","200g Baguio beans (green beans, trimmed)","3 cloves garlic","1 tbsp oyster sauce","1 tbsp soy sauce","1 tbsp sesame oil"],"steps":["Heat sesame oil in a wok; sauté garlic until fragrant.","Add chicken strips and stir-fry for 4 minutes until brown.","Toss in Baguio beans, oyster sauce, and soy sauce.","Stir-fry rapidly over high heat for 3–4 minutes until green beans are tender-crisp."],"note":"High-fiber side or main packed with silicon and Vitamin K from fresh snap beans.","id":"r143"},{"title":"Chicken Ginisang Upo","category":"main-chicken","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["200g chicken breast (diced)","1 medium upo (bottle gourd, peeled and cubed)","3 cloves garlic","1 onion","2 tomatoes (diced)","1 tbsp oil","1 cup water","salt"],"steps":["Sauté garlic, onion, and tomatoes in oil until softened.","Add diced chicken and cook for 4 minutes.","Add upo cubes and water. Cover and simmer for 8 minutes until bottle gourd becomes translucent and tender. Season to taste."],"note":"Ultra-low-calorie volume food high in water and potassium, perfect for weight management diets.","id":"r144"},{"title":"Chicken Tinola sa Gata","category":"main-chicken","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g chicken cuts","1 cup light coconut milk","2 thumbs ginger (julienned)","1 green papaya (wedged)","1 onion","2 cups dahon ng sili","1 tbsp oil","2 cups water","patis"],"steps":["Sauté ginger and onion in oil; add chicken cuts and cook for 5 minutes.","Pour in water and light coconut milk; bring to a light simmer.","Add green papaya wedges and cook for 10 minutes until tender.","Fold in green chili leaves, turn off heat, cover, and steam 2 minutes before serving."],"note":"Combines anti-inflammatory gingerol with medium-chain fats from light coconut milk to aid nutrient absorption.","id":"r145"},{"title":"Chicken Adobo sa Puti (White Vinegar Adobo)","category":"main-chicken","prep":"10 mins","cook":"35 mins","servings":"4","ingredients":["500g chicken cuts","1/2 cup white cane vinegar","8 cloves garlic (crushed)","1 tsp whole peppercorns","2 bay leaves","1 tsp sea salt","1/2 cup water","1 tbsp oil"],"steps":["Combine chicken, garlic, vinegar, salt, peppercorns, bay leaves, and water in a pot.","Bring to a boil, then reduce heat and simmer uncovered for 10 minutes.","Cover and simmer for 15 minutes longer until the chicken is tender.","Heat oil in a separate skillet; brown chicken cuts and garlic, then pour back reduced white vinegar broth."],"note":"Soy-free adobo variation ideal for individuals monitoring soy intake or sodium levels.","id":"r146"},{"title":"Chicken Pinakbet","category":"main-chicken","prep":"20 mins","cook":"25 mins","servings":"5","ingredients":["200g chicken breast (diced)","1 cup squash (cubed)","1/2 cup eggplant (sliced)","1/2 cup ampalaya (sliced)","1/2 cup sitaw","1 tbsp bagoong alamang (shrimp paste)","1 onion","2 cloves garlic","1 tbsp oil","1 cup water"],"steps":["Heat oil; sauté garlic, onion, and chicken breast until cooked.","Stir in shrimp paste and cook for 1 minute.","Add squash and water; simmer for 6 minutes until soft.","Add ampalaya, eggplant, and sitaw. Cover and cook over medium heat for 8 minutes until tender."],"note":"Diverse vegetable mix supplying beta-carotene, charantin for blood glucose control, and rich dietary fiber.","id":"r147"},{"title":"Chicken Laing (Chicken with Taro Leaves)","category":"main-chicken","prep":"15 mins","cook":"40 mins","servings":"4","ingredients":["200g chicken breast (diced)","50g dried taro leaves (dahon ng gabi)","1.5 cups light coconut milk","2 thumbs ginger (minced)","3 green chilies","1 onion","3 cloves garlic","1 tbsp shrimp paste"],"steps":["In a pot, combine light coconut milk, ginger, garlic, onion, shrimp paste, and chicken. Bring to a gentle simmer.","Add dried taro leaves on top (do not stir initially). Cover and simmer over low heat for 25 minutes.","Add green chilies and gently press leaves into liquid. Simmer 10 minutes until coconut milk renders oil slightly."],"note":"Taro leaves deliver calcium and magnesium, balanced by healthy fatty acids from light coconut milk.","id":"r148"},{"title":"Chicken Steak with Calamansi & Onions","category":"main-chicken","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g skinless chicken thigh cutlets","1/4 cup fresh calamansi juice","2 tbsp soy sauce","2 large onions (sliced into rings)","1 tbsp olive oil","black pepper"],"steps":["Marinate chicken thigh cutlets in calamansi juice, soy sauce, and black pepper for 20 minutes.","Heat olive oil in a skillet; pan-sear chicken cutlets for 4 minutes per side until cooked through. Remove to plate.","Add sliced onion rings to the pan juices and stir-fry for 2 minutes. Pour onion mix over chicken."],"note":"Vitamin C from fresh calamansi enhances tissue collagen synthesis alongside high-value poultry protein.","id":"r149"},{"title":"Chicken Bicol Express","category":"main-chicken","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g skinless chicken thigh (cubed)","1 cup light coconut milk","5 green chilies (sliced)","2 red chilies (minced)","1 tbsp bagoong alamang","2 thumbs ginger (minced)","4 cloves garlic","1 onion","1 tbsp oil"],"steps":["Sauté ginger, garlic, and onion in oil. Add chicken cubes and sear for 5 minutes.","Stir in bagoong alamang and cook for 1 minute.","Pour in light coconut milk and add green and red chilies.","Simmer over medium-low heat for 20 minutes until chicken is soft and sauce thickens."],"note":"Capsaicin-rich spicy coconut dish prepared with lean poultry to minimize saturated fat load. SEAFOODS:","id":"r150"},{"title":"Halabos na Hipon (Garlic Butter Steamed Shrimp)","category":"main-seafood","prep":"10 mins","cook":"8 mins","servings":"4","ingredients":["500g large white shrimp (head and shell on, cleaned)","4 cloves garlic (minced)","1 tbsp light butter","1/4 cup lemon-lime soda or water","1 tbsp calamansi juice","black pepper"],"steps":["Place shrimp, minced garlic, and soda/water in a wide skillet over medium-high heat.","Cook covered for 3 minutes until shrimp start to turn orange.","Toss in light butter, calamansi juice, and pepper; stir-fry for an additional 2 to 3 minutes until fully cooked."],"note":"High-protein, ultra-low-fat seafood option delivering rich zinc, selenium, and iodine.","id":"r151"},{"title":"Adobong Pusit (Filipino Squid Adobo)","category":"main-seafood","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["500g medium fresh squid (cleaned, ink sac reserved)","1/3 cup cane vinegar","2 tbsp soy sauce","5 cloves garlic (crushed)","1 onion (sliced)","1 tomato (diced)","1 tbsp oil","pepper"],"steps":["Sauté garlic, onion, and tomato in oil until soft.","Add squid, vinegar, soy sauce, reserved ink, and pepper.","Simmer uncovered over high heat for 5 to 7 minutes until squid is tender (avoid overcooking to prevent rubbery texture)."],"note":"Natural squid ink contains antioxidants and bioavailable iron with minimal overall caloric impact.","id":"r152"},{"title":"Sinanglay na Tilapia/Seafood Wrap","category":"main-seafood","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["400g mixed seafood (shrimp, squid, fish fillets)","8 large mustard leaves or pechay leaves","1.5 cups light coconut milk","1 thumb ginger","1 onion","2 tomatoes","green chilies","salt"],"steps":["Mix seafood with diced tomatoes, onions, and ginger.","Wrap portioned seafood tightly inside pechay/mustard leaves.","Lay wrapped parcels in a skillet, pour light coconut milk, and add green chilies.","Simmer covered for 18 to 20 minutes until coconut milk thickens slightly and seafood is cooked through."],"note":"Steaming wrapped seafood inside leafy greens locks in moisture while maximizing dietary fiber intake.","id":"r153"},{"title":"Ginataan na Hipon at Kalabasa (Shrimp & Squash in Coconut Cream)","category":"main-seafood","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["300g medium shrimp","2 cups squash (cubed)","1 bunch sitaw (yardlong beans)","1 cup light coconut milk","1 thumb ginger","1 onion","2 cloves garlic","1 tbsp fish sauce"],"steps":["Sauté ginger, garlic, and onion; add light coconut milk and bring to a gentle boil.","Add squash cubes and cook covered for 8 minutes until soft.","Add sitaw and shrimp; season with fish sauce. Simmer for 5 minutes until shrimp turn pink."],"note":"Squash provides high doses of Vitamin A (beta-carotene) which works synergistically with coconut lipids for optimal absorption.","id":"r154"},{"title":"Gambas Especial (Filipino Spicy Garlic Shrimp)","category":"main-seafood","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["400g peeled shrimp","2 tbsp tomato paste","1 tbsp olive oil","8 cloves garlic (minced)","1 red bell pepper (diced)","2 red chilies (chopped)","1 tbsp calamansi juice","salt"],"steps":["Heat olive oil in a skillet over medium-low heat; add garlic and cook until light golden.","Add bell pepper, chilies, and tomato paste; stir for 2 minutes.","Turn heat to high, add shrimp and calamansi juice, and stir-fry for 3 to 4 minutes."],"note":"Heart-healthy monounsaturated fats from olive oil paired with high-protein shrimp and capsaicin.","id":"r155"},{"title":"Tahong sa Luya (Mussels in Ginger Broth Main)","category":"main-seafood","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["1 kg fresh mussels (beards removed, cleaned)","2 thumbs ginger (julienned)","1 onion","4 cloves garlic","2 cups spinach or dahon ng sili","4 cups water","1 tbsp oil","salt"],"steps":["Sauté ginger, garlic, and onion in oil in a large pot.","Add cleaned mussels and toss for 2 minutes.","Pour water, cover, and bring to a boil for 5 to 7 minutes until mussel shells pop open (discard unopened shells).","Fold in spinach leaves, remove from heat, and cover for 2 minutes before serving."],"note":"Mussels are one of the most concentrated marine sources of Vitamin B12, iron, and Omega-3 fatty acids.","id":"r156"},{"title":"Kilawin na Hipon at Pusit (Seafood Ceviche)","category":"main-seafood","prep":"20 mins","cook":"0 mins","servings":"4","ingredients":["200g poached shrimp","200g poached squid rings","1 cup cane vinegar","1 thumb ginger","1 red onion","2 green chilies","3 calamansi (juiced)","cucumber cubes","salt"],"steps":["Flash-poach shrimp and squid in boiling water for 60 seconds; drain and plunge into ice water.","Toss cooled seafood with ginger, red onion, chilies, cucumber, vinegar, and calamansi juice.","Chill in the refrigerator for 30 minutes before serving cold."],"note":"Ultra-clean, zero-added-fat seafood preparation ideal for low-calorie weight management protocols.","id":"r157"},{"title":"Sizzling Squid Rings (Filipino Style)","category":"main-seafood","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["500g squid rings","1 green bell pepper","1 red bell pepper","1 onion","2 tbsp oyster sauce","1 tbsp soy sauce","1 tsp chili flakes","1 tbsp canola oil"],"steps":["Stir-fry onions, bell peppers, and chili flakes in oil over high heat for 2 minutes.","Add squid rings, oyster sauce, and soy sauce.","Toss continuously over high heat for 3 to 4 minutes until the squid is just cooked. Serve immediately."],"note":"High protein density paired with crunchy bell peppers providing high Vitamin C content.","id":"r158"},{"title":"Ginisang Tahong at Sitaw (Mussels & String Beans Sauté)","category":"main-seafood","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["500g cooked mussel meat (shucked)","1 bunch sitaw (cut into 2-inch pieces)","2 tomatoes (diced)","4 cloves garlic","1 onion","1 tbsp fish sauce","1 tbsp oil"],"steps":["Sauté garlic, onion, and tomatoes in oil until soft.","Add sitaw and cook for 4 minutes with 3 tbsp water.","Add shucked mussel meat and fish sauce; stir-fry over high heat for 3 minutes until sitaw is tender-crisp."],"note":"High dietary fiber from sitaw complements the dense mineral content of shucked mussels.","id":"r159"},{"title":"Calamares Tagalog (Air-Fried Squid Rings)","category":"main-seafood","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["400g squid rings","1/2 cup cornstarch","1 tsp garlic powder","1 egg (beaten)","calamansi dip"],"steps":["Dredge squid rings in garlic-seasoned cornstarch, dip in egg, and lightly coat again.","Spray light oil on air-fryer basket; lay squid in a single layer.","Air-fry at 190°C for 8 to 10 minutes until light golden and crisp. Serve with calamansi vinegar."],"note":"Air-frying reduces fat absorption by over 70% compared to traditional commercial deep frying.","id":"r160"},{"title":"Halabos na Alimango (Steamed Mud Crabs)","category":"main-seafood","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["2 large mud crabs (cleaned and halved)","1/2 cup lemon-lime soda or water","4 cloves garlic (minced)","1 tbsp calamansi juice","sea salt and black pepper"],"steps":["Place cleaned crabs in a wide stockpot with garlic, soda/water, and calamansi juice.","Season lightly with sea salt and black pepper. Cover tightly with a lid.","Cook over medium-high heat for 12 to 15 minutes, tossing halfway through, until shells turn bright orange-red.","Serve hot with a side of garlic-vinegar dipping sauce."],"note":"Mud crabs provide high-quality lean protein, zinc, selenium, and copper with virtually zero added fat when steamed.","id":"r161"},{"title":"Ginatang Alimango at Kalabasa","category":"main-seafood","prep":"20 mins","cook":"25 mins","servings":"4","ingredients":["2 medium mud crabs (cleaned and split)","2 cups squash (cubed)","1 bunch sitaw (cut into 2-inch pieces)","1.5 cups light coconut milk","1 thumb ginger (julienned)","1 onion","3 cloves garlic","1 tbsp fish sauce"],"steps":["Sauté ginger, garlic, and onion in a pot; add light coconut milk and bring to a simmer.","Add squash cubes, cover, and cook for 8 minutes until tender.","Add crabs, sitaw, and fish sauce. Simmer for 12 to 15 minutes until crabs are fully cooked and the sauce reduces."],"note":"Combining squash beta-carotene with healthy medium-chain fats in coconut milk optimizes fat-soluble vitamin absorption.","id":"r162"},{"title":"Crab and Corn Stir-Fry Main","category":"main-seafood","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["300g lump crabmeat (cooked)","1.5 cups sweet corn kernels","1 red bell pepper (diced)","1/2 cup spring onions","4 cloves garlic","1 tbsp sesame oil","1 tbsp low-sodium soy sauce"],"steps":["Heat sesame oil in a wok; sauté garlic and red bell pepper for 2 minutes.","Add sweet corn kernels and stir-fry for 4 minutes over medium-high heat.","Gently fold in lump crabmeat and soy sauce, tossing for 3 minutes to heat through without breaking crab chunks. Garnish with spring onions."],"note":"Sweet corn delivers lutein, zeaxanthin, and complex fiber to balance the rich, mineral-dense crab protein.","id":"r163"},{"title":"Adobong Hipon (Shrimp Adobo)","category":"main-seafood","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["500g medium shrimp (heads trimmed)","1/3 cup cane vinegar","2 tbsp low-sodium soy sauce","6 cloves garlic (crushed)","1 bay leaf","1/2 tsp whole peppercorns","1 tbsp canola oil"],"steps":["Heat oil in a skillet and fry crushed garlic until light golden brown.","Add shrimp and sear for 2 minutes over high heat.","Pour in soy sauce, cane vinegar, bay leaf, and peppercorns.","Simmer uncovered for 5 to 7 minutes without stirring until vinegar cooks off and shrimp turn pink."],"note":"Vinegar-based cooking tenderizes shrimp while low-sodium soy sauce controls overall dietary sodium intake.","id":"r164"},{"title":"Relleno na Pusit (Stuffed Grilled Squid)","category":"main-seafood","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["4 large whole squids (cleaned)","2 tomatoes (diced)","1 red onion (diced)","1/4 cup spring onions","1 tbsp calamansi juice","salt and pepper"],"steps":["Combine diced tomatoes, red onions, spring onions, calamansi juice, salt, and pepper in a bowl.","Stuff mixture inside the squid bodies, securing top openings with toothpicks.","Grill over medium-high heat for 5 to 6 minutes per side until marked and opaque."],"note":"Stuffing squid with fresh, raw antioxidant vegetables retains internal moisture without requiring high-calorie oils.","id":"r165"},{"title":"Seafood Sinigang sa Sampalok","category":"main-seafood","prep":"15 mins","cook":"20 mins","servings":"5","ingredients":["200g shrimp","200g squid","200g white fish fillets","1 pack tamarind base (or fresh tamarind juice)","1 radish","1 bunch sitaw","1 bunch kangkong","2 tomatoes","1 onion","6 cups water"],"steps":["Bring water, tomatoes, and onion to a boil in a stockpot.","Add sliced radish and sitaw; simmer for 5 minutes.","Add tamarind base, white fish, shrimp, and squid; cook gently for 6 minutes.","Stir in kangkong leaves, remove from heat, cover, and steam for 2 minutes."],"note":"High-volume, hydrating soup base delivering complete amino acids with minimal total caloric load.","id":"r166"},{"title":"Seafood Kare-Kare (Shrimp, Squid, Mussels sa Mani)","category":"main-seafood","prep":"20 mins","cook":"25 mins","servings":"5","ingredients":["400g mixed seafood (shrimp, squid rings, mussels)","1/3 cup natural unsweetened peanut butter","1 tbsp annatto powder","1 eggplant (sliced)","1 bunch sitaw","1 banana blossom (sliced)","2 cups water","garlic and onion"],"steps":["Sauté garlic and onion; stir in annatto powder and 2 cups water.","Whisk in unsweetened peanut butter until smooth; simmer for 5 minutes.","Add eggplant, sitaw, and banana blossom; cook covered for 8 minutes.","Fold in mixed seafood and cook gently for 5 minutes until done. Serve with a small side of bagoong."],"note":"Replacing fatty pork cuts with seafood cuts saturated fat drastically while supplying heart-healthy monounsaturated fats from peanuts.","id":"r167"},{"title":"Seafood Paella Tagalog","category":"main-seafood","prep":"20 mins","cook":"35 mins","servings":"6","ingredients":["2 cups brown rice or short-grain rice","300g mixed seafood (shrimp, mussels, squid)","1/2 cup peas","1 red bell pepper (strips)","1 tbsp annatto oil","3.5 cups fish stock","garlic","onion","calamansi wedges"],"steps":["Sauté garlic and onion in annatto oil in a paellera or wide pan. Add rice and stir for 2 minutes.","Pour in fish stock, cover, and cook over medium-low heat for 20 minutes.","Arrange mixed seafood, peas, and bell pepper strips over the top of the rice.","Cover tightly and cook for another 10 to 12 minutes until rice is soft and seafood is cooked. Serve with calamansi."],"note":"Brown rice boosts dietary complex fiber while mixed seafood delivers essential trace minerals.","id":"r168"},{"title":"Sautéed Clams in Sweet Chili Sauce","category":"main-seafood","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["1 kg fresh clams (purged)","2 tbsp sweet chili sauce","1 thumb ginger (minced)","4 cloves garlic","1 red chili","1 tbsp oil","1/2 cup water"],"steps":["Sauté ginger, garlic, and red chili in oil until aromatic.","Add purged clams and toss for 1 minute over high heat.","Add water and sweet chili sauce; cover pot and cook for 5 to 7 minutes until all shells open."],"note":"Clams are exceptionally rich in bioavailable heme iron and Vitamin B12, supporting red blood cell formation.","id":"r169"},{"title":"Curried Seafood Medley","category":"main-seafood","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g mixed seafood (fish fillets, shrimp, squid)","1.5 tbsp yellow curry powder","1 cup light coconut milk","1 bell pepper","1 carrot","1 thumb ginger","garlic","onion","1 tbsp oil"],"steps":["Sauté garlic, onion, and ginger in oil. Add curry powder and toast for 1 minute.","Add carrots and light coconut milk; simmer for 6 minutes.","Fold in mixed seafood and bell peppers; cook gently over medium heat for 6 to 8 minutes."],"note":"Curcumin paired with light coconut lipids provides anti-inflammatory benefit without elevated lipid counts.","id":"r170"},{"title":"Seafood Chopsuey Special","category":"main-seafood","prep":"20 mins","cook":"15 mins","servings":"5","ingredients":["300g mixed seafood (shrimp, squid)","1 cup broccoli florets","1 cup cauliflower florets","1 carrot (sliced)","1 cup snow peas","1 tbsp oyster sauce","1 tbsp cornstarch","garlic","onion","1 cup chicken/fish stock"],"steps":["Sauté garlic and onion in oil; stir-fry hard vegetables (carrots, cauliflower, broccoli) for 3 minutes.","Add stock and seafood; cover and simmer for 4 minutes.","Mix cornstarch and oyster sauce with 2 tbsp water; pour in and stir until sauce thickens. Toss in snow peas."],"note":"Micronutrient powerhouse offering dense cruciferous glucosinolates paired with lean sea protein.","id":"r171"},{"title":"Ginatang Pusit (Squid in Coconut Milk)","category":"main-seafood","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g fresh squid (cleaned and sliced)","1 cup light coconut milk","1 thumb ginger (julienned)","1 onion","2 green chilies","1 tbsp fish sauce","1 tbsp oil"],"steps":["Sauté ginger and onion in oil; add light coconut milk and bring to a simmer.","Add green chilies and simmer for 5 minutes.","Add squid and fish sauce; cook uncovered over high heat for 5 minutes until squid is tender."],"note":"Short cooking duration prevents squid protein toughing while preserving natural marine minerals.","id":"r172"},{"title":"Inihaw na Pusit (Barbecued Squid)","category":"main-seafood","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["500g whole large squids","3 tbsp cane vinegar","1 tbsp soy sauce","1 tsp garlic powder","black pepper","calamansi wedges"],"steps":["Marinate squids in vinegar, soy sauce, garlic powder, and pepper for 20 minutes.","Preheat the grill to high heat.","Grill squids for 3 to 4 minutes per side, basting with marinade, until lightly charred. Serve with calamansi."],"note":"Low-calorie grilled seafood offering robust umami flavor with negligible dietary fat.","id":"r173"},{"title":"Baked Tahong with Garlic & Herbs (Low-Fat Cheese)","category":"main-seafood","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["1 kg fresh mussels (cleaned and half-shelled)","6 cloves garlic (minced)","1/4 cup low-fat quick-melt cheese (grated)","1 tbsp light butter","1 tbsp fresh parsley (chopped)"],"steps":["Steam mussels for 3 minutes until opened; remove top shells and arrange half-shells on a baking sheet.","Mix light butter, minced garlic, and parsley; top each mussel with garlic mixture and grated low-fat cheese.","Bake at 200°C (400°F) for 6 to 8 minutes until the cheese is melted and bubbling."],"note":"Low-fat cheese substitution lowers saturated fat while providing calcium and high mussel zinc levels .","id":"r174"},{"title":"Seafood Bicol Express","category":"main-seafood","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g mixed seafood (shrimp, squid)","1.5 cups light coconut milk","4 green chilies (sliced)","2 red chilies (chopped)","1 thumb ginger","garlic","onion","1 tbsp bagoong alamang (shrimp paste)"],"steps":["Sauté ginger, garlic, onion, and bagoong alamang in a skillet for 2 minutes.","Pour in light coconut milk and chilies; simmer over medium-low heat for 8 minutes.","Fold in mixed seafood and cook for 5 to 7 minutes until seafood is done and sauce turns creamy."],"note":"Capsaicin from chilies boosts thermogenesis, while light coconut milk manages overall caloric density.","id":"r175"},{"title":"Shrimp and Broccoli Stir-Fry","category":"main-seafood","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["400g shrimp (peeled and deveined)","2 cups broccoli florets","4 cloves garlic (minced)","1 tbsp soy sauce","1 tbsp oyster sauce","1 tsp sesame oil","1 tbsp canola oil"],"steps":["Blanch broccoli florets in boiling water for 60 seconds; drain and plunge into ice water.","Heat canola oil in a wok; sauté garlic until fragrant. Add shrimp and cook 3 minutes.","Add blanched broccoli, soy sauce, oyster sauce, and sesame oil; stir-fry for 2 minutes."],"note":"High sulforaphane cruciferous broccoli content combined with high-protein lean shrimp.","id":"r176"},{"title":"Seafood Sotanghon Stew","category":"main-seafood","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["100g mung bean vermicelli (sotanghon, soaked)","300g mixed seafood","1 carrot (julienned)","1 cup cabbage","1 tbsp annatto water","4 cups fish stock","garlic","onion","patis"],"steps":["Sauté garlic and onion in oil; stir in annatto water for color.","Add carrots and fish stock; bring to a boil.","Add soaked sotanghon noodles and cook for 5 minutes.","Fold in mixed seafood and cabbage; simmer for 4 minutes until noodles are translucent and seafood is cooked."],"note":"Low-glycemic mung bean noodles provide sustained carbohydrate release.","id":"r177"},{"title":"Ginisang Halayhay (Local Clams Sautéed)","category":"main-seafood","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["1 kg fresh local clams (purged)","2 tomatoes (diced)","1 thumb ginger (sliced)","4 cloves garlic","1 onion","1 tbsp fish sauce","1 tbsp oil","1 cup dahon ng sili"],"steps":["Sauté garlic, ginger, onion, and tomatoes in oil until soft.","Add purged clams and fish sauce; stir for 2 minutes.","Add 1/2 cup water, cover pot, and boil for 5 minutes until clams open.","Stir in chili leaves, turn off heat, and cover for 1 minute before serving."],"note":"Chili leaves contribute calcium and iron to the clean, mineral-dense clam broth.","id":"r178"},{"title":"Nilasing na Hipon (Air-Fried Drunken Shrimp)","category":"main-seafood","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["400g small shrimp (heads trimmed)","2 tbsp cooking wine or white wine","1/2 cup cornstarch","1 tsp garlic powder","salt and pepper","oil spray"],"steps":["Marinate shrimp in cooking wine, salt, pepper, and garlic powder for 15 minutes.","Dredge shrimp lightly in cornstarch, shaking off excess.","Spray air-fryer basket with oil spray, lay shrimp in a single layer, and air-fry at 200°C for 8 to 10 minutes until crispy."],"note":"Air-frying delivers crispy shell textures with a fraction of the fat content of deep frying.","id":"r179"},{"title":"Seafood Marinara Tagalog","category":"main-seafood","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g mixed seafood (shrimp, squid, fish)","1.5 cups fresh tomato puree","4 cloves garlic","1 onion","1 tsp dried oregano","1 tbsp olive oil","fresh basil leaves"],"steps":["Sauté garlic and onion in olive oil until translucent.","Add tomato puree and oregano; simmer over medium-low heat for 10 minutes.","Add mixed seafood and simmer for 5 to 7 minutes until seafood is cooked.","Garnish with fresh basil leaves before serving."],"note":"Cooked tomato puree provides bioavailable lycopene supported by heart-healthy olive oil lipids.","id":"r180"},{"title":"Stuffed Crab Shells (Farced Crab / Relleno)","category":"main-seafood","prep":"25 mins","cook":"15 mins","servings":"4","ingredients":["4 empty crab carapaces","250g crabmeat","1/2 cup carrots (minced)","1/4 cup onions (minced)","1 egg (beaten)","2 tbsp breadcrumbs","salt and pepper","oil spray"],"steps":["Mix crabmeat, carrots, onions, beaten egg, breadcrumbs, salt, and pepper in a bowl.","Stuff filling firmly back into cleaned crab carapaces.","Spray light oil on stuffed shells and air-fry or bake at 190°C for 12 to 15 minutes until set and golden brown."],"note":"High protein-to-carbohydrate ratio enhanced with lean vegetable fillers.","id":"r181"},{"title":"Shrimp Patty with Sweet Chili Glaze","category":"main-seafood","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["400g minced shrimp","1/4 cup spring onions","1 egg white","2 tbsp cornstarch","1 tbsp sweet chili sauce","salt and pepper","1 tbsp oil"],"steps":["Mix minced shrimp, spring onions, egg white, cornstarch, salt, and pepper; form into 4 patties.","Pan-sear patties in oil over medium heat for 4 minutes per side.","Brush lightly with sweet chili sauce during final minute of cooking."],"note":"Egg white binding keeps fat levels exceptionally low while supplying complete protein.","id":"r182"},{"title":"Seafood Pancit Canton Main","category":"main-seafood","prep":"20 mins","cook":"15 mins","servings":"5","ingredients":["200g wheat flour noodles (canton)","300g mixed seafood","1 cup cabbage","1 carrot (sliced)","1/2 cup snow peas","2 tbsp low-sodium soy sauce","1 tbsp oyster sauce","3 cups fish stock","garlic and onion"],"steps":["Sauté garlic and onion; add seafood and cook for 3 minutes. Remove seafood and set aside.","Pour fish stock, soy sauce, and oyster sauce into pan; bring to a boil.","Add vegetables and canton noodles; simmer for 5 minutes until liquid is absorbed.","Fold cooked seafood back in, toss well, and serve hot with calamansi."],"note":"Combining ample vegetables with sea protein moderates the overall glycemic impact of wheat noodles.","id":"r183"},{"title":"Crab in Garlic Butter Sauce","category":"main-seafood","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["2 large mud crabs (cleaned and chopped)","8 cloves garlic (minced)","2 tbsp light butter","1/2 cup water","1 tbsp calamansi juice","black pepper"],"steps":["Melt light butter in a wok over medium heat; sauté minced garlic until fragrant and light golden.","Add crab pieces, water, and calamansi juice.","Cover and cook for 10 to 12 minutes, stirring occasionally, until crabs are orange and sauce clings to shells."],"note":"Portion-controlled light butter provides buttery flavor while controlling overall saturated fat intake.","id":"r184"},{"title":"Sizzling Gambas Plate","category":"main-seafood","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["400g shrimp (peeled)","1 red bell pepper (diced)","1 onion (diced)","6 cloves garlic (minced)","2 tbsp tomato sauce","1 red chili","1 tbsp olive oil"],"steps":["Heat olive oil in a skillet; sauté garlic, onion, and chili until fragrant.","Add diced bell peppers and tomato sauce; stir for 1 minute.","Add shrimp and toss over high heat for 3 to 4 minutes until pink. Transfer to a sizzling plate."],"note":"Heart-healthy olive oil paired with low-fat shrimp protein and metabolic-boosting chili.","id":"r185"},{"title":"Sweet & Sour Shrimp","category":"main-seafood","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["400g shrimp","1 red bell pepper","1/2 cup pineapple tidbits (drained)","3 tbsp vinegar","2 tbsp honey","1 tbsp tomato paste","1 tbsp cornstarch","garlic and onion"],"steps":["Sauté garlic, onion, and bell pepper for 2 minutes.","Add pineapple tidbits, vinegar, honey, tomato paste, and 1/2 cup water; simmer 3 minutes.","Add shrimp and cornstarch slurry; cook over medium-high heat for 4 minutes until sauce thickens and shrimp are done."],"note":"Pineapple bromelain aids digestion, while honey replaces refined table sugars.","id":"r186"},{"title":"Seafood Lomi Special","category":"main-seafood","prep":"20 mins","cook":"20 mins","servings":"5","ingredients":["200g thick egg noodles (lomi)","300g mixed seafood","1 cup cabbage","1 egg (beaten)","1 tbsp cassava starch (slurry)","5 cups fish stock","garlic and onion"],"steps":["Sauté garlic and onion; add seafood and cook for 3 minutes. Remove seafood.","Add fish stock to pot and bring to a boil; stir in lomi noodles and simmer 8 minutes.","Add cassava starch slurry to thicken broth; stir in beaten egg in a steady stream.","Fold cooked seafood and cabbage back in, simmer for 2 minutes, and serve hot."],"note":"High-protein, warming soup base offering dense hydration and balanced nutrients.","id":"r187"},{"title":"Ginatang Hipon sa Kamias","category":"main-seafood","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["400g shrimp","1 cup fresh kamias (sliced)","1 cup light coconut milk","1 thumb ginger","1 onion","2 green chilies","1 tbsp fish sauce"],"steps":["Bring light coconut milk, ginger, onion, and sliced kamias to a simmer in a pot.","Cook for 5 minutes until kamias softens and releases sour juice.","Add shrimp, green chilies, and fish sauce; simmer for 5 minutes until shrimp are pink."],"note":"Natural kamias tartness cuts through coconut lipids while delivering natural Vitamin C.","id":"r188"},{"title":"Stir-Fried Calamari with Snow Peas","category":"main-seafood","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["400g squid rings","1.5 cups snow peas (chicharo)","1 carrot (sliced)","4 cloves garlic","1 tbsp soy sauce","1 tsp sesame oil","1 tbsp cooking oil"],"steps":["Heat oil in a wok; sauté garlic for 1 minute.","Add carrots and snow peas; stir-fry over high heat for 3 minutes.","Add squid rings, soy sauce, and sesame oil; toss constantly for 3 minutes until tender-crisp."],"note":"High-fiber vegetable combination providing insoluble plant fiber alongside lean marine squid.","id":"r189"},{"title":"Seafood Bola-Bola in Tomato Stew","category":"main-seafood","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["300g minced fish/shrimp paste","1 egg white","2 tbsp flour","1.5 cups tomato sauce","1 potato (cubed)","1 carrot (cubed)","garlic and onion"],"steps":["Mix minced seafood paste, egg white, and flour; form into small meatballs and steam or bake for 8 minutes.","Sauté garlic and onion; add tomato sauce, carrots, potatoes, and 1 cup water. Simmer for 10 minutes.","Add cooked seafood meatballs and simmer for 5 minutes until sauce thickens."],"note":"Steaming seafood meatballs lowers fat content compared to traditional pan-frying.","id":"r190"},{"title":"Steamed Scallops in Garlic Soy","category":"main-seafood","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["400g fresh scallops on the half shell","6 cloves garlic (minced)","2 tbsp low-sodium soy sauce","1 tsp sesame oil","spring onions"],"steps":["Arrange clean scallops on half shells in a steamer basket.","Mix minced garlic, low-sodium soy sauce, and sesame oil; spoon over scallops.","Steam over boiling water for 5 to 7 minutes until opaque. Garnish with chopped spring onions."],"note":"Pure steam preparation preserving valuable marine minerals and delicate protein structures.","id":"r191"},{"title":"Adobong Tahong","category":"main-seafood","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["500g mussel meat (cooked and shucked)","1/3 cup cane vinegar","2 tbsp soy sauce","6 cloves garlic (crushed)","1 bay leaf","1 tbsp oil","pepper"],"steps":["Sauté crushed garlic in oil until golden brown.","Add shucked mussel meat, soy sauce, cane vinegar, bay leaf, and pepper.","Simmer uncovered for 6 to 8 minutes until vinegar cooks off and sauce reduces."],"note":"Shucked mussels offer concentrated iron, zinc, and B-vitamins in a low-fat vinegar reduction.","id":"r192"},{"title":"Seafood Spicy Coconut Noodle Bowl","category":"main-seafood","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["300g mixed seafood","100g rice vermicelli","1.5 cups light coconut milk","1 tbsp red curry paste","1 cup bean sprouts","lime wedges"],"steps":["Simmer red curry paste and light coconut milk in a pot for 3 minutes.","Add fish stock or water (2 cups) and bring to a gentle boil.","Add mixed seafood and rice vermicelli; cook for 5 minutes.","Serve hot in bowls topped with fresh bean sprouts and lime wedges."],"note":"Capsaicin and coconut lipids combine to create a satisfying, nutrient-dense broth base.","id":"r193"},{"title":"Crispy Baby Squid Main Plate","category":"main-seafood","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["400g baby squids (cleaned)","1/2 cup cornstarch","1 tsp garlic powder","salt and pepper","oil spray","spicy vinegar dip"],"steps":["Season baby squids with salt, pepper, and garlic powder; toss lightly in cornstarch.","Spray air-fryer basket with oil, arrange squids in a single layer, and air-fry at 200°C for 8 to 10 minutes until crispy.","Serve immediately with a side of spicy garlic vinegar."],"note":"Air-frying delivers crispy textures while maintaining low dietary fat parameters.","id":"r194"},{"title":"Sautéed Scallops with Asparagus","category":"main-seafood","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["350g sea scallops","1 bunch fresh asparagus (trimmed)","4 cloves garlic (minced)","1 tbsp olive oil","1 tbsp calamansi juice","pepper"],"steps":["Sear scallops in olive oil over high heat for 2 minutes per side; remove and set aside.","Add minced garlic and asparagus to the same pan; stir-fry for 3 minutes.","Return scallops to pan, drizzle with calamansi juice and pepper, and toss for 1 minute."],"note":"High folate and fiber from asparagus paired with lean, sweet sea scallop protein.","id":"r195"},{"title":"Seafood Omelet (Tortang Hipon at Pusit)","category":"main-seafood","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["150g shrimp (chopped)","150g squid (chopped)","4 eggs (beaten)","1 onion (diced)","1 tomato (diced)","1 tbsp oil","salt and pepper"],"steps":["Sauté onion, tomato, shrimp, and squid in oil for 3 minutes; season with salt and pepper.","Pour beaten eggs evenly over seafood mixture in skillet.","Cook over medium-low heat for 4 minutes, flip carefully, and cook for another 2 minutes until set."],"note":"Dense complete protein plate providing choline, omega-3s, and selenium.","id":"r196"},{"title":"Grilled Seafood Skewers (Shrimp & Squid)","category":"main-seafood","prep":"20 mins","cook":"10 mins","servings":"4","ingredients":["300g large shrimp","200g squid (cut into squares)","1 red bell pepper (cut into squares)","1 red onion (quartered)","annatto-garlic basting oil"],"steps":["Thread shrimp, squid, bell pepper, and onion alternately onto wooden skewers.","Preheat the grill to high heat.","Grill skewers for 3 to 4 minutes per side, basting with annatto-garlic oil until opaque."],"note":"Grilling keeps fat content low while colorful bell peppers contribute Vitamin C antioxidants.","id":"r197"},{"title":"Seafood Caldereta","category":"main-seafood","prep":"20 mins","cook":"25 mins","servings":"5","ingredients":["400g mixed seafood","1 cup tomato sauce","1 potato (cubed)","1 carrot (cubed)","1 bell pepper","1/2 cup peas","2 tbsp liver spread","garlic and onion"],"steps":["Sauté garlic and onion; add tomato sauce, liver spread, and 1 cup water. Simmer for 5 minutes.","Add potatoes and carrots; simmer covered for 10 minutes until tender.","Fold in mixed seafood, bell peppers, and peas; simmer for 5 to 7 minutes until sauce thickens."],"note":"Rich in Vitamin A and lycopene with dense iron and protein contributions from liver spread and seafood.","id":"r198"},{"title":"Seafood Gata with Malunggay","category":"main-seafood","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g mixed seafood (fish, shrimp, mussels)","1.5 cups light coconut milk","2 cups fresh malunggay leaves","1 thumb ginger","1 onion","1 tbsp fish sauce"],"steps":["Bring light coconut milk, ginger, and onion to a gentle boil in a pot.","Add mixed seafood and fish sauce; simmer covered for 8 to 10 minutes.","Stir in fresh malunggay leaves, turn off heat, cover, and steam for 2 minutes before serving."],"note":"Packed with plant-based iron and calcium from malunggay paired with essential sea minerals.","id":"r199"},{"title":"Steamed Seafood Parcel with Lemongrass","category":"main-seafood","prep":"20 mins","cook":"18 mins","servings":"4","ingredients":["400g mixed seafood","2 stalks lemongrass (bruised)","1 thumb ginger (julienned)","2 tomatoes (sliced)","banana leaves or foil","salt and pepper"],"steps":["Divide mixed seafood onto 4 sheets of banana leaves or foil.","Top each with bruised lemongrass, ginger, tomatoes, salt, and pepper.","Fold into sealed parcels and steam over boiling water for 15 to 18 minutes."],"note":"Enclosed steaming retains volatile aromatic oils and natural juices without requiring cooking fats. FISH:","id":"r200"},{"title":"Pinaputok na Tilapia (Stuffed & Baked Tilapia)","category":"main-fish","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["2 whole Tilapia (cleaned, butterflied)","2 ripe tomatoes (diced)","1 red onion (diced)","1 thumb ginger (minced)","2 calamansi (juiced)","banana leaves/foil","salt and pepper"],"steps":["Season inside and outside of tilapia with salt, pepper, and calamansi juice.","Mix tomatoes, onion, and ginger; stuff generously into the belly of the fish.","Wrap tilapia tightly in banana leaves or aluminum foil.","Bake at 200°C (400°F) for 25 minutes until the fish is flaky and cooked through."],"note":"Wrapping retains intrinsic fish moisture and volatile aromatic nutrients without requiring added cooking oils.","id":"r201"},{"title":"Inun-unan (Visayan Spiced Fish in Vinegar)","category":"main-fish","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["500g whole fish (Bangus, Talakitok, or Lapu-Lapu)","1/2 cup cane vinegar","1 thumb ginger (sliced)","5 cloves garlic (crushed)","2 green chilies","1 eggplants (sliced)","salt and peppercorns"],"steps":["Arrange ginger, garlic, and eggplant slices at the bottom of a clay pot or pan.","Lay cleaned whole fish over the vegetables.","Pour in cane vinegar, green chilies, salt, and peppercorns.","Simmer covered over medium-low heat for 20 minutes without stirring until liquid reduces."],"note":"Traditional vinegar simmering preserves Lean fish proteins while eliminating unnecessary cooking fats.","id":"r202"},{"title":"Escabeche (Filipino Sweet & Sour Fish)","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["1 whole Lapu-Lapu or Maya-Maya (500g, cleaned)","1 red bell pepper (julienned)","1 carrot (julienned)","1 thumb ginger (julienned)","1 onion","1/3 cup vinegar","3 tbsp honey","1 tbsp cornstarch","1 tbsp oil"],"steps":["Pan-sear fish in oil until golden on both sides; place on a platter.","Sauté ginger, onion, bell pepper, and carrots in the same pan for 3 minutes.","Whisk vinegar, honey, 1/2 cup water, and cornstarch together; pour into pan.","Simmer until sauce thickens and turns clear. Pour hot sweet and sour sauce over cooked fish."],"note":"Honey replaces refined sugar in the sauce, pairing natural simple sugars with high-quality marine protein.","id":"r203"},{"title":"Sinigang na Salmon Belly sa Miso","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g salmon belly strips","2 tbsp yellow miso paste","1 pack tamarind base","1 radish (sliced)","1 bunch mustard leaves or kangkong","2 tomatoes","1 onion","5 cups water"],"steps":["Sauté onion, tomatoes, and miso paste in a pot for 2 minutes until fragrant.","Pour in water and bring to a boil; add radish and simmer for 5 minutes.","Add salmon belly strips and tamarind base; simmer gently for 7 minutes.","Stir in mustard leaves, turn off heat, cover, and let steam for 2 minutes before serving."],"note":"Outstanding source of Omega-3 fatty acids (EPA/DHA), supporting arterial cardiovascular health and brain function.","id":"r204"},{"title":"Pesa na Dalag / Tilapia (Fish in Ginger Soup Main)","category":"main-fish","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g mudfish (Dalag) or Tilapia fillets","2 thumbs ginger (sliced)","1 head cabbage (quartered)","1 bunch pechay","2 leeks (cut into 2-inch pieces)","1 tsp peppercorns","5 cups rice washing","1 tbsp fish sauce"],"steps":["Bring rice washing, ginger, and peppercorns to a rolling boil in a pot.","Add fish pieces and leeks; reduce heat and simmer gently for 10 minutes.","Add cabbage and pechay; cook for an additional 4 minutes. Season with fish sauce."],"note":"Gentle boiled fish preparation offering exceptionally high protein digestibility and low digestive burden.","id":"r205"},{"title":"Sarciadong Isda (Fish in Tomato Egg Sauce)","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["500g fried fish fillets (Tilapia or Galunggong)","3 ripe tomatoes (diced)","2 eggs (beaten)","4 cloves garlic","1 onion","1/2 cup water","1 tbsp oil","salt and pepper"],"steps":["Sauté garlic, onion, and diced tomatoes in oil until soft and mushy.","Pour in water and bring to a simmer. Season with salt and pepper.","Lay fried fish into tomato mixture and simmer for 3 minutes to absorb flavors.","Pour beaten eggs evenly over fish; allow to set slightly, then gently stir sauce."],"note":"Combining whole fish protein with eggs provides a complete amino acid profile rich in choline.","id":"r206"},{"title":"Inihaw na Bangus (Stuffed Grilled Milkfish)","category":"main-fish","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["1 large Bangus (milkfish, unscaled, back-split)","2 tomatoes (diced)","1 red onion (diced)","1 thumb ginger (minced)","calamansi juice","foil for wrapping"],"steps":["Mix tomatoes, onions, ginger, and calamansi juice in a bowl.","Stuff tomato mixture into the back cavity of the split milkfish.","Wrap fish in aluminum foil, leaving the top slightly open.","Grill over medium charcoal heat for 12 to 15 minutes per side until meat is opaque."],"note":"Leaving scales on during grilling prevents flesh charring, protecting heat-sensitive healthy fats inside.","id":"r207"},{"title":"Cardona / Cardiyenteng Isda (Fish Stew with Greens)","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g white fish fillets","2 cups malunggay leaves","1 cup squash (sliced thinly)","1 thumb ginger","1 onion","3 cups rice washing","1 tbsp fish sauce"],"steps":["Boil rice washing, ginger, and onion in a pot for 5 minutes.","Add squash slices and simmer until tender (approx. 6 minutes).","Add fish fillets and simmer for 5 minutes.","Stir in malunggay leaves, season with fish sauce, cover, and turn off heat."],"note":"Micronutrient-dense fish dish providing beta-carotene, iron, potassium, and magnesium.","id":"r208"},{"title":"Ginataang Tulingan (Bullet Tuna in Coconut Milk)","category":"main-fish","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["500g Tulingan (bullet tuna, cleaned, tail twisted)","1/3 cup dried kamias or vinegar","1.5 cups light coconut milk","1 thumb ginger","2 green chilies","salt"],"steps":["Flatten fish slightly and simmer with dried kamias/vinegar, salt, and 1/2 cup water for 15 minutes until liquid evaporates.","Pour in light coconut milk and add ginger and green chilies.","Simmer over low heat for 20 minutes until coconut oil starts to render slightly."],"note":"Tulingan provides lean, dense marine protein high in selenium, phosphorus, and niacin.","id":"r209"},{"title":"Adobong Galunggong (Round Scad Adobo)","category":"main-fish","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["500g Galunggong (cleaned)","1/3 cup cane vinegar","2 tbsp soy sauce","6 cloves garlic (crushed)","1 bay leaf","1/2 tsp peppercorns","1 tbsp oil"],"steps":["Arrange galunggong in a single layer in a skillet.","Add crushed garlic, bay leaf, peppercorns, soy sauce, and cane vinegar.","Simmer uncovered for 5 minutes, then cover and cook for 10 minutes over medium-low heat.","Drizzle with oil for the final minute of cooking."],"note":"Galunggong is an accessible, sustainable source of high-quality animal protein and essential fatty acids.","id":"r210"},{"title":"Paksiw na Bangus (Milkfish in Vinegar Broth)","category":"main-fish","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["500g Bangus (milkfish, cleaned and sliced into steakes)","1/2 cup cane vinegar","1 thumb ginger (sliced)","5 cloves garlic (crushed)","1 small eggplant (sliced)","2 long green chilies (siling haba)","1/2 cup water","1 tsp peppercorns","1 tsp salt"],"steps":["Arrange ginger, garlic, and eggplant slices at the bottom of a wide pan.","Lay the bangus steaks in a single layer over the vegetable bed.","Pour in cane vinegar, water, green chilies, peppercorns, and salt.","Bring to a boil over medium heat uncovered for 5 minutes without stirring.","Cover, reduce heat to low, and simmer for 15 minutes until the fish is cooked and the vinegar is mellowed."],"note":"Vinegar cooking preserves the delicate Omega-3 fatty acids in milkfish belly without adding extra lipids, making it ideal for cardiovascular health.","id":"r211"},{"title":"Bakit (Ilocano Grilled Fish Salad)","category":"main-fish","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g Tilapia or Scad (whole, cleaned)","2 ripe tomatoes (chopped)","1 red onion (thinly sliced)","1 thumb ginger (minced)","3 tbsp cane vinegar","1 tbsp fish sauce (patis)","black pepper"],"steps":["Grill the whole fish over medium charcoal or gas flame until fully cooked and skin is charred (approx. 7–8 mins per side).","Allow fish to cool slightly, remove skin and bones, and flake the flesh into bite-sized pieces.","In a bowl, toss flaked fish with chopped tomatoes, red onion, ginger, vinegar, patis, and black pepper.","Let sit for 10 minutes before serving at room temperature."],"note":"Flaking grilled fish into a fresh tomato-onion salad delivers lean protein alongside lycopene and potassium with zero added oil.","id":"r212"},{"title":"Pinangat na Isda sa Kamias","category":"main-fish","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["500g whole fish (Sap-sap or small Bisugo)","1.5 cups fresh kamias (bilimbi, sliced)","2 ripe tomatoes (quartered)","1 onion (sliced)","1 cup water","1 tbsp fish sauce","2 green chilies"],"steps":["Layer half of the sliced kamias, tomatoes, and onions at the bottom of a pot.","Place the cleaned fish on top, then cover with the remaining kamias, tomatoes, and onions.","Add water, green chilies, and fish sauce.","Cover and simmer over medium-low heat for 20 minutes until the fish is tender and kamias releases its sour juices."],"note":"Kamias acts as a natural fruit acid tenderizer and souring agent, completely removing the need for artificial sodium enhancers.","id":"r213"},{"title":"Ginataang Tilapia sa Pechay","category":"main-fish","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["2 large Tilapia (cleaned and halved)","1.5 cups light coconut milk","1 bunch pechay (stems and leaves separated)","1 thumb ginger (julienned)","1 onion (sliced)","3 cloves garlic","2 green chilies","1 tbsp oil","salt"],"steps":["Heat oil in a pan; sauté ginger, garlic, and onion until translucent.","Pour in light coconut milk and bring to a gentle simmer.","Add tilapia pieces and pechay stems; cover and cook for 15 minutes.","Add green chilies and pechay leaves, simmer for an additional 3 minutes until leaves wilt. Season with salt."],"note":"Using light coconut milk reduces total saturated fat content while combining dietary fiber and calcium from fresh pechay leaves.","id":"r214"},{"title":"Kinilaw na Tanigue (Ceviche Main Plate)","category":"main-fish","prep":"25 mins","cook":"0 mins","servings":"4","ingredients":["500g fresh Tanigue fillet (Spanish Mackerel, cubed)","1 cup cane vinegar (for washing)","3/4 cup fresh calamansi juice","1 thumb ginger (minced)","1 red onion (diced)","2 green chilies (sliced)","1/2 cucumber (diced)","sea salt"],"steps":["Wash cubed raw fish in 1 cup cane vinegar in a bowl for 2 minutes; gently strain and completely discard used vinegar.","Add calamansi juice, fresh ginger, red onion, chilies, cucumber, and sea salt to the washed fish.","Toss gently, cover, and chill in the refrigerator for 20 minutes to cure before serving cold."],"note":"Curing fish in citrus acid retains heat-sensitive vitamins and Omega-3 fatty acids without adding dietary fats.","id":"r215"},{"title":"Inihaw na Blue Marlin Steak","category":"main-fish","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["4 Blue Marlin steaks (approx. 150g each)","3 tbsp soy sauce","2 tbsp calamansi juice","2 cloves garlic (minced)","1 tsp sesame oil","black pepper"],"steps":["Whisk soy sauce, calamansi juice, minced garlic, sesame oil, and black pepper to create a marinade.","Marinate Blue Marlin steaks for 15 to 20 minutes.","Preheat the grill or griddle pan to high heat.","Grill steaks for 5 to 6 minutes per side, basting with remaining marinade, until cooked through and marked."],"note":"Dense, lean pelagic fish provides high concentration of complete protein, selenium, and B-complex vitamins per serving.","id":"r216"},{"title":"Fish Fillet in Sweet Corn Sauce","category":"main-fish","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g cream dory or white fish fillets (cut into bite-sized pieces)","1 cup sweet cream corn","1/2 cup low-fat milk","1 egg white","2 tbsp cornstarch","1 tbsp oil","salt and white pepper"],"steps":["Coat fish pieces in egg white and 1 tbsp cornstarch; pan-sear in oil over medium heat for 3 minutes per side. Set aside.","In the same pan, pour sweet cream corn, low-fat milk, and 1/2 cup water; simmer for 3 minutes.","Slurry remaining cornstarch with 1 tbsp water; stir into corn mixture until thick and glossy. Season with salt and white pepper.","Gently fold pan-seared fish into the warm corn sauce before serving."],"note":"A mild, low-glycemic dish ideal for pediatric or pediatric-geriatric meal plans needing soft textures and nutrient density.","id":"r217"},{"title":"Sinigang na Lapu-Lapu sa Sauteed Miso","category":"main-fish","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g Lapu-Lapu (Grouper, cleaned and cut into steaks)","2 tbsp yellow miso paste","1 pack tamarind base","1 radish (sliced)","1 bunch mustard greens","2 tomatoes (diced)","1 onion","5 cups water","1 tbsp oil"],"steps":["Sauté onion, tomatoes, and yellow miso paste in oil for 3 minutes until fragrant.","Pour in water and bring to a boil; add radish and simmer for 5 minutes.","Add Lapu-Lapu steaks and tamarind base; reduce heat to medium-low and simmer for 10 minutes.","Stir in mustard greens, turn off heat, cover, and let steam for 2 minutes before serving."],"note":"Miso adds fermented probiotics and umami richness, enhancing the digestive profile of lean white fish broth.","id":"r218"},{"title":"Pritong Lapu-Lapu with Calamansi Dip","category":"main-fish","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["1 whole Lapu-Lapu (600g, scored on both sides)","1 tsp salt","1/2 tsp black pepper","2 tbsp cornstarch (for light dusting)","2 tbsp canola oil (for shallow pan-searing)","calamansi wedges and soy sauce for dip"],"steps":["Season Lapu-Lapu inside and out with salt and black pepper; dust lightly with cornstarch.","Heat canola oil in a large non-stick skillet over medium-high heat.","Shallow-fry fish for 6 to 7 minutes per side until skin is crispy and golden and internal flesh is flaky.","Drain on paper towels and serve immediately with fresh calamansi and low-sodium soy sauce."],"note":"Light dusting with cornstarch and pan-searing in minimal non-stick oil controls total fat intake compared to deep frying.","id":"r219"},{"title":"Fish Tausi (Fillet in Black Bean Sauce)","category":"main-fish","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g tilapia or Maya-Maya fillets","2 tbsp salted black beans (tausi, rinsed)","1 red bell pepper (sliced)","1 thumb ginger (julienned)","3 cloves garlic","1 onion","1 tbsp oyster sauce","1/2 cup water","1 tbsp oil"],"steps":["Pan-sear fish fillets in oil for 3 minutes per side until lightly browned; remove and set aside.","In the same pan, sauté ginger, garlic, onion, and rinsed tausi for 2 minutes.","Pour in water and oyster sauce; add red bell pepper and simmer for 3 minutes.","Return fish fillets to the pan, spooning black bean sauce over top, and simmer for 2 minutes."],"note":"Rinsing fermented black beans significantly reduces total sodium while retaining dark bean phytonutrients and savory umami.","id":"r220"},{"title":"Steamed Maya-Maya with Soy-Ginger Glaze","category":"main-fish","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g Maya-Maya fillets (Red Snapper)","2 thumbs ginger (julienned)","3 stalks green onions (julienned)","2 tbsp low-sodium soy sauce","1 tbsp sesame oil","1 tbsp mirin or rice wine","1/2 tsp white pepper"],"steps":["Arrange snapper fillets on a heat-proof plate; top with half of the julienned ginger and green onions.","Steam over medium-high heat for 10 to 12 minutes until flesh is opaque and flaky.","Mix low-sodium soy sauce, mirin, and white pepper in a small bowl.","Pour sauce over hot fish, top with remaining fresh ginger and green onions, and drizzle warm sesame oil over top."],"note":"Steaming locks in high biological value protein with zero lipid peroxidation; sesame oil provides heart-healthy fats.","id":"r221"},{"title":"Fish Bola-Bola sa Sweet & Sour Sauce","category":"main-fish","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["400g white fish fillet (ground/minced)","1 egg","1/4 cup carrots (minced)","2 tbsp breadcrumbs","1 bell pepper (sliced)","1/3 cup vinegar","2 tbsp honey","1 tbsp tomato paste","1 tbsp cornstarch","1 tbsp oil"],"steps":["Combine ground fish, egg, minced carrots, breadcrumbs, salt, and pepper; form into 12 meatballs.","Pan-sear fish balls in oil for 6 minutes, turning until golden brown on all sides; set aside.","In a separate pan, whisk vinegar, honey, tomato paste, cornstarch, and 1/2 cup water; bring to a simmer until clear and thickened.","Add bell peppers and pan-seared fish balls; toss gently to coat in sweet and sour glaze."],"note":"Homemade fish meatballs minimize sodium and industrial preservatives found in pre-packaged commercial processed fish balls.","id":"r222"},{"title":"Ginataang Salmon Belly","category":"main-fish","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["400g salmon belly strips","1.5 cups light coconut milk","1 bunch spinach or mustard leaves","1 thumb ginger (julienned)","1 onion (sliced)","2 green chilies","1 tbsp fish sauce"],"steps":["Combine light coconut milk, ginger, and onion in a pot; bring to a gentle simmer over medium-low heat.","Add salmon belly strips and green chilies; simmer gently for 10 minutes (do not boil vigorously to prevent curdling).","Season with fish sauce and fold in fresh spinach leaves.","Turn off heat, cover, and let steam for 2 minutes before serving."],"note":"Combines anti-inflammatory Omega-3 fats from salmon belly with medium-chain triglycerides from coconut milk.","id":"r223"},{"title":"Adobong Bangus","category":"main-fish","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g Bangus (cleaned and cut into steaks)","1/3 cup cane vinegar","3 tbsp low-sodium soy sauce","6 cloves garlic (crushed)","1 bay leaf","1/2 tsp whole peppercorns","1/2 cup water","1 tbsp oil"],"steps":["Marinate bangus steaks in soy sauce, garlic, and peppercorns for 15 minutes.","Heat oil in a pan; brown bangus steaks for 2 minutes per side, then remove.","Pour reserved marinade, water, bay leaf, and vinegar into the pan. Bring to a boil for 3 minutes uncovered.","Return fish to pan, cover, and simmer over low heat for 12 minutes until sauce reduces."],"note":"Classic adobo preparation adapted for milkfish yields high protein with a lower saturated fat profile than pork alternatives.","id":"r224"},{"title":"Fish Curry Tagalog Style","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["500g firm white fish fillets (cubed)","1 tbsp mild curry powder","1 cup light coconut milk","1 red bell pepper (sliced)","1 carrot (sliced)","1 thumb ginger","1 onion","2 cloves garlic","1 tbsp oil","salt"],"steps":["Sauté garlic, onion, and ginger in oil for 2 minutes. Stir in curry powder until fragrant.","Add carrots and 1/2 cup water; simmer for 5 minutes.","Pour in light coconut milk and add fish cubes and bell pepper.","Simmer gently over medium-low heat for 8 to 10 minutes until fish is cooked through and sauce thickens. Season with salt."],"note":"Curcumin in curry powder provides systemic antioxidant support complemented by lean marine protein.","id":"r225"},{"title":"Pochero Isda (Fish Stew with Saba Plantains)","category":"main-fish","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g fish steaks (Maya-Maya or Lapu-Lapu)","2 ripe Saba bananas (sliced)","1 cup tomato sauce","1 cup chickpea/garbanzo beans","1 bunch pechay","1 onion","2 cloves garlic","1 cup water","1 tbsp oil"],"steps":["Pan-sear fish steaks in oil for 2 minutes per side; remove and set aside.","Sauté garlic and onion; add tomato sauce, water, garbanzo beans, and saba plantain slices. Simmer for 10 minutes.","Return fish steaks to the pot and cook for 5 minutes.","Add pechay leaves, cover, turn off heat, and steam for 2 minutes before serving."],"note":"Plantain bananas and chickpeas provide dietary fiber and complex carbohydrates, creating a well-balanced single-pot meal.","id":"r226"},{"title":"Inihaw na Tilapia with Salsa","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["2 whole Tilapia (cleaned and scored)","2 ripe tomatoes (diced)","1 red onion (diced)","2 tbsp calamansi juice","1 tbsp cilantro or green onion (chopped)","sea salt and pepper"],"steps":["Season tilapia inside and out with sea salt, pepper, and 1 tbsp calamansi juice.","Grill whole tilapia over medium heat for 8 to 10 minutes per side until flesh is opaque and flaking.","In a bowl, mix diced tomatoes, red onion, green onion, remaining calamansi juice, and a pinch of salt.","Top warm grilled tilapia with fresh tomato salsa immediately before serving."],"note":"Grilling eliminates added cooking oils, while fresh tomato salsa provides raw Vitamin C and lycopene.","id":"r227"},{"title":"Steamed Pampano in Sesame Soy","category":"main-fish","prep":"15 mins","cook":"18 mins","servings":"4","ingredients":["1 whole Pampano (600g, cleaned and scored)","2 thumbs ginger (julienned)","3 stalks scallions (sliced)","2 tbsp low-sodium soy sauce","1 tbsp sesame oil","1 tbsp mirin","white pepper"],"steps":["Place Pampano on a heat-proof plate and cover with half of the ginger and scallions.","Steam over medium heat for 15 to 18 minutes until fully cooked.","Combine soy sauce, mirin, and white pepper; pour over steamed fish.","Drizzle warm sesame oil over top and garnish with remaining fresh scallions."],"note":"Pampano provides rich natural healthy fats and minerals; steaming preserves texture without heavy oil usage.","id":"r228"},{"title":"Fish Cake Patties Tagalog","category":"main-fish","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["400g white fish fillets (mashed)","1 sweet potato (steamed and mashed)","1 egg","1/4 cup scallions (chopped)","1 tsp garlic powder","salt and pepper","1 tbsp oil"],"steps":["Combine mashed fish fillet, mashed sweet potato, egg, scallions, garlic powder, salt, and pepper in a bowl.","Shape mixture into 8 uniform round patties.","Heat oil in a wide non-stick pan; pan-sear patties over medium heat for 4 to 5 minutes per side until golden brown.","Serve warm with a calamansi-vinegar dip."],"note":"Sweet potato acts as a nutrient-dense binder providing vitamin A and complex carbohydrates instead of refined wheat flour.","id":"r229"},{"title":"Sizzling Bangus Sisig (Low-Fat)","category":"main-fish","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["500g grilled Bangus belly/flesh (flaked and chopped)","1 red onion (diced)","2 green chilies (chopped)","2 tbsp light mayonnaise or Greek yogurt","2 tbsp calamansi juice","1 tbsp low-sodium soy sauce","1 tsp oil"],"steps":["Sauté chopped grilled bangus flesh in a pan with 1 tsp oil over high heat for 3 minutes to crisp slightly.","Add diced red onion, green chilies, soy sauce, and calamansi juice; toss for 2 minutes.","Remove from heat and fold in light mayonnaise or Greek yogurt until creamy.","Transfer to a hot plate and serve immediately with extra calamansi wedges."],"note":"Replaces traditional high-fat pork sisig with lean milkfish protein, reducing total saturated fat by up to 75%.","id":"r230"},{"title":"Sinigang na Bangus sa Bayabas (Guava Fish)","category":"main-fish","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["500g Bangus (cleaned and sliced into steaks)","6 ripe guavas (peeled, quartered, and seeded)","1 bunch kangkong","1 radish (sliced)","1 onion (quartered)","5 cups water","1 tbsp fish sauce"],"steps":["Boil quartered guavas and onion in 5 cups of water for 15 minutes until guavas are soft.","Mash guavas in the pot and strain through a sieve to extract pulp while discarding seeds.","Return smooth guava broth to a boil; add sliced radish and bangus steaks. Simmer for 10 minutes.","Add kangkong leaves, season with fish sauce, turn off heat, and cover for 2 minutes before serving."],"note":"Guava broth provides natural Vitamin C and a mild sweet-sour flavor without relying on processed souring powders.","id":"r231"},{"title":"Fish Tapa (Marinated Dried/Fresh Fish)","category":"main-fish","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["500g boneless Bangus or white fish fillets","3 tbsp cane vinegar","4 cloves garlic (crushed)","1/2 tsp black pepper","1/2 tsp sea salt","1 tbsp canola oil"],"steps":["Combine vinegar, crushed garlic, black pepper, and sea salt in a dish.","Marinate fish fillets for at least 30 minutes (or overnight in refrigerator).","Heat canola oil in a non-stick pan over medium-high heat.","Pan-fry fish for 4 to 5 minutes per side until lightly crisp on edges and cooked through."],"note":"A low-fat, high-protein alternative to commercial beef or pork tapa, free from nitrates and artificial colorings.","id":"r232"},{"title":"Ginisang Tinapa with Tomatoes & Egg","category":"main-fish","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["300g smoked fish flakes (Tinapa, bones removed)","4 ripe tomatoes (diced)","1 onion (diced)","3 cloves garlic","2 eggs (beaten)","1 tbsp oil","black pepper"],"steps":["Heat oil in a pan; sauté garlic, onion, and diced tomatoes until tomatoes are soft and juicy (approx. 4 mins).","Add smoked tinapa flakes and toss for 3 minutes to combine flavors.","Pour beaten eggs over the mixture; allow to set slightly, then gently scramble. Season with black pepper."],"note":"Combines high-protein smoked fish with eggs and antioxidant-rich cooked tomatoes for a nutrient-dense breakfast or main dish.","id":"r233"},{"title":"Fish Salpicao","category":"main-fish","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["500g firm white fish or Tuna fillets (cubed)","8 cloves garlic (minced)","2 tbsp Worcestershire sauce","1 tbsp low-sodium soy sauce","1 tbsp olive oil","1 tsp red pepper flakes"],"steps":["Marinate cubed fish in Worcestershire sauce, low-sodium soy sauce, and red pepper flakes for 10 minutes.","Heat olive oil in a wide skillet over medium-low heat; fry half of the minced garlic until golden brown and crispy. Set crispy garlic aside.","Increase heat to high; add remaining garlic and fish cubes with marinade.","Stir-fry rapidly for 4 to 5 minutes until fish is cooked through and sauce coats the cubes. Top with crispy garlic."],"note":"Olive oil and high-heat rapid searing keep the fish moist while supplying heart-healthy fats and garlic compounds.","id":"r234"},{"title":"Pan-Seared Tanigue Steak in Calamansi Butter","category":"main-fish","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["4 Tanigue steaks (Spanish Mackerel, 150g each)","2 tbsp calamansi juice","1 tbsp light butter","1 tbsp olive oil","2 cloves garlic (minced)","salt and pepper"],"steps":["Season Tanigue steaks with salt, pepper, and 1 tbsp calamansi juice.","Heat olive oil and light butter in a skillet over medium-high heat.","Add garlic and pan-sear Tanigue steaks for 4 to 5 minutes per side until golden and opaque inside.","Drizzle remaining fresh calamansi juice over steaks in the pan right before serving."],"note":"Spanish Mackerel provides essential Omega-3 fatty acids; light butter combined with olive oil lowers total saturated fat.","id":"r235"},{"title":"Fish Menudo","category":"main-fish","prep":"20 mins","cook":"25 mins","servings":"4","ingredients":["500g firm white fish fillets (cubed)","1 potato (diced)","1 carrot (diced)","1 red bell pepper (diced)","1 cup tomato sauce","1/2 cup green peas","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Pan-sear fish cubes in oil for 2 minutes per side; remove and set aside.","In the same pan, sauté garlic and onion. Add tomato sauce and 1/2 cup water; bring to a simmer.","Add diced potatoes and carrots; cook covered for 8 to 10 minutes until tender.","Add red bell pepper, green peas, and seared fish cubes. Simmer gently for 5 minutes until the sauce thickens."],"note":"Replaces red meat in traditional menudo with lean fish, maintaining high fiber and lycopene levels while reducing saturated fat.","id":"r236"},{"title":"Adobong Isda sa Puti (White Fish Adobo)","category":"main-fish","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["500g white fish fillets (Maya-Maya or Pangasius)","1/2 cup cane vinegar","6 cloves garlic (crushed)","1 tsp whole peppercorns","2 green chilies","1/2 cup water","1 tsp salt","1 tbsp oil"],"steps":["Place crushed garlic, peppercorns, salt, vinegar, and water in a wide skillet.","Lay fish fillets in the liquid and bring to a boil uncovered over medium heat for 4 minutes.","Add green chilies, cover, reduce heat to low, and simmer for 12 minutes.","Drizzle oil over the fish during the final minute of cooking."],"note":"Soy-sauce-free white adobo controls sodium levels while maintaining traditional acetic acid flavor profiles.","id":"r237"},{"title":"Fish Caldereta","category":"main-fish","prep":"20 mins","cook":"25 mins","servings":"4","ingredients":["500g firm fish fillets (Tuna or Mahi-Mahi, cubed)","1 cup tomato sauce","2 tbsp liver spread","1/2 cup low-fat grated cheese","1 red bell pepper","1 potato (cubed)","1 carrot (cubed)","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Sear fish cubes in oil for 3 minutes; set aside.","Sauté garlic and onion in the pan; stir in tomato sauce, liver spread, and 1/2 cup water.","Add potatoes and carrots; simmer covered for 10 minutes until soft.","Add bell peppers, seared fish, and low-fat cheese. Simmer for 5 minutes until cheese melts into the thick sauce."],"note":"High-protein main dish delivering Vitamin A, iron, and calcium through root vegetables, fish, and light cheese enrichment.","id":"r238"},{"title":"Ginataang Fish Fillet with Spinach","category":"main-fish","prep":"10 mins","cook":"18 mins","servings":"4","ingredients":["500g white fish fillets (cut into wide strips)","1.5 cups light coconut milk","2 cups fresh spinach leaves","1 thumb ginger (julienned)","1 onion","2 cloves garlic","1 green chili","1 tbsp oil","salt"],"steps":["Sauté ginger, garlic, and onion in oil in a pan until fragrant.","Pour in light coconut milk and bring to a low simmer.","Add fish strips and green chili; cover and simmer gently for 10 minutes.","Stir in fresh spinach leaves, season with salt, turn off heat, and steam covered for 2 minutes."],"note":"Spinach adds lutein, folate, and non-heme iron to high-quality protein cooked in light coconut milk.","id":"r239"},{"title":"Crispy Baked Fish Cutlets","category":"main-fish","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g white fish cutlets","1/2 cup whole wheat breadcrumbs","1/4 cup cornstarch","1 egg (beaten)","1 tsp garlic powder","1/2 tsp paprika","salt and pepper","cooking spray"],"steps":["Season fish cutlets with garlic powder, paprika, salt, and pepper.","Dredge cutlets in cornstarch, dip into beaten egg, and coat thoroughly with whole wheat breadcrumbs.","Arrange cutlets on a wire rack over a baking sheet and lightly coat with cooking spray.","Bake at 200°C (400°F) for 12 to 15 minutes until golden and crispy."],"note":"Oven-baking with whole wheat breadcrumbs provides a crispy crunch with minimal added fat and higher complex fiber.","id":"r240"},{"title":"Fish Afritada","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["500g white fish fillets (cubed)","1 cup tomato sauce","1 potato (cubed)","1 carrot (cubed)","1 green bell pepper (sliced)","1/2 cup green peas","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Pan-sear fish cubes in oil for 2 minutes per side; remove and set aside.","Sauté garlic and onion in the pan; pour tomato sauce and 1/2 cup water. Bring to a boil.","Add potatoes and carrots; simmer covered for 8 to 10 minutes.","Stir in bell peppers, green peas, and fish cubes. Simmer gently for 5 minutes until vegetables are tender."],"note":"Lycopene-rich tomato stew paired with lean white fish provides cardiovascular support and high digestible protein.","id":"r241"},{"title":"Steamed White Fish with Lemongrass","category":"main-fish","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["500g white fish fillets (Tilapia, Pangasius, or Snapper)","2 stalks lemongrass (tanglad, bruised and chopped)","1 thumb ginger (sliced)","2 calamansi (juiced)","1 tbsp fish sauce","banana leaf for wrapping"],"steps":["Rub fish fillets with calamansi juice and fish sauce.","Place bruised lemongrass stalks and ginger slices over fish fillets.","Wrap tightly in banana leaf or aluminum foil.","Steam over boiling water for 12 to 15 minutes until the fish is tender and fragrant."],"note":"Essential oils from lemongrass infuse the fish with citrus aroma without requiring oils or artificial flavorings.","id":"r242"},{"title":"Sinigang na Tanigue sa Mangga","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["500g Tanigue steaks (Spanish Mackerel)","1 green mango (peeled and grated)","1 bunch kangkong","1 radish (sliced)","1 onion (quartered)","2 tomatoes (quartered)","5 cups water","1 tbsp fish sauce"],"steps":["Boil grated green mango, onions, and tomatoes in 5 cups of water for 10 minutes until mango softens and sours the broth.","Add sliced radish and Tanigue steaks; simmer over medium heat for 8 minutes.","Fold in kangkong leaves, season with fish sauce, turn off heat, and cover for 2 minutes."],"note":"Unripe green mango acts as an all-natural souring agent rich in Vitamin C, bioflavonoids, and organic tartaric acids.","id":"r243"},{"title":"Fish Almondigas (Fish Balls with Patola)","category":"main-fish","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["300g minced fish fillet","1 egg","2 tbsp cornstarch","1 medium patola (sponge gourd, sliced into rounds)","50g misua noodles","4 cups fish/vegetable stock","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Combine minced fish, egg, cornstarch, salt, and pepper; form into small fish meatballs.","Sauté garlic and onion in oil; pour in stock and bring to a boil.","Drop fish meatballs into boiling stock and cook for 5 minutes until they float.","Add patola slices and misua noodles; cook for 3 minutes until noodles are tender."],"note":"Patola provides hydrating soluble fiber in a low-calorie soup featuring easy-to-digest fish protein balls.","id":"r244"},{"title":"Pan-Seared Sea Bass with Mango Salsa","category":"main-fish","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["4 Sea Bass fillets (150g each)","1 ripe Carabao mango (diced)","1/2 red onion (diced)","1 tbsp fresh cilantro (chopped)","2 tbsp calamansi juice","1 tbsp olive oil","salt and pepper"],"steps":["Season sea bass fillets with salt and pepper.","Heat olive oil in a non-stick skillet over medium-high heat; sear sea bass skin-side down for 4 minutes, flip, and cook for 3 minutes.","Mix diced mango, red onion, cilantro, and calamansi juice in a bowl.","Serve seared sea bass topped with fresh mango salsa."],"note":"Rich in high-value Omega-3 fatty acids and Vitamin A; raw mango salsa provides active digestive enzymes.","id":"r245"},{"title":"Fish Fillet Chopsuey","category":"main-fish","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["400g firm white fish fillets (cubed)","1 cup cauliflower florets","1 carrot (sliced)","1 cup snow peas","1 bell pepper (sliced)","1 cup cabbage (chopped)","1 cup vegetable broth","1 tbsp cornstarch","1 tbsp soy sauce","1 tbsp oil"],"steps":["Sear fish cubes in oil for 3 minutes; remove and set aside.","Sauté garlic and onion; add carrots and cauliflower with half the broth, cooking for 3 minutes.","Add snow peas, bell pepper, and cabbage.","Stir cornstarch, remaining broth, and soy sauce into the pan; simmer until thick. Fold in seared fish cubes gently before serving."],"note":"Cruciferous vegetable mix provides high fiber, glucosinolates, and Vitamin C paired with clean marine protein.","id":"r246"},{"title":"Ginataang Dalag at Malunggay","category":"main-fish","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["500g Dalag (Mudfish, cleaned and sliced)","1.5 cups light coconut milk","2 cups fresh malunggay leaves","1 thumb ginger (julienned)","1 onion","2 green chilies","1 tbsp fish sauce"],"steps":["Combine light coconut milk, ginger, onion, and fish sauce in a pan; bring to a low simmer.","Add dalag slices and green chilies; simmer covered over medium-low heat for 15 minutes.","Add malunggay leaves, turn off heat, cover, and steam for 3 minutes before serving."],"note":"Mudfish is traditionally valued for wound healing and muscle recovery due to its high albumin and essential amino acid content.","id":"r247"},{"title":"Baked Tilapia Parmigiana (Light)","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["4 Tilapia fillets","1 cup tomato sauce","1/3 cup low-fat mozzarella cheese (shredded)","2 tbsp parmesan cheese","1 tsp dried oregano","1 tsp garlic powder","salt and pepper"],"steps":["Arrange tilapia fillets in a baking dish; season with garlic powder, oregano, salt, and pepper.","Spoon tomato sauce evenly over the fillets.","Top with low-fat mozzarella and parmesan cheese.","Bake at 190°C (375°F) for 18 to 20 minutes until the cheese is bubbly and fish flakes easily with a fork."],"note":"A modern low-fat fusion dish offering high protein, lycopene, and calcium with minimal saturated fat.","id":"r248"},{"title":"Fish Mechado","category":"main-fish","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["500g firm fish steaks (Tuna or Maya-Maya)","1 cup tomato sauce","2 tbsp soy sauce","2 tbsp calamansi juice","1 potato (cubed)","1 bell pepper (sliced)","1 onion","2 cloves garlic","1 tbsp oil"],"steps":["Marinate fish steaks in soy sauce and calamansi juice for 10 minutes.","Pan-sear fish in oil for 2 minutes per side; remove and set aside.","Sauté garlic and onion; add tomato sauce, marinade liquid, and 1/2 cup water. Simmer potatoes for 8 minutes until tender.","Return fish steaks and add bell pepper; simmer gently for 5 minutes until sauce reduces."],"note":"Citrus marinades break down fish proteins for improved digestibility while tomato bases supply antioxidant protection.","id":"r249"},{"title":"Broiled Fish Collar with Calamansi Ponzu","category":"main-fish","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["2 large Tuna or Salmon collars (panga, halved)","1 tsp sea salt","1/2 tsp black pepper","3 tbsp low-sodium soy sauce","2 tbsp calamansi juice","1 tsp grated ginger"],"steps":["Season fish collars thoroughly with sea salt and black pepper.","Preheat the oven broiler or griddle pan to high heat.","Broil fish collars for 7 to 8 minutes per side until skin is blistered and flesh is cooked through.","Whisk soy sauce, fresh calamansi juice, and grated ginger to make ponzu dip; serve alongside hot broiled collar."],"note":"Fish collar meat retains exceptional moisture and contains high concentrations of Omega-3 fatty acids without added cooking oils. REFERENCES:","id":"r250"},{"title":"Ensaladang Talong (Eggplant Salad)","category":"side","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["3 large Asian eggplants","2 medium tomatoes (diced)","1 small red onion (diced)","3 tbsp cane vinegar","1 tbsp fish sauce (patis) or pinch of salt","freshly ground black pepper"],"steps":["Grill or roast whole eggplants over gas flame or oven until skin is charred and flesh is tender.","Peel off charred skin while warm, leaving the stem intact. Mash flesh lightly with a fork.","Combine diced tomatoes and red onions in a bowl.","Lay mashed eggplant on a platter, top with tomato-onion mix, and drizzle with cane vinegar and fish sauce. Serve warm or chilled."],"note":"Rich in dietary fiber and chlorogenic acid (antioxidant). Grilling without added oil keeps caloric density low.","id":"r251"},{"title":"Ginisang Ampalaya (Stir-Fried Bitter Gourd)","category":"side","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["2 medium bitter gourds (sliced thinly)","2 eggs (beaten)","2 cloves garlic (minced)","1 small onion (sliced)","2 tomatoes (diced)","1 tbsp vegetable oil","salt and pepper"],"steps":["Massage sliced bitter gourd in 1 tbsp salt for 5 minutes, rinse thoroughly in cold water, and drain to reduce bitterness.","Heat oil in a pan; sauté garlic, onion, and tomatoes until soft.","Add ampalaya and stir-fry over medium-high heat for 3–5 minutes until tender-crisp.","Pour in beaten eggs, let set slightly, then gently scramble. Season with pepper."],"note":"Ampalaya contains charantin and polypeptide-p, which assist in blood glucose regulation.","id":"r252"},{"title":"Achara (Pickled Green Papaya)","category":"side","prep":"30 mins","cook":"10 mins","servings":"10","ingredients":["1 kg green papaya (shredded)","1 carrot (sliced thinly into flowers)","1 red bell pepper (julienned)","1 thumb ginger (julienned)","5 cloves garlic (sliced)","1 cup cane vinegar","1 cup white sugar","1 tbsp salt"],"steps":["Salt shredded papaya and let stand 30 minutes. Squeeze out excess liquid thoroughly using cheesecloth.","Combine carrots, bell pepper, ginger, and garlic with papaya in clean glass jars.","In a saucepan, simmer vinegar, sugar, and salt until dissolved. Do not stir while boiling.","Pour hot brine over packed vegetables. Seal and refrigerate for 24 hours before serving."],"note":"Contains active papain enzymes that aid protein digestion when served alongside fried or grilled meats.","id":"r253"},{"title":"Ensaladang Mangga at Kamatis (Green Mango & Tomato Salad)","category":"side","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["2 unripe green mangoes (julienned)","3 ripe tomatoes (diced)","1 red onion (diced)","2 tbsp bagoong alamang (shrimp paste) or seaweed flakes for vegan option"],"steps":["Prepare mangoes, tomatoes, and onions.","Toss ingredients together in a glass bowl.","Serve topped with a side of sautéed bagoong or fold in lightly just before serving."],"note":"Excellent source of Vitamin C and bioflavonoids.","id":"r254"},{"title":"Ginisang Munggo (Sautéed Mung Bean Side)","category":"side","prep":"10 mins","cook":"35 mins","servings":"6","ingredients":["1 cup dried green mung beans","4 cloves garlic (minced)","1 onion (sliced)","2 tomatoes (diced)","2 cups malunggay (moringa) leaves","1 tbsp vegetable oil","1 tbsp patis"],"steps":["Boil mung beans in 4 cups water until tender (approx. 25–30 minutes).","In a separate skillet, sauté garlic, onion, and tomatoes in oil until softened.","Pour boiled mung beans and cooking liquid into the sautéed mixture. Simmer 5 minutes.","Stir in malunggay leaves, turn off heat, cover, and let steam 2 minutes. Season with patis."],"note":"Plant-based iron and micronutrient powerhouse boosted by Moringa oleifera.","id":"r255"},{"title":"Adobong Sitaw (Long Beans Adobo)","category":"side","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["1 bunch (300g) sitaw (yardlong beans, cut into 2-inch pieces)","4 cloves garlic (crushed)","3 tbsp cane vinegar","2 tbsp soy sauce","1/2 cup water","1 tbsp oil","black pepper"],"steps":["Heat oil; sauté garlic until light golden brown.","Add sitaw and toss for 2 minutes.","Pour in soy sauce, water, and pepper. Simmer covered for 5 minutes.","Add vinegar; allow to boil un-covered for 3 minutes without stirring. Stir and serve."],"note":"Low-calorie, high-fiber side dish suitable for daily glycemic management.","id":"r256"},{"title":"Kilawin na Puso ng Saging (Banana Blossom in Vinegar)","category":"side","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["1 banana blossom (outer layers removed, sliced thinly)","1/2 cup cane vinegar","4 cloves garlic (minced)","1 small onion","1 red chili (optional)","salt and pepper"],"steps":["Soak sliced banana blossom in salted water for 15 mins; squeeze out bitter juice and drain.","Boil in clear water for 8 minutes until tender; drain thoroughly.","Toss boiled banana blossom with raw garlic, onions, chilies, vinegar, salt, and pepper."],"note":"Exceptionally rich in dietary fiber and insoluble complex carbohydrates.","id":"r257"},{"title":"Ensaladang Pako (Fiddlehead Fern Salad)","category":"side","prep":"15 mins","cook":"0 mins","servings":"4","ingredients":["3 cups fresh pako (fiddlehead fern, cleaned and trimmed)","2 salted eggs (diced)","2 ripe tomatoes (diced)","1 red onion (sliced)","3 tbsp coconut vinegar","1 tbsp honey"],"steps":["Wash fern fronds in cold ice water to crisp up; drain well.","Whisk vinegar and honey to create a light dressing.","Arrange pako on a serving dish; top with tomatoes, red onions, and salted eggs.","Drizzle dressing right before serving."],"note":"Abundant in Beta-carotene, Calcium, and Vitamin A.","id":"r258"},{"title":"Ginisang Kangkong (Sautéed Water Spinach)","category":"side","prep":"10 mins","cook":"8 mins","servings":"4","ingredients":["2 bunches kangkong (leaves and tender stems)","6 cloves garlic (minced)","2 tbsp soy sauce","1 tbsp cane vinegar","1 tbsp sesame or cooking oil"],"steps":["Heat oil in a wok; fry garlic until crispy and golden. Remove half for garnish.","Add kangkong stems first, stir-fry 2 minutes, then add leaves.","Pour soy sauce and vinegar. Stir quickly over high heat for 1 minute. Top with fried garlic."],"note":"High in iron, magnesium, and dietary fiber.","id":"r259"},{"title":"Chopsuey (Filipino Stir-Fried Vegetables)","category":"side","prep":"20 mins","cook":"12 mins","servings":"6","ingredients":["1 cup cauliflower florets","1 carrot (sliced)","1 cup snow peas (chicharo)","1 bell pepper (sliced)","1 cup cabbage (chopped)","1 cup chicken broth","1 tbsp cornstarch","1 tbsp soy sauce","1 tbsp oyster sauce","1 tbsp oil","garlic and onion"],"steps":["Sauté garlic and onion in oil.","Add hard vegetables (carrots, cauliflower) and cook 3 minutes with half the broth.","Add snow peas, bell pepper, and cabbage.","Mix cornstarch, remaining broth, soy sauce, and oyster sauce; pour into pan and simmer until sauce thickens."],"note":"High-density cruciferous vegetable mix packed with glucosinolates.","id":"r260"},{"title":"Adobong Kangkong with Toasted Garlic","category":"side","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["2 bunches water spinach (kangkong, leaves and tender stems cut into 2-inch lengths)","8 cloves garlic (minced)","3 tbsp cane vinegar","2 tbsp low-sodium soy sauce","1/2 cup water","1 tbsp cooking oil","1/2 tsp crushed black peppercorns"],"steps":["Heat oil in a pan over medium heat; sauté half of the minced garlic until deep golden brown and crispy. Remove toasted garlic and set aside for garnish.","In the same pan, add remaining garlic and sauté until fragrant. Add kangkong stems and toss for 1 minute.","Pour in low-sodium soy sauce, water, and black pepper. Bring to a simmer.","Add kangkong leaves and cane vinegar. Allow to boil uncovered for 2 minutes without stirring.","Stir gently to combine, transfer to a platter, and top with reserved toasted garlic."],"note":"Kangkong is exceptionally rich in non-heme iron, calcium, and beta-carotene. Using low-sodium soy sauce helps keep blood pressure in check while preserving classic adobo umami.","id":"r261"},{"title":"Laing (Spiced Taro Leaves in Coconut Milk)","category":"side","prep":"15 mins","cook":"40 mins","servings":"6","ingredients":["100g dried taro leaves (dahon ng gabi)","2 cups thin coconut milk (kabalawan)","1 cup thick coconut cream (kakang gabi)","3 thumbs ginger (julienned)","5 cloves garlic (minced)","1 red onion (sliced)","3 green bird's eye chilies (siling labuyo)","1 tbsp bagoong alamang (shrimp paste)","1/2 tsp salt"],"steps":["In a heavy pot, combine thin coconut milk, ginger, garlic, red onion, siling labuyo, and shrimp paste. Bring to a gentle simmer over medium-low heat.","Add dried taro leaves into the liquid. Press leaves down gently into the liquid; do not stir for the first 15–20 minutes to prevent itching (gati).","Simmer until taro leaves absorb the coconut milk and soften completely.","Pour in thick coconut cream, adjust heat to low, and simmer until oil separates slightly (approx. 10 minutes)."],"note":"Taro leaves are packed with dietary fiber and vitamin A. Medium-chain triglycerides (MCTs) in coconut milk offer efficient cellular energy, though portion control is advised for dyslipidemia management.","id":"r262"},{"title":"Gulay sa Gata (Squash & String Beans in Coconut Cream)","category":"side","prep":"15 mins","cook":"20 mins","servings":"5","ingredients":["300g calabaza squash (kalabasa, peeled and cubed)","150g yardlong beans (sitaw, cut into 2-inch pieces)","1.5 cups coconut milk","1/2 cup coconut cream","1 red onion (sliced)","3 cloves garlic (minced)","1 thumb ginger (sliced)","1 tbsp fish sauce (patis)","1 tbsp cooking oil"],"steps":["Heat oil in a saucepan. Sauté garlic, onion, and ginger until soft and translucent.","Add squash cubes and pour in coconut milk. Simmer covered for 8–10 minutes until squash softens slightly.","Add sitaw and fish sauce. Continue simmering for 5 minutes until beans are tender-crisp.","Pour in coconut cream, simmer for an additional 3 minutes to thicken sauce, and serve warm."],"note":"High in vitamin A (alpha and beta-carotene) from squash, which supports ocular and mucosal immunity.","id":"r263"},{"title":"Inihaw na Talong with Salted Egg","category":"side","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["3 long purple eggplants","1 salted duck egg (itlog na maalat, diced)","2 ripe tomatoes (diced)","1 small red onion (diced)","2 tbsp cane vinegar","1 tsp extra virgin olive oil","freshly cracked black pepper"],"steps":["Grill eggplants over medium open flame or stovetop burner until skin is fully charred and flesh is completely soft.","Allow to cool slightly, then peel off charred skin, keeping the stem intact. Flatten flesh lightly with a fork.","In a bowl, toss diced salted egg, tomatoes, red onion, cane vinegar, olive oil, and black pepper.","Lay grilled eggplant on a plate and spoon salted egg mixture over top."],"note":"Eggplant skin and flesh contain chlorogenic acid and nasunin, potent antioxidants that combat oxidative stress. Dicing one salted egg across four portions controls overall sodium distribution.","id":"r264"},{"title":"Ensaladang Pipino (Filipino Cucumber Salad)","category":"side","prep":"15 mins","cook":"0 mins","servings":"4","ingredients":["2 large cucumbers (thinly sliced)","1 red onion (thinly sliced)","1/3 cup cane or coconut vinegar","1 tbsp raw honey or coconut sugar","1/2 tsp sea salt","1/4 tsp coarsely ground black pepper","1 finger chili (sliced thinly)"],"steps":["In a glass bowl, whisk together cane vinegar, honey, salt, black pepper, and finger chili until sweetener dissolves.","Add cucumber slices and red onions to the dressing.","Toss thoroughly to coat vegetables evenly.","Cover and chill in the refrigerator for 20 minutes before serving."],"note":"Highly hydrating side dish with low caloric density. Cucumbers contain cucurbitacins and lignans, supporting anti-inflammatory pathways.","id":"r265"},{"title":"Ginisang Sayote (Sautéed Chayote)","category":"side","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["2 medium chayotes (sayote, peeled, cored, and julienned)","1 small carrot (julienned)","4 cloves garlic (minced)","1 small onion (sliced)","1 tomato (diced)","1 tbsp canola oil","1 tbsp light soy sauce","1/4 cup water","ground black pepper"],"steps":["Heat canola oil in a wok or skillet over medium heat. Sauté garlic, onion, and tomato until softened.","Add julienned sayote and carrots; stir-fry for 3 minutes.","Pour in light soy sauce and water. Season with black pepper.","Cover and simmer for 4–5 minutes until vegetables are tender-crisp."],"note":"Chayote is very low in calories, sodium, and carbohydrates while supplying folate and vitamin C—ideal for weight management and diabetic diet protocols.","id":"r266"},{"title":"Pinakbet Tagalog (Mild Mixed Vegetables)","category":"side","prep":"20 mins","cook":"25 mins","servings":"6","ingredients":["1 cup squash (cubed)","1 small eggplant (sliced)","1 small bitter gourd (ampalaya, deseeded and sliced)","6 yardlong beans (sitaw, cut into 2-inch pieces)","4 okra","2 tomatoes (chopped)","1 onion","3 cloves garlic","1 tbsp sautéed shrimp paste (bagoong alamang)","1.5 cups water","1 tbsp oil"],"steps":["Sauté garlic, onion, and tomatoes in oil until tomatoes are soft.","Stir in bagoong alamang and cook for 1 minute.","Add water and squash cubes; simmer for 6 minutes until squash starts to soften.","Layer sitaw, ampalaya, eggplant, and okra into the pot. Cover and simmer over medium-low heat for 10 minutes without over-stirring to keep vegetables intact."],"note":"Diverse vegetable selection provides a wide spectrum of dietary fibers, phytonutrients, and potassium essential for cardiovascular health.","id":"r267"},{"title":"Ginisang Repolyo at Karots (Sautéed Cabbage & Carrots)","category":"side","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["3 cups green cabbage (shredded)","1 medium carrot (julienned)","4 cloves garlic (minced)","1 onion (sliced)","1 tbsp vegetable oil","1 tbsp fish sauce (patis) or tamari","freshly ground black pepper"],"steps":["Heat oil in a pan over medium-high heat; sauté garlic and onion until aromatic.","Add julienned carrots and stir-fry for 2 minutes.","Add shredded cabbage and toss continuously for 3 minutes until leaves wilt slightly.","Season with fish sauce and black pepper. Turn off heat while cabbage remains crisp."],"note":"Cabbage provides sulforaphane and glucosinolates, which aid hepatic detoxification and cellular defense.","id":"r268"},{"title":"Ensaladang Okra with Bagoong Dip","category":"side","prep":"5 mins","cook":"8 mins","servings":"4","ingredients":["12 fresh young okra pods (stems trimmed slightly)","2 tbsp bagoong balayan or sautéed bagoong alamang","1 calamansi (juiced)","1 small red onion (minced)","1 red chili (minced)"],"steps":["Wash okra pods thoroughly under cold running water.","Steam okra over boiling water for 6–8 minutes, or boil for 5 minutes until bright green and tender.","In a small dip saucer, mix bagoong, calamansi juice, minced red onion, and chili.","Serve steamed okra warm or chilled accompanied by the bagoong calamansi dip."],"note":"Okra mucilage contains soluble fiber (pectin) that binds excess intestinal cholesterol and slows carbohydrate absorption, aiding blood glucose stabilization.","id":"r269"},{"title":"Adobong Labong (Bamboo Shoots Adobo)","category":"side","prep":"20 mins","cook":"25 mins","servings":"4","ingredients":["400g fresh bamboo shoots (labong, thinly sliced and parboiled)","4 cloves garlic (crushed)","1 onion (sliced)","3 tbsp cane vinegar","2 tbsp low-sodium soy sauce","1/2 cup water","1 tbsp oil","1 bay leaf","1/2 tsp whole peppercorns"],"steps":["Parboil sliced bamboo shoots in plain water for 15 minutes, then drain thoroughly to remove bitterness.","Heat oil in a skillet; sauté garlic and onion until golden.","Add drained bamboo shoots, bay leaf, and peppercorns; stir-fry for 3 minutes.","Pour in soy sauce, water, and cane vinegar. Allow to come to a boil uncovered for 3 minutes.","Lower heat, cover, and simmer for 10–12 minutes until liquid reduces."],"note":"Bamboo shoots are high in dietary fiber, potassium, and phytosterols, supporting lipid panel optimization.","id":"r270"},{"title":"Ginisang Pechay with Garlic","category":"side","prep":"8 mins","cook":"6 mins","servings":"4","ingredients":["3 bunches native pechay (bok choy, base trimmed and leaves separated)","6 cloves garlic (minced)","1 small red onion (sliced)","1 tbsp vegetable oil","1 tbsp oyster sauce","2 tbsp water","black pepper"],"steps":["Heat oil in a pan over medium heat. Sauté garlic until fragrant and light golden.","Add red onion and stir-fry for 1 minute.","Add pechay stems first with 2 tbsp water; stir-fry for 2 minutes.","Add pechay leaves and oyster sauce. Toss quickly for 1–2 minutes over high heat until leaves wilt. Season with pepper."],"note":"Cruciferous leaf vegetable loaded with bioavailable calcium, bioflavonoids, and vitamin K for bone health.","id":"r271"},{"title":"Ensaladang Kamoteng Kahoy (Sweet Potato Tops Salad)","category":"side","prep":"10 mins","cook":"5 mins","servings":"4","ingredients":["3 cups fresh talbos ng kamote (sweet potato tops, leaves and tender stems)","2 ripe tomatoes (chopped)","1 red onion (sliced)","3 tbsp cane vinegar","1 tbsp calamansi juice","1 tsp raw sugar","1/2 tsp salt"],"steps":["Blanch kamote tops in boiling salted water for 60–90 seconds. Immediately transfer to ice water to stop cooking; drain well.","Whisk vinegar, calamansi juice, raw sugar, and salt in a salad bowl to make dressing.","Add blanched tops, chopped tomatoes, and red onion into the bowl.","Toss gently to combine and serve chilled."],"note":"Talbos ng kamote is rich in lutein, polyphenols, and iron, supporting ophthalmic wellness and erythropoiesis.","id":"r272"},{"title":"Ginisang Kalabasa at Sitaw","category":"side","prep":"15 mins","cook":"18 mins","servings":"4","ingredients":["250g calabaza squash (peeled and diced)","150g sitaw (cut into 2-inch lengths)","4 cloves garlic (minced)","1 onion (sliced)","2 tomatoes (diced)","1 cup vegetable broth or water","1 tbsp canola oil","1 tbsp fish sauce","black pepper"],"steps":["Sauté garlic, onion, and tomatoes in canola oil until softened.","Add diced squash and cook for 3 minutes, stirring constantly.","Pour in vegetable broth and bring to a simmer. Cover and cook for 7 minutes until squash softens.","Add sitaw and fish sauce. Cook for 5 minutes until beans are tender-crisp and liquid reduces slightly."],"note":"Excellent nutrient-dense, low-fat side dish offering complex carbohydrates, carotenes, and soluble fiber.","id":"r273"},{"title":"Adobong Pusit Side Dish Portion","category":"side","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["300g small squid (cleaned, ink sacs preserved)","4 cloves garlic (crushed)","1 small onion (sliced)","3 tbsp cane vinegar","2 tbsp soy sauce","1 green chili","1 tbsp oil","ground black pepper"],"steps":["Heat oil in a pan over medium-high heat; sauté garlic and onion.","Add cleaned squid and toss quickly for 1 minute.","Pour in soy sauce, vinegar, and squid ink. Bring to a rapid boil uncovered for 2 minutes.","Add green chili and pepper. Simmer for an additional 3–4 minutes until squid is cooked through (do not overcook)."],"note":"Squid provides lean, high-biological-value protein, copper, selenium, and vitamin B12 in controlled side-dish portions.","id":"r274"},{"title":"Ensaladang Singkamas at Kamatis (Jicama Salad)","category":"side","prep":"15 mins","cook":"0 mins","servings":"4","ingredients":["1.5 cups jicama (singkamas, peeled and julienned)","2 firm tomatoes (diced)","1 small red onion (thinly sliced)","3 tbsp white coconut vinegar","1 tbsp lime or calamansi juice","1 tsp honey","1/4 tsp salt"],"steps":["Combine julienned jicama, diced tomatoes, and red onion in a glass bowl.","In a small cup, whisk together white vinegar, calamansi juice, honey, and salt.","Pour dressing over jicama mixture and mix thoroughly.","Refrigerate for 15 minutes before serving to crisp up."],"note":"Jicama is an outstanding source of inulin, a prebiotic soluble fiber that feeds beneficial gut microbiota.","id":"r275"},{"title":"Ginisang Togue (Sautéed Mung Bean Sprouts)","category":"side","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["300g mung bean sprouts (togue, rinsed and drained)","1/2 carrot (julienned)","1/2 cup firm tofu (cut into small cubes)","1/2 cup bell pepper (julienned)","3 cloves garlic (minced)","1 onion (sliced)","1 tbsp oil","1 tbsp soy sauce","salt and pepper"],"steps":["Pan-fry tofu cubes in oil until lightly golden; remove and set aside.","In the same pan, sauté garlic and onion. Add carrots and bell peppers; cook for 2 minutes.","Add mung bean sprouts and cooked tofu. Season with soy sauce, salt, and pepper.","Stir-fry over high heat for 2–3 minutes until sprouts are tender yet crunchy."],"note":"Germination increases bioavailability of vitamins C and B in mung beans while reducing anti-nutrients like phytic acid.","id":"r276"},{"title":"Tortang Talong (Eggplant Omelet - Side Portion)","category":"side","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["2 long purple eggplants","2 large eggs (beaten)","2 cloves garlic (minced)","1 small onion (minced)","1/2 tsp salt","1/4 tsp black pepper","1 tbsp olive oil"],"steps":["Broil or grill whole eggplants until charred; cool, peel skin, and mash flesh flat while leaving stem intact.","Beat eggs with garlic, onion, salt, and black pepper in a shallow dish.","Dip flattened eggplants into beaten egg mixture, coating thoroughly.","Heat olive oil in a skillet over medium heat. Fry eggplants for 3–4 minutes per side until golden brown."],"note":"Egg-wrapped eggplant provides dietary fiber along with high-quality ovalbumin protein, ideal as a nutrient-dense side plate.","id":"r277"},{"title":"Atcharang Ampalaya (Pickled Bitter Melon)","category":"side","prep":"20 mins","cook":"8 mins","servings":"8","ingredients":["1 large bitter gourd (ampalaya, halved, deseeded, and thinly sliced)","1/2 carrot (sliced into flowerets)","1/2 red bell pepper (julienned)","1 cup cane vinegar","3/4 cup raw sugar","1 tbsp coarse salt (for purging)","1 tsp sea salt (for brine)","3 cloves garlic"],"steps":["Toss ampalaya slices in coarse salt and let sit for 15 minutes. Squeeze out excess bitter liquid and rinse under cold water; drain well.","Pack ampalaya, carrots, bell pepper, and garlic into sterilized glass jars.","Simmer vinegar, sugar, and sea salt in a saucepan for 5 minutes until sugar dissolves.","Pour hot brine into packed jars, cover, and chill in refrigerator for 24 hours before serving."],"note":"Charantin and polypeptide-p present in bitter melon support peripheral glucose utilization and glycemic control.","id":"r278"},{"title":"Ginisang Patola with Misua (Dry Side Variation)","category":"side","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["1 large sponge gourd (patola, peeled and sliced into rounds)","1 bundle misua noodles","4 cloves garlic (minced)","1 onion (sliced)","1/2 cup water","1 tbsp oil","1 tbsp fish sauce","black pepper"],"steps":["Heat oil in a pan; sauté garlic and onion until translucent.","Add patola slices and stir-fry for 3 minutes.","Pour in water and fish sauce; simmer covered for 4 minutes until patola becomes translucent.","Add misua noodles, stir for 1–2 minutes until liquid is absorbed into a moist side-dish consistency, season with pepper, and remove from heat."],"note":"Low-calorie vegetable containing dietary fiber, vitamin C, and potassium, served in a high-density reduced-broth presentation.","id":"r279"},{"title":"Adobong Mushroom (Local Oyster Mushrooms)","category":"side","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["300g fresh oyster mushrooms (cleaned and torn into bite-sized strips)","6 cloves garlic (crushed)","3 tbsp cane vinegar","2 tbsp low-sodium soy sauce","1 bay leaf","1 tbsp canola oil","1/2 tsp cracked black peppercorns"],"steps":["Heat oil in a skillet over high heat. Add mushrooms and sear without crowding until edges brown (approx. 3 minutes).","Add crushed garlic, bay leaf, and peppercorns; sauté for 1 minute.","Pour low-sodium soy sauce and cane vinegar over mushrooms.","Allow vinegar to boil uncovered for 2 minutes without stirring, then lower heat and reduce sauce for 3 minutes."],"note":"Mushrooms supply ergosterol (pre-vitamin D), beta-glucans, and prebiotic fiber with zero cholesterol.","id":"r280"},{"title":"Ensaladang Labanos (Daikon Radish Salad)","category":"side","prep":"15 mins","cook":"0 mins","servings":"4","ingredients":["1 medium daikon radish (labanos, peeled and thinly sliced or julienned)","1 tomato (diced)","1 small red onion (sliced)","1/4 cup cane vinegar","1 tbsp honey","1/2 tsp salt","freshly ground black pepper"],"steps":["Sprinkle radish slices with a pinch of salt, let rest for 10 minutes, and squeeze out excess moisture.","In a bowl, combine cane vinegar, honey, salt, and black pepper.","Add squeezed radish, tomatoes, and red onion.","Toss well and refrigerate 20 minutes before serving."],"note":"Radishes contain glucosinolates and myrosinase, compounds known to support liver metabolic enzyme pathways.","id":"r281"},{"title":"Ginisang Broccoli at Cauliflower","category":"side","prep":"12 mins","cook":"10 mins","servings":"4","ingredients":["1.5 cups broccoli florets","1.5 cups cauliflower florets","4 cloves garlic (minced)","1 small onion (sliced)","1 tbsp sesame oil","1 tbsp light soy sauce","2 tbsp water","toasted sesame seeds (optional)"],"steps":["Blanch broccoli and cauliflower florets in boiling water for 1 minute; plunge into ice water and drain.","Heat sesame oil in a wok over medium-high heat. Sauté garlic and onion.","Add blanched brassica florets and light soy sauce with 2 tbsp water.","Stir-fry rapidly for 3 minutes until tender-crisp. Garnish with toasted sesame seeds."],"note":"High-density cruciferous combination delivering sulforaphane, indole-3-carbinol, and dietary fiber.","id":"r282"},{"title":"Ginisang Corn at Spinach","category":"side","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["1.5 cups sweet corn kernels (fresh or canned drained)","2 cups fresh spinach leaves (washed)","3 cloves garlic (minced)","1 small onion (diced)","1 tbsp olive oil or butter","1/4 cup low-fat milk","salt and black pepper"],"steps":["Heat olive oil in a pan over medium heat; sauté garlic and onion until tender.","Add corn kernels and stir-fry for 3–4 minutes.","Pour in low-fat milk and bring to a bare simmer.","Fold in fresh spinach leaves, stir until wilted (approx. 1 minute), season with salt and pepper, and serve."],"note":"Combines lutein and zeaxanthin from corn and spinach, promoting macular health and cellular protection.","id":"r283"},{"title":"Atcharang Labanos (Pickled Radish)","category":"side","prep":"20 mins","cook":"5 mins","servings":"8","ingredients":["2 cups daikon radish (julienned)","1/2 carrot (julienned)","1 cup cane vinegar","1/2 cup raw sugar","1 tbsp sea salt","1 thumb ginger (julienned)","3 cloves garlic (sliced)"],"steps":["Massage radish with salt, let stand 15 minutes, squeeze out liquid, and rinse.","Pack radish, carrots, ginger, and garlic tightly into clean jars.","Dissolve sugar and salt in cane vinegar in a saucepan over medium heat; simmer for 3 minutes.","Pour warm brine into jars, seal, and let cure in refrigerator for at least 12 hours."],"note":"Low-calorie digestive condiment that stimulates gastric acid secretion and enhances non-heme iron absorption.","id":"r284"},{"title":"Kangkong Chips (Air-Fried Water Spinach)","category":"side","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["3 cups large water spinach leaves (kangkong, washed and thoroughly dried)","3 tbsp cornstarch","1 tbsp rice flour","1/2 tsp garlic powder","1/2 tsp sea salt","1 tbsp olive oil spray"],"steps":["Ensure kangkong leaves are completely dry using paper towels.","Whisk cornstarch, rice flour, garlic powder, and salt in a wide bowl.","Lightly dust kangkong leaves with flour mixture, shaking off excess.","Arrange in a single layer in air fryer basket, spray lightly with olive oil, and air-fry at 160°C (320°F) for 6–8 minutes until crispy."],"note":"Air-frying reduces added fat content significantly compared to traditional deep-fat batter immersion.","id":"r285"},{"title":"Ginisang Sigarilyas (Winged Beans in Garlic)","category":"side","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["250g winged beans (sigarilyas, sliced crosswise)","5 cloves garlic (minced)","1 small red onion (sliced)","1 tomato (diced)","1 tbsp vegetable oil","1 tbsp fish sauce","1/4 cup water","ground black pepper"],"steps":["Heat oil in a pan; sauté garlic, onion, and tomato until softened.","Add sliced winged beans and stir-fry for 2 minutes.","Add fish sauce, black pepper, and water.","Cover and cook over medium heat for 4–5 minutes until beans are bright green and tender-crisp."],"note":"Winged beans offer exceptional protein content relative to other legumes, alongside substantial calcium and iron.","id":"r286"},{"title":"Kalabasa Patties (Steamed/Pan-Seared Squash Cakes)","category":"side","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["2 cups squash (steamed and mashed)","1/4 cup whole wheat flour or oat flour","1 egg (beaten)","2 green onions (finely chopped)","1/2 tsp garlic powder","salt and pepper","1 tbsp olive oil"],"steps":["In a bowl, combine mashed squash, flour, beaten egg, green onions, garlic powder, salt, and pepper until a moldable batter forms.","Shape mixture into small round patties.","Heat olive oil in a non-stick pan over medium heat.","Sear patties for 3–4 minutes per side until golden brown and firm."],"note":"Low-GI root vegetable alternative packed with dietary fiber, potassium, and provitamin A.","id":"r287"},{"title":"Ensaladang Lettuce with Calamansi Vinaigrette","category":"side","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["4 cups fresh green leaf lettuce (washed and torn)","1 firm tomato (sliced)","1/2 cucumber (sliced)","3 tbsp extra virgin olive oil","2 tbsp fresh calamansi juice","1 tsp wild honey","salt and black pepper"],"steps":["Whisk extra virgin olive oil, calamansi juice, honey, salt, and pepper together until emulsified.","Place lettuce, tomatoes, and cucumber in a salad bowl.","Drizzle calamansi vinaigrette over fresh greens right before serving and toss lightly."],"note":"Provides heart-healthy monounsaturated fatty acids (MUFAs) combined with fresh vitamin C to maximize nutrient absorption.","id":"r288"},{"title":"Ginisang Upo (Sautéed Bottle Gourd)","category":"side","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["400g bottle gourd (upo, peeled, deseeded, and diced)","4 cloves garlic (minced)","1 onion (sliced)","2 tomatoes (diced)","1 tbsp canola oil","1 tbsp fish sauce","1/2 cup water","black pepper"],"steps":["Heat oil in a pan over medium heat; sauté garlic, onion, and tomatoes until soft.","Add diced upo and stir for 2 minutes.","Add fish sauce, water, and pepper. Cover pan and simmer over medium-low heat for 8–10 minutes until upo becomes translucent and tender."],"note":"Bottle gourd has high water content and low caloric density, making it soothing for renal and digestive care protocols.","id":"r289"},{"title":"Adobong Puso ng Saging","category":"side","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["1 banana blossom (puso ng saging, outer bracts removed, core finely sliced)","4 cloves garlic (crushed)","1 onion (sliced)","3 tbsp cane vinegar","2 tbsp low-sodium soy sauce","1/2 cup water","1 tbsp oil","black pepper"],"steps":["Soak sliced banana blossom in salted water for 15 minutes, then squeeze firmly to remove bitter sap; drain well.","Heat oil in a pan; sauté garlic and onion.","Add squeezed banana blossom and toss for 3 minutes.","Pour in soy sauce, water, and vinegar. Bring to a boil uncovered for 3 minutes without stirring.","Lower heat, cover, and simmer for 10 minutes until tender."],"note":"Rich in dietary fiber, flavanoids, and essential minerals; supports healthy lipid regulation.","id":"r290"},{"title":"Pritong Santol (Sautéed Cotton Fruit Pulp)","category":"side","prep":"25 mins","cook":"20 mins","servings":"4","ingredients":["3 fresh santol fruits (peeled, seeds removed, pericarp finely minced and squeezed of excess sour juice)","3 cloves garlic","1 onion","1 red chili (sliced)","1/2 cup light coconut milk","1 tbsp fish sauce","1 tbsp cooking oil"],"steps":["Sauté garlic, onion, and chili in oil until fragrant.","Add minced santol pericarp and stir-fry for 3 minutes.","Add fish sauce and light coconut milk.","Simmer over low heat for 12–15 minutes until liquid reduces and santol pulp absorbs coconut milk."],"note":"Santol pericarp contains bioflavonoids, pectin, and dietary fiber, providing a unique sweet-sour dietary profile.","id":"r291"},{"title":"Ginisang Baguio Beans (Green Beans)","category":"side","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["250g Baguio snap beans (trimmed and cut diagonally)","4 cloves garlic (minced)","1 small red onion (sliced)","1 tbsp vegetable oil","1 tbsp light soy sauce","2 tbsp water","black pepper"],"steps":["Heat oil in a pan; sauté garlic and onion until golden.","Add green beans and stir-fry for 2 minutes over medium-high heat.","Add light soy sauce, water, and pepper.","Cover and cook for 4–5 minutes until green beans are bright green and crisp-tender."],"note":"Snap beans are high in silicon, vitamin K, and lutein, promoting vascular health and bone mineral density.","id":"r292"},{"title":"Ensaladang Lato (Sea Grape Salad)","category":"side","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["2 cups fresh sea grapes (lato, washed thoroughly in cold water)","2 ripe tomatoes (diced)","1 small red onion (thinly sliced)","3 tbsp native cane vinegar","1 tsp sugar or honey"],"steps":["Rinse sea grapes quickly under cold filtered water; drain immediately (do not soak to avoid collapse of beads).","Mix cane vinegar and sugar in a small cup.","Arrange lato on a plate topped with diced tomatoes and red onion.","Pour vinegar dressing over salad immediately prior to consumption."],"note":"Exceptionally rich in iodine, trace sea minerals, omega-3 fatty acids, and vitamin A.","id":"r293"},{"title":"Ginisang Sigarilyas sa Gata","category":"side","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["250g winged beans (sigarilyas, sliced)","1 cup light coconut milk","3 cloves garlic (minced)","1 onion (sliced)","1 green chili","1 tbsp fish sauce","1 tbsp cooking oil"],"steps":["Heat oil in a pan; sauté garlic and onion until soft.","Add winged beans and stir-fry for 2 minutes.","Pour in light coconut milk and fish sauce; add green chili.","Simmer covered over low heat for 8–10 minutes until the sauce thickens slightly."],"note":"Combines plant protein and calcium from winged beans with coconut milk fat for enhanced fat-soluble nutrient delivery.","id":"r294"},{"title":"Atcharang Singkamas (Pickled Jicama)","category":"side","prep":"20 mins","cook":"5 mins","servings":"8","ingredients":["2 cups jicama (singkamas, peeled and julienned)","1/2 carrot (julienned)","1 cup cane vinegar","1/2 cup sugar","1 tbsp salt","1 thumb ginger (julienned)"],"steps":["Combine julienned jicama, carrots, and ginger in a glass container.","Heat cane vinegar, sugar, and salt in a pan until completely dissolved.","Pour warm pickle brine over packed vegetables.","Cool, seal, and refrigerate for 12 hours prior to serving."],"note":"Crisp, low-calorie pickled side dish rich in prebiotic inulin to support lower gastrointestinal microflora balance.","id":"r295"},{"title":"Ginisang Malunggay at Mais","category":"side","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["1.5 cups white sweet corn kernels (scraped from cob)","2 cups fresh moringa leaves (malunggay, stemmed)","3 cloves garlic (minced)","1 onion (sliced)","1 cup water","1 tbsp oil","salt and pepper"],"steps":["Sauté garlic and onion in oil until fragrant.","Add corn kernels and stir-fry for 3 minutes.","Add water, cover, and cook for 5–7 minutes until corn is tender.","Stir in malunggay leaves, season with salt and pepper, turn off heat, and cover for 2 minutes to steam leaves."],"note":"Moringa oleifera is a local superfood loaded with iron, calcium, vitamin C, and essential amino acids.","id":"r296"},{"title":"Roasted Kamote Wedges with Salt & Chili","category":"side","prep":"10 mins","cook":"25 mins","servings":"4","ingredients":["2 medium orange or purple sweet potatoes (kamote, scrubbed and cut into wedges)","1 tbsp olive oil","1/2 tsp chili powder","1/2 tsp garlic powder","1/2 tsp sea salt"],"steps":["Preheat the oven to 200°C (400°F) or preheat the air fryer to 190°C (375°F).","Toss kamote wedges with olive oil, chili powder, garlic powder, and sea salt.","Arrange in a single layer on a parchment-lined baking sheet or air fryer basket.","Bake for 20–25 minutes (or air-fry for 15–18 minutes), turning halfway through until crispy on edges and tender inside."],"note":"Low-glycemic complex carbohydrate alternative rich in beta-carotene, anthocyanins, and dietary fiber.","id":"r297"},{"title":"Adobong Asparagus (Benguet Style)","category":"side","prep":"10 mins","cook":"8 mins","servings":"4","ingredients":["250g fresh Benguet asparagus spears (woody ends snapped off, cut into 2-inch lengths)","5 cloves garlic (minced)","2 tbsp cane vinegar","1.5 tbsp low-sodium soy sauce","1 tbsp olive oil","black pepper"],"steps":["Heat olive oil in a skillet over medium-high heat; sauté garlic until light golden.","Add asparagus spears and stir-fry for 2 minutes.","Add low-sodium soy sauce and cane vinegar. Allow vinegar to simmer uncovered for 2 minutes.","Season with black pepper, toss quickly, and transfer to a serving dish."],"note":"Asparagus provides asparagine, folate, and chromium, aiding insulin sensitivity and fluid balance modulation.","id":"r298"},{"title":"Ensaladang Suha at Pipino (Pomelo Cucumber Salad)","category":"side","prep":"15 mins","cook":"0 mins","servings":"4","ingredients":["1.5 cups pink pomelo segments (suha, broken into bite-sized chunks)","1 large cucumber (thinly sliced)","1 small red onion (sliced)","2 tbsp calamansi juice","1 tbsp raw honey","1 tsp fish sauce","fresh mint leaves"],"steps":["Combine pomelo segments, sliced cucumber, and red onion in a salad bowl.","Whisk calamansi juice, raw honey, and fish sauce together.","Pour dressing over salad, toss gently, and garnish with fresh mint leaves."],"note":"High vitamin C and bioflavonoid density; natural potassium from pomelo supports electrolyte stability.","id":"r299"},{"title":"Steamed Okra with Calamansi Dip","category":"side","prep":"5 mins","cook":"6 mins","servings":"4","ingredients":["12 fresh young okra pods","3 tbsp fresh calamansi juice","1 tbsp low-sodium soy sauce or tamari","1 red chili (minced, optional)"],"steps":["Wash okra thoroughly and trim top stems without exposing seed cavity.","Place in a steamer basket over boiling water and steam for 5–6 minutes until tender yet bright green.","Whisk calamansi juice, low-sodium soy sauce, and minced chili in a small bowl.","Serve steamed okra whole alongside calamansi soy dip."],"note":"Minimalist preparation preserving water-soluble vitamins (C and B-complex) and mucilage fiber for optimal GI health. APPETIZERS:","id":"r300"},{"title":"Lumpiang Shanghai (Filipino Pork Spring Rolls)","category":"appetizer","prep":"30 mins","cook":"15 mins","servings":"8","ingredients":["500g ground pork (lean)","1 cup carrots (finely minced)","1 cup onion (finely minced)","2 eggs","1 tbsp soy sauce","1 tsp garlic powder","salt","pepper","spring roll wrappers","cooking oil"],"steps":["Combine ground pork, carrots, onion, eggs, soy sauce, garlic powder, salt, and pepper in a bowl.","Spoon 1 tbsp filling along the edge of a spring roll wrapper, roll tightly, and seal edge with water.","Cut rolls into 2-inch pieces.","Pan-fry or air-fry at 180°C for 12–15 minutes until golden brown and cooked through."],"note":"Lean meat reduction paired with increased vegetable ratio improves protein-to-fat proportion.","id":"r301"},{"title":"Tokwa't Baboy (Tofu and Pork Bites)","category":"appetizer","prep":"15 mins","cook":"25 mins","servings":"6","ingredients":["400g firm tofu (cut into cubes)","300g pork shoulder (boiled and cubed)","1 cup cane vinegar","1/2 cup soy sauce","1 red onion (diced)","2 green chilies (sliced)","1 tbsp sugar"],"steps":["Pan-fry tofu cubes in minimal oil until golden and crispy; drain on paper towels.","Boil pork shoulder until tender, then cube.","In a bowl, mix vinegar, soy sauce, red onion, green chilies, and sugar.","Combine warm tofu and boiled pork in a dish and pour dressing over."],"note":"High-protein appetizer pairing soy-based isoflavones with lean animal protein.","id":"r302"},{"title":"Ukoy (Vegetable & Shrimp Fritters)","category":"appetizer","prep":"20 mins","cook":"15 mins","servings":"6","ingredients":["1 cup small shrimps (heads removed, shells on)","1 cup sweet potato (julienned)","1 cup bean sprouts","1/2 cup cornstarch","1/4 cup rice flour","1 egg","1/2 cup cold water","salt and pepper","oil for pan-frying"],"steps":["Whisk cornstarch, rice flour, egg, water, salt, and pepper into a smooth batter.","Fold in sweet potato, bean sprouts, and small shrimps.","Ladle portions into medium-hot oil and pan-fry for 3 minutes per side until crispy.","Serve with garlic-vinegar dipping sauce."],"note":"Complex carbohydrates from sweet potato provide a lower glycemic load than all-wheat flour alternatives.","id":"r303"},{"title":"Kinilaw na Tanigue (Filipino Fish Ceviche)","category":"appetizer","prep":"20 mins","cook":"0 mins","servings":"4","ingredients":["400g fresh Tanigue / Spanish Mackerel (cubed)","1 cup cane vinegar","1 thumb ginger (minced)","1 red onion (diced)","2 green chilies (sliced)","3 calamansi (juiced)","salt and white pepper"],"steps":["Wash cubed fresh fish in 1/2 cup vinegar, then drain completely and discard used vinegar.","Add remaining vinegar, calamansi juice, ginger, red onion, chilies, salt, and pepper to the fish.","Toss gently, cover, and chill in the refrigerator for 20 minutes to cure before serving."],"note":"High in Omega-3 fatty acids; zero added cooking oils.","id":"r304"},{"title":"Dynamite Lumpia (Stuffed Green Chili Rolls)","category":"appetizer","prep":"25 mins","cook":"10 mins","servings":"6","ingredients":["12 large green chilies (Siling Haba)","150g quick-melt low-fat cheese or seasoned ground chicken","spring roll wrappers","oil for frying"],"steps":["Make a longitudinal slit in each chili and carefully remove seeds.","Stuff each chili with a strip of cheese or cooked ground chicken.","Wrap tightly in lumpia wrappers, sealing edges with water.","Pan-fry until the wrapper is golden and the cheese is melted."],"note":"Capsaicin in green chilies stimulates metabolic rate and gastric motility.","id":"r305"},{"title":"Crispy Kangkong with Calamansi Mayo Dip","category":"appetizer","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["2 bunches water spinach leaves","1/2 cup cornstarch","1/4 cup flour","1/2 cup ice water","light mayonnaise + calamansi juice for dip"],"steps":["Whisk cornstarch, flour, and ice water into a light batter.","Dip clean, dry kangkong leaves into batter, shaking off excess.","Shallow-fry or air-fry until crisp. Drain well.","Serve immediately with light calamansi mayonnaise."],"note":"Air-frying reduces fat retention while preserving leaf crispness.","id":"r306"},{"title":"Chicharon Bulaklak","category":"appetizer","prep":"30 mins","cook":"40 mins","servings":"6","ingredients":["500g pork mesentery","1 tbsp salt","1 tsp peppercorns","4 bay leaves","vinegar dipping sauce"],"steps":["Boil mesentery in water with salt, peppercorns, and bay leaves for 30 minutes until tender. Drain and pat dry completely.","Cut into bite-sized pieces.","Air-fry at 200°C for 15–20 minutes, flipping halfway until puffed and crispy."],"note":"Air-frying renders out excess structural fat compared to traditional deep frying.","id":"r307"},{"title":"Calamares","category":"appetizer","prep":"15 mins","cook":"5 mins","servings":"4","ingredients":["400g squid rings","1/2 cup flour","1 tsp garlic powder","1 egg (beaten)","1/2 cup breadcrumbs","calamansi wedges"],"steps":["Dredge squid rings in seasoned flour, dip in beaten egg, and coat with breadcrumbs.","Shallow fry in hot oil for 1–2 minutes until golden (do not overcook to avoid toughness).","Serve warm with calamansi wedges."],"note":"Good source of lean protein, zinc, and selenium.","id":"r308"},{"title":"Gambas al Ajillo (Filipino-Spanish Garlic Shrimp)","category":"appetizer","prep":"10 mins","cook":"8 mins","servings":"4","ingredients":["300g medium shrimp (peeled and deveined)","8 cloves garlic (sliced)","1 tbsp olive oil","1 tsp paprika","1 red chili","salt"],"steps":["Heat olive oil in a skillet over low heat; add garlic and cook until fragrant and light brown.","Increase heat to medium, add shrimp, paprika, and chilies.","Cook for 3–4 minutes until shrimp turn pink. Season with salt."],"note":"Heart-healthy monounsaturated fats from olive oil paired with high-value shrimp protein.","id":"r309"},{"title":"Adobong Mani (Garlic Fried Peanuts)","category":"appetizer","prep":"5 mins","cook":"10 mins","servings":"8","ingredients":["2 cups raw skin-on peanuts","10 cloves garlic (unpeeled, crushed)","1 tbsp oil","sea salt"],"steps":["Heat oil in a pan over medium-low heat.","Add raw peanuts and garlic. Toast slowly, stirring continuously for 8–10 minutes.","Drain excess oil on paper towels and toss with sea salt."],"note":"Nutrient-dense snack packed with plant protein, vitamin E, and healthy fats.","id":"r310"},{"title":"Inihaw na Pusit Bites","category":"appetizer","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["400g medium squid (cleaned, cut into bite-sized rings)","1 small red onion (minced)","2 ripe tomatoes (diced)","2 tbsp calamansi juice","2 tbsp soy sauce","1 tsp ground black pepper","wooden skewers"],"steps":["Marinate squid rings in calamansi juice, soy sauce, and black pepper for 10 minutes.","Thread 3–4 squid rings per wooden skewer along with diced onions and tomatoes.","Grill over high direct heat for 3–4 minutes per side until charred and firm. Avoid overcooking to maintain tenderness."],"note":"High in high-biological-value protein and selenium; low in dietary fat. Charring over high heat minimizes added fat while boosting flavor density.","id":"r311"},{"title":"Siomai (Steamed Pork & Shrimp Dim Sum)","category":"appetizer","prep":"25 mins","cook":"20 mins","servings":"6","ingredients":["300g lean ground pork","150g shrimp (peeled, deveined, finely chopped)","1/2 cup jicama (singkamas, finely grated)","1 egg","2 tbsp sesame oil","1 tbsp soy sauce","30 wonton wrappers"],"steps":["Mix ground pork, chopped shrimp, grated jicama, egg, sesame oil, and soy sauce in a bowl until cohesive.","Spoon 1 tablespoon of mixture onto each wonton wrapper and pleat edges upward leaving the top open.","Arrange in a steamer basket lined with parchment paper. Steam over boiling water for 18–20 minutes until thoroughly cooked."],"note":"Substituting jicama for pork fat adds crunch and moisture while delivering dietary fiber and keeping saturated fat within therapeutic limits.","id":"r312"},{"title":"Chicken Skin Crisp (Baked/Air-Fried)","category":"appetizer","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["400g clean chicken skin (fat trimmed)","1 tsp sea salt","1/2 tsp garlic powder","1/2 tsp black pepper","1 tbsp cane vinegar for dipping"],"steps":["Blanch chicken skin in boiling salted water for 3 minutes; drain and pat thoroughly dry with paper towels.","Toss skin with sea salt, garlic powder, and black pepper.","Arrange single-layer in an air-fryer basket or baking sheet. Air-fry at 190°C (375°F) for 20–25 minutes, flipping halfway, until fat renders completely and skin turns crispy."],"note":"Rendering out excess subcutaneous lipids via air-frying drastically lowers total fat compared to traditional deep-frying methods.","id":"r313"},{"title":"Tortang Dulong (Fish Patties)","category":"appetizer","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["300g fresh dulong (noodlefish/lacustrine goby, rinsed)","2 eggs (beaten)","1/4 cup scallions (chopped)","2 tbsp cornstarch","1/2 tsp salt","1/4 tsp white pepper","1 tbsp cooking oil"],"steps":["Whisk eggs, cornstarch, scallions, salt, and white pepper in a medium bowl.","Fold in cleaned dulong gently to combine.","Heat oil in a non-stick skillet over medium heat. Drop mixture by tablespoonfuls and flatten slightly.","Pan-fry for 3 minutes per side until light golden brown and set."],"note":"Highly bioavailable source of calcium, phosphorus, and whole-fish micronutrients because bones are fully soft and edible.","id":"r314"},{"title":"Stuffed Squid Bites","category":"appetizer","prep":"20 mins","cook":"12 mins","servings":"4","ingredients":["400g small squids (cleaned)","1/2 cup firm tofu (crumbled)","1/4 cup tomatoes (diced)","2 tbsp red onion (minced)","1 tbsp scallions (chopped)","1 tsp fish sauce","toothpicks"],"steps":["Combine crumbled tofu, tomatoes, onion, scallions, and fish sauce in a small bowl.","Stuff each squid cavity with tofu mixture (filling to 3/4 capacity to allow for shrinkage). Secure open end with toothpicks.","Pan-sear or grill over medium heat for 5–6 minutes per side until opaque and cooked through. Cut into bite-sized segments before serving."],"note":"Plant-protein extension using tofu increases total fiber and lowers cholesterol density of whole squid dishes.","id":"r315"},{"title":"Crispy Tofu Sticks with Spicy Dip","category":"appetizer","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["400g firm block tofu (cut into 1/2-inch sticks)","2 tbsp cornstarch","1/2 tsp paprika","1/2 tsp garlic powder","1/4 cup cane vinegar","1 red chili (minced)","salt"],"steps":["Press tofu between paper towels for 10 minutes to drain excess moisture.","Toss tofu sticks in a mixture of cornstarch, paprika, garlic powder, and salt until lightly coated.","Air-fry at 200°C (400°F) for 12–15 minutes, shaking the basket halfway until crispy.","Whisk cane vinegar, minced chili, and a pinch of salt to serve as dipping sauce."],"note":"Pure plant-based protein appetizer providing essential isoflavones and low saturated fat; suited for cardiovascular management diets.","id":"r316"},{"title":"Fish Balls with Homemade Sweet & Sour Sauce","category":"appetizer","prep":"20 mins","cook":"12 mins","servings":"6","ingredients":["300g white fish fillet (tilapia/cream dory, ground)","2 tbsp tapioca starch","1 egg white","1 tsp salt","1/4 tsp white pepper","## Sauce","1/2 cup water","2 tbsp cane vinegar","2 tbsp brown sugar","1 tbsp banana ketchup","1 tsp cornstarch"],"steps":["Blend fish fillet, tapioca starch, egg white, salt, and pepper in a food processor until smooth paste forms. Roll into small balls.","Poach balls in simmering water for 5 minutes until they float; remove and drain.","Simmer sauce ingredients in a small pan over medium heat for 3–4 minutes until clear and thickened.","Air-fry or pan-sear poached fish balls for 3 minutes for crispiness, then serve on skewers with warm sauce."],"note":"Homemade preparation avoids artificial binders and high-sodium commercial additives, facilitating sodium control.","id":"r317"},{"title":"Kikiam (Filipino Style Veggie/Pork Rolls)","category":"appetizer","prep":"25 mins","cook":"20 mins","servings":"6","ingredients":["200g lean ground pork","100g minced shrimp","1/2 cup carrots (grated)","1/2 cup water chestnuts (minced)","1/2 tsp five-spice powder","1 egg","bean curd sheets (tau kwan/bean curd skin)"],"steps":["Mix pork, shrimp, carrots, water chestnuts, five-spice powder, and egg until sticky.","Wrap mixture tightly into log shapes using bean curd sheets.","Steam logs for 15 minutes to set structure. Cool and slice into 1-inch pieces.","Lightly pan-sear in a non-stick pan for 2–3 minutes per side until wrapper turns golden brown."],"note":"Incorporating water chestnuts and carrots increases moisture and fiber while five-spice provides antioxidant compounds.","id":"r318"},{"title":"Lumpiang Sariwa Skewers (Fresh Spring Roll Bite)","category":"appetizer","prep":"25 mins","cook":"10 mins","servings":"6","ingredients":["1 cup sweet potato (julienned)","1 cup green beans (thinly sliced)","1 cup cabbage (shredded)","100g tofu (cubed)","6 homemade crepe wrappers","1/4 cup peanut dipping sauce","wooden skewers"],"steps":["Sauté tofu, sweet potato, green beans, and cabbage until tender-crisp.","Spoon 2 tablespoons of cooked vegetable mixture onto each wrapper, roll tightly, and seal.","Slice rolls into 1-inch bite pieces and thread onto mini skewers.","Drizzle lightly with garlic-peanut sauce before serving."],"note":"Nutrient-rich, non-fried spring roll delivering high dietary fiber, complex carbohydrates, and essential beta-carotene.","id":"r319"},{"title":"Grilled Pork BBQ Skewers (Mini Appetizer Portions)","category":"appetizer","prep":"20 mins","cook":"10 mins","servings":"6","ingredients":["400g lean pork tenderloin (thinly sliced into ribbons)","2 tbsp calamansi juice","3 tbsp soy sauce","2 cloves garlic (minced)","1 tbsp brown sugar","1 tbsp banana ketchup","mini bamboo skewers"],"steps":["Marinate pork slices in calamansi juice, soy sauce, garlic, brown sugar, and banana ketchup for at least 2 hours.","Thread meat ribbons onto soaked bamboo skewers.","Grill over hot coals or hot grill pan for 3–4 minutes per side, basting with remaining marinade until cooked through."],"note":"Pork tenderloin offers a lean animal protein foundation. Portion-controlled mini skewers help keep calorie intake balanced.","id":"r320"},{"title":"Baked Tahong (Garlic Cheese Mussels)","category":"appetizer","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["500g green mussels (tahong, cleaned on half shell)","2 tbsp butter (softened)","4 cloves garlic (minced)","1/4 cup low-fat quick-melt cheese (grated)","1 tbsp parsley (chopped)"],"steps":["Steam cleaned mussels for 3 minutes until shells open; discard unopened ones and detach top shells.","Mix softened butter and minced garlic together. Spread a thin layer over each mussel meat.","Top each mussel with grated low-fat cheese and chopped parsley.","Bake at 200°C (400°F) for 5–7 minutes until the cheese is melted and bubbling."],"note":"Excellent source of zinc, iron, and vitamin B12; low-fat cheese substitution manages total saturated fat load.","id":"r321"},{"title":"Nilasing na Hipon (Crispy Drunken Shrimp)","category":"appetizer","prep":"15 mins","cook":"5 mins","servings":"4","ingredients":["300g small medium shrimp (heads and shells intact, antennae trimmed)","3 tbsp cooking wine or tuba","2 tbsp cornstarch","1/2 tsp salt","1/4 tsp black pepper","oil spray for air-frying"],"steps":["Marinate trimmed shrimp in cooking wine for 15 minutes; drain thoroughly.","Toss shrimp with cornstarch, salt, and black pepper to coat outer shell evenly.","Arrange in a single layer in the air fryer, spray lightly with cooking oil spray.","Air-fry at 200°C (400°F) for 5–6 minutes until crisp and orange."],"note":"Consuming whole shrimp with shells provides structural chitin and calcium while air-frying cuts extraneous oil.","id":"r322"},{"title":"Inihaw na Liempo Bites","category":"appetizer","prep":"15 mins","cook":"15 mins","servings":"6","ingredients":["400g lean pork belly cuts (excess outer fat trimmed, cut into bite cubes)","3 tbsp cane vinegar","2 tbsp soy sauce","1 tsp black peppercorns (crushed)","3 cloves garlic (crushed)"],"steps":["Marinate trimmed pork belly cubes in vinegar, soy sauce, crushed garlic, and black pepper for 1 hour.","Thread 2–3 cubes per mini skewer.","Grill over medium-high heat for 12–15 minutes, turning frequently to render fat and char edges evenly."],"note":"Trimming outer subcutaneous fat layers combined with high-heat grilling renders down internal lipids for lower overall fat consumption.","id":"r323"},{"title":"Chicken Lollipop Tagalog","category":"appetizer","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["8 chicken wings (frenched into lollipops)","2 tbsp calamansi juice","1 tbsp patis (fish sauce)","1/2 tsp garlic powder","2 tbsp rice flour","oil for shallow frying"],"steps":["Cut wing joints and push meat down to one end of bone to form lollipop shape.","Marinate chicken lollipops in calamansi juice, fish sauce, and garlic powder for 20 minutes.","Dust meat ends lightly with rice flour.","Shallow fry or air-fry at 190°C for 15 minutes until skin is crispy and internal temperature reaches 74°C (165°F)."],"note":"Rice flour coating creates a light barrier preventing excessive oil absorption compared to heavy wheat batters.","id":"r324"},{"title":"Bola-Bola (Filipino Meatballs)","category":"appetizer","prep":"20 mins","cook":"12 mins","servings":"6","ingredients":["300g lean ground beef","100g ground turkey or pork","1/4 cup carrots (minced)","1/4 cup onion (minced)","1 egg","2 tbsp breadcrumbs","1/2 tsp salt","black pepper"],"steps":["Combine ground meats, carrots, onion, egg, breadcrumbs, salt, and pepper in a bowl. Mix thoroughly.","Shape mixture into small 1-inch meatballs.","Bake on a lined tray at 200°C (400°F) for 12 minutes or air-fry for 10 minutes until golden brown and cooked through."],"note":"Blending turkey/lean beef with vegetable aromatics increases micronutrient density while mitigating saturated fat levels.","id":"r325"},{"title":"Croquetas de Jamon y Queso (Filipino Style)","category":"appetizer","prep":"30 mins","cook":"10 mins","servings":"6","ingredients":["2 cups boiled sweet potato or yellow sweet potato (mashed)","1/2 cup sweet ham (diced)","1/4 cup low-fat cheddar cheese (diced)","1 egg (beaten)","1/2 cup panko breadcrumbs"],"steps":["Combine mashed sweet potato and diced ham.","Form 1-inch balls, inserting a small cube of low-fat cheese into center of each ball.","Dip balls in beaten egg and coat evenly with panko breadcrumbs.","Air-fry at 190°C (375°F) for 8–10 minutes until crisp and golden brown."],"note":"Replaces traditional white flour Béchamel base with mashed sweet potatoes, supplying dietary potassium and complex low-GI carbohydrates.","id":"r326"},{"title":"Empanaditas (Mini Chicken Meat Pastries)","category":"appetizer","prep":"35 mins","cook":"15 mins","servings":"8","ingredients":["## Dough","1.5 cups whole wheat flour","1/4 cup olive oil","1/3 cup cold water","pinch salt","## Filling","150g ground chicken","1/4 cup raisins","1/4 cup green peas","1/4 cup potatoes (diced)","1 tbsp soy sauce"],"steps":["Sauté ground chicken, potatoes, green peas, raisins, and soy sauce until dry; cool completely.","Mix flour, oil, salt, and cold water to form dough; roll thin and cut into 2-inch circles.","Place 1 teaspoon filling on a dough circle, fold into half-moon, and crimp edges with a fork.","Brush with egg wash and bake at 190°C (375°F) for 15 minutes until golden brown."],"note":"Whole-wheat pastry dough increases total dietary fiber, supporting smooth postprandial glucose regulation.","id":"r327"},{"title":"Crispy Kapa-Kapa / Baby Crab","category":"appetizer","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["300g fresh baby crabs (cleaned, halves)","2 tbsp calamansi juice","3 tbsp cornstarch","1/2 tsp chili powder","1/2 tsp salt","oil spray"],"steps":["Toss cleaned baby crabs with calamansi juice, salt, and chili powder.","Dust evenly with cornstarch, shaking off excess.","Arrange in an air fryer basket in a single layer and spray lightly with cooking oil.","Air-fry at 200°C (400°F) for 8 minutes until thoroughly crisp. Serve with spiced vinegar."],"note":"Exceptionally rich in structural bio-available calcium and marine minerals due to edible shell composition.","id":"r328"},{"title":"Kilawin na Hipon (Shrimp Ceviche)","category":"appetizer","prep":"20 mins","cook":"0 mins","servings":"4","ingredients":["300g fresh wild shrimp (peeled, deveined, butterflied)","3/4 cup cane vinegar","1 tbsp ginger (minced)","1 red onion (diced)","1 cucumber (seeded, diced)","2 calamansi (juiced)","salt and pepper"],"steps":["Soak shrimp in 1/4 cup vinegar for 5 minutes, squeeze gently, and drain off liquid completely.","Pour remaining 1/2 cup fresh vinegar and calamansi juice over shrimp.","Add minced ginger, red onion, and diced cucumber.","Season with salt and pepper; toss gently and refrigerate for 15 minutes to cure before serving."],"note":"Zero added oil preparation method; high lean protein yield retaining native heat-sensitive vitamin structures.","id":"r329"},{"title":"Adobong Chicken Wings","category":"appetizer","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["500g chicken wing mid-joints","3 tbsp cane vinegar","3 tbsp low-sodium soy sauce","5 cloves garlic (crushed)","2 bay leaves","1 tsp whole black peppercorns","1/2 cup water"],"steps":["Simmer chicken wings with vinegar, soy sauce, garlic, bay leaves, peppercorns, and water in a pan covered for 15 minutes.","Remove wings from pan, transfer liquid to small pot to reduce into thick glaze.","Air-fry wings at 200°C for 6 minutes to crisp skin.","Toss crispy wings in reduced adobo glaze before serving."],"note":"Utilizing low-sodium soy sauce and air-frying helps mitigate excessive sodium intake while eliminating deep-frying oils.","id":"r330"},{"title":"Crispy Crickets / Camaro (Pampanga Style)","category":"appetizer","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["200g field crickets (camaro, thoroughly cleaned, wings/legs trimmed)","2 tbsp cane vinegar","3 cloves garlic (minced)","1/4 cup tomatoes (chopped)","1 tsp cooking oil","salt"],"steps":["Simmer cleaned crickets in vinegar and minced garlic for 5 minutes until liquid evaporates.","Heat oil in a skillet; sauté chopped tomatoes until soft.","Add simmered crickets to the skillet and stir-fry over medium-high heat for 5 minutes until crisp. Season with salt."],"note":"High-density alternative protein source loaded with essential amino acids, iron, chitin fiber, and B-complex vitamins.","id":"r331"},{"title":"Spiced Chicharon Toast","category":"appetizer","prep":"10 mins","cook":"6 mins","servings":"4","ingredients":["4 slices whole-grain baguette","2 tbsp light cream cheese","2 tbsp air-fried pork chicharon (crushed)","1 tbsp spring onions (sliced)","chili flakes"],"steps":["Toast baguette slices until crisp.","Spread light cream cheese evenly over toasted slices.","Top generously with crushed air-fried chicharon, spring onions, and a sprinkle of chili flakes.","Cut into bite-sized appetizer toasts."],"note":"High-fiber whole grain base offsets dense savory toppings, keeping glycemic impact low while providing textural contrast.","id":"r332"},{"title":"Inihaw na Isaw (Cleaned Chicken Intestine Skewers)","category":"appetizer","prep":"30 mins","cook":"10 mins","servings":"4","ingredients":["300g chicken intestines (thoroughly cleaned, boiled in ginger water)","2 tbsp vinegar","2 tbsp soy sauce","1 tsp garlic powder","1/2 tsp black pepper","skewers"],"steps":["Coiling boiled intestines onto wooden skewers.","Mix vinegar, soy sauce, garlic powder, and black pepper; brush over skewers.","Grill over hot charcoal for 3–4 minutes per side until outer edges turn crispy and charred."],"note":"Thorough boiling with ginger extracts impurities; grilled preparation ensures moderate fat rendering.","id":"r333"},{"title":"Lumpiang Isda (Fish Lumpia)","category":"appetizer","prep":"20 mins","cook":"10 mins","servings":"6","ingredients":["300g cooked fish flakes (tinapa or steamed tilapia)","1/2 cup carrots (minced)","1/4 cup kinchay/celery (minced)","1 egg","spring roll wrappers","oil for shallow frying"],"steps":["Combine fish flakes, carrots, kinchay, and egg in a bowl.","Spoon filling onto wrappers, roll tightly, and seal edges with water.","Shallow-fry or air-fry at 190°C for 8–10 minutes until golden and crisp."],"note":"Lean marine protein combined with apiaceous herbs (kinchay) provides cardiovascular benefits and phytonutrients.","id":"r334"},{"title":"Sizzling Sisig Bites (Lean Pork/Tofu)","category":"appetizer","prep":"20 mins","cook":"15 mins","servings":"6","ingredients":["200g boiled lean pork mask/shoulder (diced finely)","200g firm tofu (cubed, crisp-cooked, diced)","1 red onion (diced)","2 green chilies (sliced)","2 tbsp calamansi juice","1 tbsp light mayonnaise","salt and pepper"],"steps":["Grill or sear pork until charred; dice into small bits along with crisp tofu.","Toss warm pork and tofu with diced red onions, green chilies, calamansi juice, light mayonnaise, salt, and pepper.","Spoon onto mini warm cast-iron plates or crisp lettuce cups for appetizer serving."],"note":"50:50 plant-to-animal protein ratio using tofu cuts total saturated fat and cholesterol by half compared to classic organ-meat sisig.","id":"r335"},{"title":"Crispy Tilapia Strips with Calamansi Tartar","category":"appetizer","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["400g tilapia fillets (cut into 1-inch strips)","1/2 cup panko breadcrumbs","1 egg (beaten)","1/2 tsp garlic salt","## Sauce","3 tbsp light mayo","1 tbsp calamansi juice","1 tsp pickle relish"],"steps":["Season tilapia strips with garlic salt. Dip in beaten egg, then roll in panko breadcrumbs.","Air-fry at 190°C (375°F) for 8–10 minutes until golden.","Whisk light mayo, fresh calamansi juice, and pickle relish to make tartar sauce."],"note":"Easily digestible lean white fish high in phosphorus; air-frying avoids excessive oil absorption.","id":"r336"},{"title":"Inihaw na Tengga ng Baboy Bites","category":"appetizer","prep":"30 mins","cook":"15 mins","servings":"4","ingredients":["300g pork ears (cleaned, pressure-cooked until tender, sliced)","2 tbsp cane vinegar","2 tbsp soy sauce","1 tbsp brown sugar","3 cloves garlic (minced)","skewers"],"steps":["Marinate cooked ear slices in vinegar, soy sauce, sugar, and garlic for 30 minutes.","Thread onto bamboo skewers.","Grill over medium-high heat for 10–12 minutes, turning continuously until the edges are gelatinous and crispy."],"note":"High natural collagen protein structure; boiling prior to grilling renders off excess structural fats.","id":"r337"},{"title":"Spiced Corn Chips with Tomato Salsa","category":"appetizer","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["4 corn tortillas (cut into triangles)","1 tsp olive oil","1/2 tsp chili powder","## Salsa","2 ripe tomatoes (diced)","1/2 red onion (diced)","2 tbsp coriander (chopped)","1 tbsp calamansi juice","salt"],"steps":["Toss tortilla triangles with olive oil and chili powder.","Bake at 180°C (350°F) for 8–10 minutes until crisp.","Mix diced tomatoes, red onion, chopped coriander, calamansi juice, and salt in a bowl. Serve with warm baked chips."],"note":"Baked whole-corn tortilla chips deliver dietary fiber without the trans-fat risk of commercial deep-fried corn chips.","id":"r338"},{"title":"Kilawin na Pusit","category":"appetizer","prep":"20 mins","cook":"2 mins","servings":"4","ingredients":["300g fresh small squid (cleaned, flash-blanched for 1 minute, cut into rings)","1/2 cup cane vinegar","1 thumb ginger (julienned)","1 red onion (diced)","1 siling haba (sliced)","salt"],"steps":["Flash-blanch squid in boiling water for 60 seconds; drain immediately and submerge in ice bath.","Toss blanched squid with vinegar, julienned ginger, red onion, sliced green chili, and salt.","Chill in the refrigerator for 30 minutes before serving cold."],"note":"Brief blanching improves digestibility while maintaining high trace mineral content (copper, zinc, iodine).","id":"r339"},{"title":"Mini Beef Tapa Skewers","category":"appetizer","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["300g beef sirloin (thinly sliced)","2 tbsp soy sauce","2 tbsp calamansi juice","4 cloves garlic (minced)","1/2 tsp black pepper","mini skewers"],"steps":["Marinate sliced beef in soy sauce, calamansi juice, minced garlic, and pepper for 2 hours.","Thread marinated beef tightly onto mini wooden skewers.","Pan-sear on a hot non-stick skillet for 3–4 minutes per side until browned and tender."],"note":"High-iron, protein-dense appetizer using lean sirloin; citrus marinade acts as a natural tenderizer.","id":"r340"},{"title":"Pritong Smoked Fish Cakes (Tinapa Cakes)","category":"appetizer","prep":"20 mins","cook":"10 mins","servings":"4","ingredients":["1.5 cups flaked tinapa (smoked fish, bones removed)","1 cup mashed potatoes","1/4 cup scallions (chopped)","1 egg","1/2 cup breadcrumbs","1 tbsp oil"],"steps":["Mix flaked tinapa, mashed potatoes, scallions, and egg together in a bowl.","Form into small 1.5-inch patties and dredge lightly in breadcrumbs.","Shallow fry in 1 tbsp oil over medium heat for 3–4 minutes per side until golden brown."],"note":"Smoked fish delivers high omega-3 fatty acids and vitamin D; potato binder provides easy-to-digest carbohydrates.","id":"r341"},{"title":"Adobong Chicken Liver Skewers","category":"appetizer","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["300g fresh chicken liver (cleaned, cut into bite pieces)","2 tbsp cane vinegar","2 tbsp soy sauce","3 cloves garlic (minced)","1/2 tsp black pepper","skewers"],"steps":["Marinate chicken liver in vinegar, soy sauce, garlic, and pepper for 15 minutes.","Thread liver pieces onto wooden skewers.","Pan-sear in a hot non-stick skillet for 4–5 minutes per side until fully cooked through."],"note":"Unusually high in bioavailable heme iron, vitamin A, and folate; recommended for nutritional anemia management in controlled portions.","id":"r342"},{"title":"Cheesy Garlic Dumpling Bites","category":"appetizer","prep":"20 mins","cook":"12 mins","servings":"4","ingredients":["200g lean ground pork","1/4 cup low-fat cheddar cheese (diced small)","1 tbsp roasted garlic (minced)","dumpling wrappers","water for sealing"],"steps":["Mix ground pork and roasted garlic.","Place 1 teaspoon pork mixture on a wrapper, add a small cheese cube, fold, and crimp edges tightly.","Steam for 10 minutes, then briefly pan-sear bottom in a non-stick pan for 2 minutes for crispness."],"note":"Steaming maintains low fat content while roasted garlic provides organosulfur compounds helpful for vascular health.","id":"r343"},{"title":"Steamed Shrimp Dumplings (Hagao Tagalog)","category":"appetizer","prep":"25 mins","cook":"8 mins","servings":"4","ingredients":["250g whole shrimp (peeled, deveined, chopped)","2 tbsp bamboo shoots (minced)","1 tsp sesame oil","1/2 tsp salt","1/2 cup wheat starch + 2 tbsp tapioca starch (for wrapper dough)"],"steps":["Mix chopped shrimp, bamboo shoots, sesame oil, and salt to form filling.","Prepare dough using boiling water, wheat starch, and tapioca starch; roll into thin translucent discs.","Wrap filling, pleat edges, and steam over high heat for 6–8 minutes until translucent."],"note":"Low-calorie translucent dumplings packed with lean seafood protein and devoid of heavy fats.","id":"r344"},{"title":"Crispy Baby Squid","category":"appetizer","prep":"15 mins","cook":"6 mins","servings":"4","ingredients":["300g fresh baby squid (cleaned, whole)","3 tbsp cornstarch","1/2 tsp salt","1/2 tsp garlic powder","oil spray"],"steps":["Dry baby squids thoroughly with paper towels.","Toss with cornstarch, salt, and garlic powder until lightly coated.","Arrange a single layer in the air fryer, spray lightly with oil, and air-fry at 200°C (400°F) for 6 minutes until crispy."],"note":"Air-frying small cephalopods avoids deep-frying oils while retaining mineral micronutrients like zinc and copper.","id":"r345"},{"title":"Inihaw na Hotdog & Marshmallow Skewers","category":"appetizer","prep":"5 mins","cook":"5 mins","servings":"4","ingredients":["4 lean red tender juicy hotdogs (cut into 1-inch rounds)","8 mini white marshmallows","wooden skewers"],"steps":["Thread alternating rounds of hotdog pieces and marshmallows onto wooden skewers.","Grill lightly over medium coals or pan-grill for 4–5 minutes until hotdog edges char slightly and marshmallows soften."],"note":"Traditional festive appetizer portioned into mini skewers to manage dietary sodium and simple sugar intake.","id":"r346"},{"title":"Sautéed Mushroom Tapas","category":"appetizer","prep":"10 mins","cook":"8 mins","servings":"4","ingredients":["300g local oyster mushrooms (cleaned, torn)","4 cloves garlic (sliced)","1 tbsp olive oil","1 tbsp soy sauce","1 tbsp calamansi juice","chopped parsley"],"steps":["Heat olive oil in a skillet over medium-high heat.","Add sliced garlic and cook until light golden.","Toss in oyster mushrooms and sauté for 4–5 minutes until browned.","Deglaze pan with soy sauce and calamansi juice; garnish with parsley."],"note":"Exceptionally low in calories; rich in beta-glucans and prebiotic fibers supporting immune and gut health.","id":"r347"},{"title":"Salt & Pepper Calamari Bites","category":"appetizer","prep":"15 mins","cook":"6 mins","servings":"4","ingredients":["350g squid tubes (cut into bite-size squares, scored)","2 tbsp cornstarch","1/2 tsp sea salt","1/2 tsp crushed black peppercorns","1 red chili (sliced)","oil spray"],"steps":["Score squid squares in a diamond pattern and pat dry.","Toss squid with cornstarch, sea salt, and black pepper.","Air-fry at 200°C for 5–6 minutes until the edges curl up crisp. Toss with fresh red chilies before serving."],"note":"High-protein, low-fat alternative to heavily battered fried calamari rings.","id":"r348"},{"title":"Crispy Lumpiang Hubad Cups","category":"appetizer","prep":"20 mins","cook":"10 mins","servings":"6","ingredients":["1 cup sweet potato (diced)","1 cup green beans (diced)","1 cup jicama (diced)","1/2 cup tofu (diced)","6 small baked wonton wrapper cups","2 tbsp crushed peanuts"],"steps":["Press wonton wrappers into mini muffin tins and bake at 180°C for 6 minutes to form crispy cups.","Sauté sweet potato, green beans, jicama, and tofu until tender.","Spoon cooked vegetables into baked wonton cups and garnish with crushed peanuts."],"note":"Portioned vegetable presentation offering diverse textures, complex carbohydrates, and plant-based dietary fiber.","id":"r349"},{"title":"Spiced Garlic Chicharon Tofu","category":"appetizer","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["400g extra-firm tofu (cut into small 1/2-inch cubes)","1 tbsp garlic powder","1/2 tsp salt","1/2 tsp chili flakes","1 tbsp cornstarch","1 tbsp oil"],"steps":["Press tofu thoroughly to remove moisture, then cut into small cubes.","Toss cubes with cornstarch, garlic powder, salt, and chili flakes.","Pan-fry in oil over medium-high heat or air-fry at 200°C for 15 minutes, shaking frequently until crunchy like chicharon.","Serve with spicy garlic vinegar dip."],"note":"High-protein, zero-cholesterol plant alternative mimicking traditional pork cracklings, suitable for cardiovascular health plans. SOUPS & BROTHS","id":"r350"},{"title":"Sinigang na Bangus sa Sampalok (Milkfish Tamarind Soup)","category":"soup","prep":"15 mins","cook":"25 mins","servings":"6","ingredients":["1 large Bangus (milkfish, cleaned and sliced)","1 cup fresh tamarind pods (or tamarind base)","1 radish (sliced)","1 bunch sitaw","1 bunch kangkong","2 tomatoes (quartered)","1 onion (quartered)","2 green long peppers","6 cups water","salt or fish sauce"],"steps":["Boil tamarind pods in 1 cup water, mash, and strain juice.","In a large pot, bring 6 cups of water with onions and tomatoes to a boil.","Add radish and sitaw; simmer for 5 minutes.","Add bangus slices, green peppers, and tamarind juice. Simmer for 7 minutes until fish is cooked.","Season with salt/patis, fold in kangkong, turn off heat, and cover for 2 minutes."],"note":"Naturally low-fat, highly hydrating broth rich in vitamin C and mineral electrolytes.","id":"r351"},{"title":"Tinolang Manok (Chicken Ginger Soup)","category":"soup","prep":"15 mins","cook":"30 mins","servings":"6","ingredients":["500g chicken (cut into pieces)","2 thumbs ginger (julienned)","4 cloves garlic","1 onion","1 small green papaya or chayote (wedged)","2 cups dahon ng sili (chili leaves) or malunggay","1 tbsp oil","6 cups rice washing or water","1 tbsp patis"],"steps":["Sauté ginger, garlic, and onion in oil until aromatic.","Add chicken and sear until light golden brown; season with patis.","Pour in rice washing or water; bring to a boil, then lower heat and simmer for 20 minutes.","Add green papaya/chayote and cook until tender (approx. 7 mins).","Turn off heat, stir in chili leaves/malunggay, cover, and serve hot."],"note":"Gingerol provides anti-inflammatory benefit while chili leaves deliver high calcium and iron.","id":"r352"},{"title":"Bulalo (Beef Shank & Marrow Soup)","category":"soup","prep":"15 mins","cook":"2 hours","servings":"6","ingredients":["1 kg beef shank with marrow bone","1 head cabbage (quartered)","2 corn on the cob (cut into thirds)","1/2 lb Baguio beans","1 onion","1 tsp whole peppercorns","water","salt"],"steps":["Blanch beef shank in boiling water for 5 minutes, drain, and rinse to remove impurities.","In a deep stockpot, boil beef shank with onion and peppercorns in 8–10 cups of water. Simmer on low heat for 1.5–2 hours until meat is tender.","Add sweet corn pieces and cook for 15 minutes.","Add Baguio beans and cabbage; simmer for 3 minutes. Season with salt."],"note":"Rich collagen and amino acid broth base; portioning marrow controls saturated fat intake.","id":"r353"},{"title":"Batchoy (Iloilo Style Noodle Soup)","category":"soup","prep":"20 mins","cook":"45 mins","servings":"4","ingredients":["200g miki noodles","200g lean pork strips","100g pork liver (sliced)","4 cups pork/beef bone broth","3 cloves garlic (fried)","2 tbsp chicharon (crushed)","scallions","1 tbsp shrimp paste (bagoong)","soy sauce","pepper"],"steps":["Simmer bone broth with bagoong, soy sauce, and black pepper for 30 minutes to build flavor.","Boil pork strips and liver in broth until tender.","Place cooked miki noodles in bowls. Ladle hot broth, pork, and liver over noodles.","Top with fried garlic, crushed chicharon, and chopped scallions."],"note":"High-protein noodle dish; using lean pork cuts balances fat content.","id":"r354"},{"title":"Sopas (Filipino Chicken Macaroni Soup)","category":"soup","prep":"15 mins","cook":"25 mins","servings":"6","ingredients":["1 cup elbow macaroni","200g chicken breast (shredded)","1 carrot (diced)","1 cup cabbage (chopped)","1/2 cup evaporated milk (low-fat)","1 onion","2 cloves garlic","5 cups chicken stock","1 tbsp butter/oil"],"steps":["Sauté garlic and onion in butter/oil. Add shredded chicken and carrots.","Pour chicken stock and bring to a boil.","Add elbow macaroni and cook for 8–10 minutes until al dente.","Add cabbage and pour low-fat evaporated milk. Stir constantly on low heat for 2 minutes. Season to taste."],"note":"Comforting recovery soup offering digestible carbohydrates and lean protein.","id":"r355"},{"title":"Sinigang na Baboy sa Kamias (Pork Tamarind/Kamias Soup)","category":"soup","prep":"15 mins","cook":"45 mins","servings":"6","ingredients":["500g lean pork rib/shoulder","1 cup fresh kamias (bilimbi, sliced)","1 gabi (taro, quartered)","1 bunch kangkong","1 radish","2 tomatoes","water","salt"],"steps":["Boil pork and gabi in 6 cups of water for 30 minutes until soft and gabi breaks down to thicken broth.","Add sliced kamias and tomatoes; press kamias against the side of the pot to release natural sour juice.","Add sliced radish and cook for 5 minutes.","Season with salt, add kangkong, and remove from heat."],"note":"Natural fruit acid souring agent (kamias) eliminates the need for artificial sodium-heavy flavor enhancers.","id":"r356"},{"title":"Suam na Mais (Corn and Spinachy/Malunggay Soup)","category":"soup","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["2 cups fresh white corn (scraped from cob)","150g shrimp (peeled)","2 cups chili leaves or spinach","1 thumb ginger (julienned)","1 onion","4 cups water","1 tbsp oil","salt"],"steps":["Sauté ginger and onion in oil until translucent.","Add scraped sweet corn and stir-fry for 2 minutes.","Pour water and simmer for 12 minutes until the corn is tender.","Add shrimp and cook for 2 minutes. Stir in greens, season with salt, and turn off heat."],"note":"High insoluble fiber content from whole sweet corn supports digestive wellness.","id":"r357"},{"title":"Linagpang na Manok (Grilled Chicken Soup)","category":"soup","prep":"20 mins","cook":"25 mins","servings":"5","ingredients":["500g grilled chicken pieces","3 tomatoes (charred)","2 onions (charred)","1 thumb ginger","5 cups water","green chilies","lemongrass","salt"],"steps":["Chop grilled chicken, charred tomatoes, and charred onions.","In a pot, combine water, lemongrass, ginger, chicken, and charred vegetables.","Simmer for 20 minutes to infuse smoky charcoal flavor into broth.","Season with salt and add green chilies before serving."],"note":"Charring vegetables prior to simmering creates deep umami without added fat.","id":"r358"},{"title":"Sinanglay na Tilapia Soup Portion","category":"soup","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["2 whole Tilapia (wrapped in mustard leaves)","1.5 cups light coconut milk","1 thumb ginger","1 onion","2 tomatoes","green chilies","salt"],"steps":["Stuff tilapia with tomatoes, onions, and ginger; wrap in leaf greens.","Lay stuffed fish in a pan, pour light coconut milk, add chilies.","Simmer covered over low heat for 18–20 minutes until fish is cooked."],"note":"Medium-chain triglycerides (MCTs) from light coconut milk paired with high-quality lean fish protein.","id":"r359"},{"title":"Pesang Isda (Fish in Ginger Broth)","category":"soup","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["400g Lapu-Lapu or Dalag (sliced)","2 thumbs ginger (sliced)","1 cup cabbage (quartered)","1 bunch pechay","1 leek (sliced)","1 tsp whole peppercorns","5 cups rice washing","patis"],"steps":["Bring rice washing, ginger, and peppercorns to a boil in a pot.","Add fish slices and leeks; simmer gently for 8 minutes.","Add cabbage and pechay; simmer for 3 minutes until vegetables are tender-crisp. Season with patis."],"note":"Extremely light, low-sodium broth base recommended for mild digestive rest.","id":"r360"},{"title":"Sinigang na Hipon sa Sampalok (Shrimp in Tamarind Broth)","category":"soup","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["500g medium black tiger shrimp (whiskers trimmed)","1 cup fresh tamarind pods (or tamarind base)","1 medium daikon radish (sliced)","1 bunch sitaw (long beans, cut into 2-inch segments)","1 bunch kangkong (water spinach fronds)","2 tomatoes (quartered)","1 onion (quartered)","2 green long peppers (siling haba)","5 cups water","sea salt or patis"],"steps":["Boil fresh tamarind pods in 1 cup of water until soft, mash through a sieve, and extract the concentrated sour juice.","Bring 5 cups of water to a boil in a medium stockpot along with onions and tomatoes.","Add sliced daikon radish and sitaw; simmer for 4 minutes until tender-crisp.","Stir in the prepared tamarind juice and green long peppers.","Lower trimmed shrimp into the simmering broth and cook for 3 to 4 minutes just until pink and opaque.","Season with sea salt, turn off heat, fold in kangkong leaves, and cover for 2 minutes before serving."],"note":"Shrimp provides high-quality protein and astaxanthin antioxidants with minimal fat. Keeping cooking time brief prevents tough protein textures and preserves heat-sensitive Vitamin C from greens.","id":"r361"},{"title":"Kansi (Negrense Sour Beef Soup)","category":"soup","prep":"20 mins","cook":"1 hr 45 mins","servings":"6","ingredients":["1 kg beef shank with marrow bone","4 pieces batuan fruit (or green mango/tamarind as alternative souring agent)","2 stalks lemongrass (bruised)","1 thumb turmeric (peeled and sliced)","1 small unripe green papaya (wedged)","1 onion (sliced)","3 cloves garlic (crushed)","2 green chilies","8 cups water","salt"],"steps":["Blanch beef shanks in boiling water for 5 minutes; discard cloudy water and rinse shanks.","In a deep pot, combine cleaned beef shanks, bruised lemongrass, garlic, onion, turmeric, and 8 cups of water.","Simmer on medium-low heat for 1.5 hours until beef tendons and meat become tender.","Add batuan fruit (slotted with a knife) and green papaya wedges; cook for 15 minutes until sourness infuses the broth and papaya softens.","Add green chilies and adjust seasoning with salt. Serve hot."],"note":"Natural curcumin from turmeric offers anti-inflammatory benefits, while batuan fruit delivers organic acids without requiring high sodium addition.","id":"r362"},{"title":"Pochero Beef Soup","category":"soup","prep":"20 mins","cook":"1 hr 30 mins","servings":"6","ingredients":["600g beef brisket (cubed)","2 saba bananas (halved)","1 sweet potato (cubed)","1 cup garbanzo beans (chickpeas, cooked)","1 small cabbage (quartered)","1 bunch bok choy (pechay)","1 cup tomato sauce","1 onion","1 tsp peppercorns","7 cups water","salt"],"steps":["Simmer beef brisket, onion, and peppercorns in 7 cups of water for 1 hour until tender.","Stir in tomato sauce, chickpeas, and sweet potato cubes; simmer for 10 minutes.","Add saba banana halves and cook for another 5 minutes until soft.","Fold in quartered cabbage and fresh pechay.","Simmer for 3 minutes until leafy greens are tender-crisp, season with salt, and serve."],"note":"Combines high-fiber complex carbohydrates from chickpeas and sweet potatoes with lean beef, yielding a balanced glycemic profile.","id":"r363"},{"title":"Balbacua (Davao Style Braised Beef Soup)","category":"soup","prep":"25 mins","cook":"2 hrs 30 mins","servings":"6","ingredients":["500g beef oxtail","300g beef skin/tendon","2 stalks lemongrass","1 thumb ginger (sliced)","2 tbsp annatto oil (atsuete)","3 cloves garlic (minced)","1 onion","2 star anise","1 tbsp black bean paste (tausi)","8 cups water","salt"],"steps":["Boil oxtail and beef skin in water for 10 minutes; drain and discard liquid.","Heat annatto oil in a heavy pot; sauté garlic, onion, ginger, and black bean paste.","Add blanched meats, lemongrass, star anise, and 8 cups of water.","Cover and simmer over low heat for 2 to 2.5 hours until collagen is fully gelatinized and broth turns rich.","Season lightly with salt and serve hot with chopped scallions."],"note":"Collagen-rich broth supporting joint matrix synthesis; skimming excess surface fat after simmering controls overall calorie density.","id":"r364"},{"title":"Lomi (Batangas Thick Noodle Soup)","category":"soup","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["300g fresh thick egg noodles (Lomi noodles)","150g lean pork strips","100g chicken liver (sliced)","1 egg (whisked)","2 tbsp cassava starch or cornstarch (slurry)","1 onion (minced)","4 cloves garlic (minced)","5 cups pork stock","1 tbsp soy sauce","scallions"],"steps":["Sauté garlic and onion in a pot until fragrant. Add pork strips and chicken liver; sear for 4 minutes.","Pour in soy sauce and pork stock; bring to a rolling boil.","Add fresh lomi noodles and simmer for 5 to 7 minutes until noodles soften.","Pour in cassava starch slurry while stirring continuously to thicken broth.","Turn off heat, slowly drizzle whisked egg into hot soup to create silky egg ribbons, and garnish with scallions."],"note":"Rich in heme iron from chicken liver. Pairing with a side citrus slice (calamansi) enhances non-heme mineral bio-availability.","id":"r365"},{"title":"Sinigang na Salmon Belly sa Miso","category":"soup","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g salmon belly strips","3 tbsp yellow soybean paste (miso)","1 cup tamarind juice extract","1 mustard green bunch (mustasa)","1 radish (sliced)","2 tomatoes (diced)","1 onion (diced)","2 green long peppers","5 cups rice washing","salt"],"steps":["Sauté onion, tomatoes, and yellow miso in a dry pot for 2 minutes until aromatic.","Pour in rice washing and bring to a simmer.","Stir in tamarind extract and sliced radish; cook for 5 minutes.","Add salmon belly strips and green long peppers; simmer gently for 5 to 6 minutes.","Turn off heat, press mustasa leaves into hot broth, cover for 2 minutes, and season with salt."],"note":"High density of essential Omega-3 long-chain fatty acids (EPA/DHA) paired with fermentative probiotic benefits from soybean miso.","id":"r366"},{"title":"Mami Chicken Soup","category":"soup","prep":"15 mins","cook":"35 mins","servings":"4","ingredients":["300g chicken breast","200g egg noodles (cooked)","1 napa cabbage (wong bok, sliced)","2 hard-boiled eggs (halved)","1 head garlic (minced and toasted)","6 cups chicken bone broth","1 tbsp light soy sauce","scallions"],"steps":["Simmer chicken breast in bone broth with light soy sauce for 20 minutes until fully cooked.","Remove chicken, shred flesh into strips, and return bones to broth to simmer 10 additional minutes. Strain broth.","Divide cooked egg noodles into bowls and top with shredded chicken, halved hard-boiled eggs, and sliced napa cabbage.","Ladle hot strained broth over contents to wilt cabbage. Top with golden toasted garlic and scallions."],"note":"Low-fat, high-protein restorative soup containing accessible electrolytes suitable for athletic rehydration.","id":"r367"},{"title":"Mami Beef Soup","category":"soup","prep":"20 mins","cook":"1 hr 45 mins","servings":"4","ingredients":["400g beef shank or flank","200g flat wheat noodles","1 star anise","1 thumb ginger","1 cup napa cabbage","6 cups water","1 tbsp dark soy sauce","fried garlic","chopped chives"],"steps":["Simmer beef shank with star anise, ginger, and dark soy sauce in 6 cups of water for 1.5 hours until fork-tender.","Slice beef into thin cross-sections.","Place cooked wheat noodles and raw napa cabbage into serving bowls.","Lay sliced beef over noodles and pour boiling beef broth directly over the bowl.","Garnish with crisp fried garlic and chives."],"note":"Warm spice compounds (anethole from star anise) promote gastric enzyme secretion and digestion.","id":"r368"},{"title":"Almondigas (Meatball & Patola Soup)","category":"soup","prep":"20 mins","cook":"15 mins","servings":"4","ingredients":["300g lean ground pork","1 egg","2 tbsp flour","1 medium patola (sponge gourd, peeled and sliced into rounds)","50g misua noodles","4 cloves garlic (minced)","1 onion (diced)","5 cups water or vegetable stock","salt and pepper"],"steps":["Mix ground pork, egg, flour, salt, and pepper in a bowl; form into 1-inch meatballs.","Sauté garlic and onion in a pot until softened; pour in water/stock and bring to a boil.","Drop meatballs into boiling broth one by one; simmer for 8 minutes until meatballs float.","Add patola slices and cook for 3 minutes.","Stir in misua noodles, cook for 1 minute, turn off heat, and serve immediately."],"note":"Patola provides high water content and soluble mucilage fiber while keeping overall caloric density low.","id":"r369"},{"title":"Lauya (Ilocano Pork/Beef Soup)","category":"soup","prep":"15 mins","cook":"1 hr 15 mins","servings":"5","ingredients":["500g pork bone-in ribs or beef brisket","1 green papaya (wedged)","2 thumbs ginger (crushed)","1 tsp whole peppercorns","2 tbsp fish sauce (patis)","6 cups water","pechay leaves"],"steps":["Combine meat, crushed ginger, and peppercorns in 6 cups of water; bring to a boil.","Lower heat and simmer for 1 hour until meat is tender.","Add patis and green papaya wedges; cook for 10 minutes until papaya is pierced easily with a fork.","Stir in pechay leaves, turn off heat, cover for 2 minutes, and serve."],"note":"Traditional ginger-heavy broth base aids peripheral circulation and relieves nausea.","id":"r370"},{"title":"Sinampalukang Manok (Chicken in Tamarind Leaves)","category":"soup","prep":"20 mins","cook":"35 mins","servings":"5","ingredients":["500g chicken pieces","1 cup fresh young tamarind leaves (young shoots)","1 thumb ginger (julienned)","1 onion","2 tomatoes","2 green long peppers","1 tbsp oil","6 cups water","salt"],"steps":["Heat oil in a pot; sauté ginger, onion, tomatoes, and chicken pieces until light golden.","Pour in water and bring to a simmer for 20 minutes until chicken is tender.","Add fresh young tamarind leaves and green long peppers; simmer for 8 minutes to release natural sour notes.","Season with salt and serve hot."],"note":"Young tamarind shoots supply plant oxalic and tartaric acids alongside polyphenol antioxidants.","id":"r371"},{"title":"Papaitan Baka (Bitter Beef Broth)","category":"soup","prep":"30 mins","cook":"1 hr 30 mins","servings":"6","ingredients":["400g beef tripe and heart (cleaned thoroughly)","3 tbsp bile extract (kiti/papait)","2 thumbs ginger (minced)","1 head garlic","2 onions","3 green chilies","7 cups water","salt"],"steps":["Boil tripe and heart in water with ginger for 45 minutes; drain, rinse, and finely dice.","Sauté garlic, onions, and remaining ginger in a pot; add diced organ meats and sear for 5 minutes.","Pour in 7 cups of water; simmer for 30 minutes until meat is tender.","Stir in bile extract gradually to achieve desired bitterness; add green chilies and simmer for 5 minutes. Season with salt."],"note":"Bitter flavor compounds help stimulate bile flow and pancreatic enzyme production to assist macronutrient metabolism.","id":"r372"},{"title":"Ginisang Monggo Soup with Chicharon topping","category":"soup","prep":"15 mins","cook":"40 mins","servings":"6","ingredients":["1 cup dried green mung beans","50g tinapa flakes (smoked fish)","2 cups tinapay/kangkong/malunggay leaves","4 cloves garlic","1 onion","2 tomatoes","2 tbsp crushed chicharon (for garnish)","6 cups water","1 tbsp oil","salt"],"steps":["Boil mung beans in 5 cups of water for 30 minutes until soft and burst.","In a pan, sauté garlic, onion, tomatoes, and tinapa flakes in oil.","Pour boiled mung beans and cooking broth into sautéed mixture; simmer 5 minutes.","Fold in malunggay leaves and turn off heat. Serve topped with crushed chicharon."],"note":"Plant-based protein base supplemented with dietary folate and potassium; small chicharon garnish delivers flavor without excessive lipid loading.","id":"r373"},{"title":"Halaan Soup (Clam Ginger Soup)","category":"soup","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["1 kg fresh Manila clams (soaked in salted water to purge sand)","2 thumbs ginger (julienned)","1 bunch spinach or pepper leaves (dahon ng sili)","1 onion (sliced)","4 cups water","1 tbsp oil"],"steps":["Heat oil in a pot; sauté julienned ginger and onion until soft.","Add purged clams and stir-fry for 1 minute.","Pour in water, cover the pot, and bring to a rapid boil.","Cook for 5 minutes until all clam shells pop open (discard unopened shells).","Stir in spinach or chili leaves, turn off heat, and serve immediately."],"note":"Excellent marine source of highly bioavailable iron, zinc, and Vitamin B12.","id":"r374"},{"title":"Tulya Soup (Small Clam Soup)","category":"soup","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["1 kg small freshwater clams (tulya)","2 thumbs ginger (sliced)","1 stalk lemongrass","1 bunch of malunggay leaves","4 cups water","and salt"],"steps":["Boil water with sliced ginger and bruised lemongrass.","Add cleaned tulya clams; boil covered for 4 to 5 minutes until shells open.","Season lightly with salt.","Stir in fresh malunggay leaves, remove from heat, and keep covered for 2 minutes before serving."],"note":"Light clear broth high in calcium and essential trace minerals with low total calorie density.","id":"r375"},{"title":"Sinigang na Baka sa Bayabas (Beef Guava Soup)","category":"soup","prep":"20 mins","cook":"1 hr 30 mins","servings":"6","ingredients":["500g beef ribs","6 ripe guavas (peeled, quartered, and deseeded)","1 bunch kangkong","1 small taro root (gabi, cubed)","1 onion","6 cups water","salt"],"steps":["Boil guavas in 2 cups of water until soft; mash and press through a sieve to extract thick guava pulp.","In a pot, boil beef ribs, onion, and gabi in 6 cups water for 1 hour until beef is tender and gabi thickens broth.","Add extracted guava pulp; simmer for 15 minutes to infuse sweet-sour flavor.","Season with salt, add kangkong fronds, turn off heat, and serve."],"note":"Ripe guavas supply high amounts of natural dietary Vitamin C and dietary pectin fiber.","id":"r376"},{"title":"Sinigang na Baka sa Mangga","category":"soup","prep":"20 mins","cook":"1 hr 20 mins","servings":"5","ingredients":["500g beef brisket","2 green unripe mangoes (peeled and grated/sliced)","1 radish","1 bunch sitaw","1 onion","2 tomatoes","6 cups water","salt"],"steps":["Simmer beef brisket with onion and tomatoes in 6 cups of water for 1 hour until tender.","Add green mango slices; cook for 10 minutes until mangoes soften and sour the broth.","Add radish and sitaw; simmer for 5 minutes.","Adjust taste with salt and serve hot."],"note":"Tartaric and malic acids from green mango provide tartness while avoiding processed souring powders.","id":"r377"},{"title":"Linat-an (Visayan Pork Soup)","category":"soup","prep":"15 mins","cook":"50 mins","servings":"5","ingredients":["500g pork chops or ribs","1 cup lemongrass (tied in a knot)","1 sweet potato (cubed)","1 gabi root","1 cup long beans","1 thumb ginger","6 cups water","salt"],"steps":["Boil pork ribs with ginger and lemongrass in 6 cups of water for 35 minutes until tender.","Add gabi and sweet potato cubes; simmer for 10 minutes until the roots are cooked.","Stir in long beans and cook for 3 minutes.","Season with salt and serve piping hot."],"note":"Lemongrass essential oils (citral) offer aromatic carminative benefits for comfortable digestion.","id":"r378"},{"title":"Imbaliktad (Ilocano Seared Beef Broth)","category":"soup","prep":"15 mins","cook":"8 mins","servings":"4","ingredients":["300g sirloin steak (sliced paper-thin)","2 thumbs ginger (julienned)","4 cloves garlic","1 red onion","2 tbsp cane vinegar","3 cups beef stock","1 tbsp oil","salt and pepper"],"steps":["Heat oil in a wok; flash-sauté garlic, onion, and ginger over high heat.","Add paper-thin beef strips; sear quickly for 1 minute (rare/medium-rare stage).","Pour in cane vinegar and hot beef stock.","Bring to a rapid boil for 1 minute, season with salt and pepper, and remove from heat immediately."],"note":"Flash-cooking preserves tender muscle fibers and minimizes nutrient oxidation loss in beef cuts.","id":"r379"},{"title":"Soto Ayam Tagalog Style","category":"soup","prep":"20 mins","cook":"30 mins","servings":"4","ingredients":["300g shredded cooked chicken","50g glass noodles (sotanghon)","1 thumb turmeric","1 stalk lemongrass","2 boiled eggs","5 cups chicken broth","fried garlic","scallions"],"steps":["Simmer chicken broth with bruised lemongrass and fresh turmeric for 15 minutes.","Soak sotanghon noodles in warm water for 5 minutes; drain.","Place sotanghon noodles and shredded chicken into bowls.","Strain hot golden turmeric broth directly over noodles.","Top with sliced boiled eggs, toasted garlic, and scallions."],"note":"Turmeric-infused broth delivers bio-active polyphenols and curcumin compounds for metabolic support.","id":"r380"},{"title":"Kimchi Sinigang Fusion Soup","category":"soup","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["300g pork belly or tofu cubes","1 cup Baechu Kimchi (chopped)","2 tbsp tamarind juice concentrate","1 radish (sliced)","1 green pepper","1 bunch kangkong","5 cups water","1 tbsp soy sauce"],"steps":["Sauté chopped kimchi and pork/tofu in a pot for 3 minutes.","Pour water and bring to a simmer for 15 minutes.","Stir in tamarind concentrate, sliced radish, and green pepper; cook for 5 minutes.","Season with light soy sauce, stir in kangkong leaves, and remove from heat."],"note":"Fusion of lactic acid probiotics from fermented kimchi with traditional tamarind souring components.","id":"r381"},{"title":"Sinangag at Tapa Soup Combination","category":"soup","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["200g cured beef tapa strips","4 cups beef broth","4 cloves fried garlic","1 cup bok choy","1 tsp toasted rice powder (thickener)","black pepper"],"steps":["Pan-sear beef tapa strips until browned; slice into bite-sized pieces.","Bring beef broth to a boil with fried garlic and toasted rice powder.","Add seared tapa pieces and simmer for 8 minutes to infuse flavor into broth.","Add bok choy leaves, simmer for 2 minutes, season with pepper, and serve."],"note":"Reinterprets traditional dry breakfast proteins into a warm, hydrating broth layout.","id":"r382"},{"title":"Crab Soup with Corn & Egg","category":"soup","prep":"15 mins","cook":"15 mins","servings":"4","ingredients":["1 cup fresh lump crabmeat","1 cup sweet corn kernels (scraped from cob)","1 egg (beaten)","1 tbsp cornstarch (slurry)","1 onion","4 cups chicken/seafood broth","scallions","salt"],"steps":["Bring seafood broth, onion, and sweet corn to a boil; simmer for 8 minutes.","Add fresh lump crabmeat and cook for 3 minutes.","Stir in cornstarch slurry to create a smooth, velvety broth consistency.","Turn off heat, slowly stream in beaten egg while stirring gently to form egg drop ribbons. Season with salt and top with scallions."],"note":"Lean seafood protein paired with dietary zinc, selenium, and dietary carbohydrates.","id":"r383"},{"title":"Fish Head Soup sa Miso","category":"soup","prep":"15 mins","cook":"25 mins","servings":"4","ingredients":["1 large Lapu-Lapu or Red Snapper fish head (halved and cleaned)","3 tbsp white miso paste","1 thumb ginger","1 mustard green bunch","2 tomatoes","5 cups rice washing","salt"],"steps":["Sear fish head halves in a dry pan for 2 minutes per side to eliminate fishy notes.","In a stockpot, sauté ginger, tomatoes, and white miso paste.","Pour in rice washing and bring to a simmer.","Add seared fish head; cover and simmer gently for 12 minutes.","Add mustard green leaves, season with salt, turn off heat, and cover for 2 minutes."],"note":"Fish head cartilage supplies naturally occurring glucosamine, chondroitin, and marine collagen.","id":"r384"},{"title":"Sinigang na Pusit Soup","category":"soup","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["400g medium fresh squid (cleaned, ink kept intact or removed)","1 cup tamarind juice extract","2 tomatoes","1 onion","1 bunch kangkong","2 green long peppers","4 cups water","salt"],"steps":["Boil water with onions and tomatoes for 5 minutes.","Pour in tamarind extract and green long peppers.","Add cleaned squid; cook over medium heat for 3 to 4 minutes maximum (overcooking toughens squid).","Season with salt, add kangkong fronds, turn off heat, and serve immediately."],"note":"Low-calorie marine protein offering high selenium content; rapid cooking ensures tenderness.","id":"r385"},{"title":"Pochero Fish Soup","category":"soup","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["400g firm fish steaks (Maya-Maya or Tanigue)","1 saba banana (sliced)","1/2 cup cooked chickpeas","1 cup tomato sauce","1 cup cabbage (chopped)","1 onion","4 cups fish stock","1 tbsp oil","salt"],"steps":["Pan-fry fish steaks in oil for 2 minutes per side; set aside.","Sauté onion in the same pot; add tomato sauce and fish stock. Bring to a boil.","Add chickpeas and saba banana slices; cook for 6 minutes.","Gently place fried fish steaks and chopped cabbage into broth; simmer for 3 minutes. Season with salt."],"note":"Heart-healthy alternative to pork pochero, lowering saturated fat while retaining rich lycopene from tomato sauce.","id":"r386"},{"title":"Tinolang Tahong (Mussel Ginger Soup)","category":"soup","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["1 kg fresh green mussels (tahong, scrubbed and debearded)","2 thumbs ginger (julienned)","1 onion","1 bunch spinach or chili leaves","1 tbsp oil","4 cups water","patis"],"steps":["Sauté ginger and onion in oil until soft and fragrant.","Add scrubbed mussels and stir-fry for 2 minutes.","Pour in water, cover pot, and boil for 5 minutes until mussel shells open wide.","Season with patis, stir in spinach/chili leaves, and turn off heat immediately."],"note":"Exceptional source of marine Omega-3s, Vitamin B12, and trace minerals like iron and manganese.","id":"r387"},{"title":"Kalabasa Soup (Filipino Cream of Squash)","category":"soup","prep":"15 mins","cook":"20 mins","servings":"4","ingredients":["3 cups calabaza squash (peeled and cubed)","1 cup low-fat milk or light coconut milk","1 onion (diced)","2 cloves garlic","3 cups vegetable broth","1 tbsp olive oil","nutmeg","salt","and pepper"],"steps":["Sauté garlic and onion in olive oil until soft.","Add squash cubes and vegetable broth; simmer for 15 minutes until squash is completely tender.","Puree contents using an immersion blender until smooth.","Stir in low-fat milk/light coconut milk, season with salt, pepper, and a pinch of nutmeg, then warm gently for 2 minutes."],"note":"Rich in Provitamin A carotenoids (beta-carotene) and potassium with a smooth, comforting texture.","id":"r388"},{"title":"Sweet Potato Leaves Clear Broth","category":"soup","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["3 cups fresh talbos ng kamote (sweet potato tops)","1 tomato (wedged)","1 onion (sliced)","1 thumb ginger (sliced)","4 cups rice washing or water","patis"],"steps":["Bring rice washing, ginger, onion, and tomato to a boil in a pot; simmer for 5 minutes.","Add patis to taste.","Add cleaned sweet potato tops, turn off heat immediately, and cover for 3 minutes to allow leaves to steam tender."],"note":"High concentrations of lutein, polyphenols, and dietary fiber supporting ocular and metabolic wellness.","id":"r389"},{"title":"Baguio Vegetable Clear Soup","category":"soup","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["1 cup broccoli florets","1 cup cauliflower florets","1/2 cup carrots (sliced)","1/2 cup sugar snap peas","4 cups vegetable broth","2 cloves garlic (crushed)","salt","white pepper"],"steps":["Bring vegetable broth and crushed garlic to a boil.","Add hard vegetables (carrots and cauliflower florets); simmer for 4 minutes.","Add broccoli florets and sugar snap peas; cook for 3 minutes.","Season with salt and white pepper, then serve immediately while vegetables retain bright colors."],"note":"Cruciferous vegetable blend loaded with sulforaphane compounds, Vitamin C, and insoluble fiber.","id":"r390"},{"title":"Suam na Tulya","category":"soup","prep":"15 mins","cook":"12 mins","servings":"4","ingredients":["1 kg freshwater clams (tulya)","2 thumbs ginger (julienned)","4 cloves garlic","1 bunch dahon ng sili","1 tbsp cooking oil","4 cups water","salt"],"steps":["Heat oil in a saucepan; sauté garlic and ginger until light golden.","Add washed tulya clams and toss over high heat for 1 minute.","Pour in water, cover the pan, and boil for 5 minutes until shells pop open.","Season with salt, fold in chili leaves, turn off heat, and serve."],"note":"Traditional postpartum and convalescent broth valued for mineral replacement and warmth.","id":"r391"},{"title":"Tinola sa Gata (Chicken Ginger in Light Coconut Milk)","category":"soup","prep":"15 mins","cook":"35 mins","servings":"5","ingredients":["500g chicken cuts","1 cup light coconut milk","2 thumbs ginger (julienned)","1 green papaya (wedged)","1 bunch of malunggay leaves","1 onion","4 cups water","salt"],"steps":["Sauté ginger and onion; add chicken pieces and sear for 5 minutes.","Pour in 3 cups of water and simmer for 20 minutes until the chicken is tender.","Add green papaya wedges and 1 cup light coconut milk; simmer gently for 10 minutes (do not boil rapidly).","Stir in malunggay leaves, season with salt, and remove from heat."],"note":"Lauric acid from coconut milk paired with the galactagogue and antioxidant properties of Moringa oleifera.","id":"r392"},{"title":"Sinigang na Upo with Pork Strips","category":"soup","prep":"10 mins","cook":"20 mins","servings":"4","ingredients":["150g lean pork strips","2 cups upo (bottle gourd, peeled and cubed)","1/2 cup tamarind juice extract","1 tomato","1 onion","4 cups water","salt"],"steps":["Sear lean pork strips in a pot until light brown.","Add tomato, onion, and water; simmer for 10 minutes.","Stir in tamarind extract and upo cubes; simmer for 7 minutes until upo turns translucent.","Season with salt and serve hot."],"note":"Bottle gourd offers high fluid hydration and low caloric density, making it suitable for weight-management diets.","id":"r393"},{"title":"Beef Pares Broth","category":"soup","prep":"10 mins","cook":"1 hr 30 mins","servings":"5","ingredients":["400g beef brisket/beef bone","1 star anise","1 thumb ginger","1 cinnamon bark piece","1 tbsp light soy sauce","6 cups water","chopped green onions"],"steps":["Simmer beef brisket, bone, star anise, ginger, cinnamon, and soy sauce in 6 cups water for 1.5 hours until beef is tender.","Strain broth to remove spices and small bone fragments.","Slice cooked beef thinly.","Serve clear spiced broth in individual bowls garnished generously with green onions."],"note":"Aromatic botanical spice infusion (cinnamon and star anise) provides antioxidant activity without extra sugars.","id":"r394"},{"title":"Ginisang Misua at Patola Soup","category":"soup","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["1 medium patola (sliced into rounds)","50g misua (fine wheat noodles)","2 cloves garlic (minced)","1 onion (diced)","100g shrimp (peeled)","4 cups water or vegetable stock","1 tbsp oil","salt"],"steps":["Sauté garlic and onion in oil; stir in peeled shrimp and cook for 2 minutes.","Pour in water/stock and bring to a simmer.","Add patola rounds; cook for 4 minutes until tender.","Drop in misua noodles, cook for 1 minute, season with salt, and remove from heat."],"note":"Soft-textured, easily digestible soup ideal for individuals needing gentle dietary regimens.","id":"r395"},{"title":"Mushroom Clear Broth with Malunggay","category":"soup","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["2 cups fresh local oyster mushrooms (torn into strips)","2 cups malunggay leaves","1 thumb ginger (sliced)","1 onion","4 cups vegetable stock","salt and pepper"],"steps":["Bring vegetable stock, ginger, and onion to a boil in a pot.","Add oyster mushroom strips; simmer for 8 minutes.","Season with salt and pepper.","Turn off heat, fold in malunggay leaves, cover for 2 minutes, and serve."],"note":"Mushrooms deliver beta-glucan soluble fibers that support immune health while keeping calorie count minimal.","id":"r396"},{"title":"Sinigang na Hipon sa Santol","category":"soup","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["400g medium shrimp","2 ripe santol fruits (peeled, seeds and grated pericarp pulp used)","1 bunch kangkong","1 onion","2 green peppers","5 cups water","salt"],"steps":["Simmer peeled santol pulp and seeds with onion in 5 cups of water for 10 minutes until sour juices render.","Add green long peppers and medium shrimp; cook for 4 minutes.","Season broth with salt.","Turn off heat, add kangkong leaves, cover for 2 minutes, and serve warm."],"note":"Santol fruit provides natural pectin fiber and organic fruit acids for souring without added synthetic additives.","id":"r397"},{"title":"Utan Bisaya (Vegetable Clear Soup)","category":"soup","prep":"15 mins","cook":"15 mins","servings":"5","ingredients":["1 cup squash (cubed)","1 cup eggplant (sliced)","1 cup okra","1 cup sitaw","1 cup alugbati (Malabar spinach)","1 thumb ginger","5 cups water","salt"],"steps":["Boil water with sliced ginger in a pot.","Add hard squash cubes first; simmer for 5 minutes.","Add eggplant, okra, and sitaw; cook for 5 minutes.","Season with salt, fold in alugbati leaves, turn off heat, and serve."],"note":"Traditional fat-free, multi-vegetable clear soup providing a broad spectrum of micronutrients and insoluble fiber.","id":"r398"},{"title":"Dinengdeng (Ilocano Bagoong-based Vegetable Soup)","category":"soup","prep":"15 mins","cook":"20 mins","servings":"5","ingredients":["1 piece grilled or fried fish (Tilapia or Bangus)","2 tbsp bagoong isda (fermented fish paste, strained)","1 cup squash fruit and flowers","1 cup sitaw","1 cup ampakaya slices","1 cup sweet potato tops","5 cups rice washing"],"steps":["Bring rice washing to a boil in a clay pot or saucepan; stir in strained bagoong isda liquid.","Add squash cubes; cook for 5 minutes.","Add sitaw, bitter melon slices, and squash flowers; simmer for 5 minutes.","Lay grilled/fried fish on top of vegetables and fold in sweet potato tops.","Simmer for 2 minutes and serve warm."],"note":"High micronutrient density from varied local vegetables; fermented bagoong delivers savory umami with trace minerals.","id":"r399"},{"title":"Kapampangan Asadong Manok Soup Base","category":"soup","prep":"15 mins","cook":"30 mins","servings":"4","ingredients":["400g chicken pieces","1/4 cup calamansi juice","2 tbsp soy sauce","1 potato (cubed)","1 onion","2 tomatoes","4 cups chicken stock","1 tbsp oil","black pepper"],"steps":["Marinate chicken in calamansi juice and soy sauce for 15 minutes.","Heat oil; sauté onion, tomatoes, and marinated chicken until seared.","Pour in chicken stock and potato cubes; simmer for 20 minutes until chicken and potatoes are tender.","Season with black pepper and serve warm."],"note":"Citrus marination helps tenderize poultry proteins while enhancing iron absorption through natural Vitamin C. DESSERTS:","id":"r400"},{"title":"Leche Flan (Reduced-Sugar Filipino Custard)","category":"dessert","prep":"20 mins","cook":"45 mins","servings":"8","ingredients":["8 egg yolks","1 cup condensed milk (skimmed/low-fat)","1 cup evaporated milk (low-fat)","1 tsp vanilla extract","3 tbsp coconut sugar (for caramel caramelization)"],"steps":["Melt coconut sugar in llanera molds over low heat until caramelized; spread evenly.","Whisk egg yolks gently without creating air bubbles. Mix in condensed milk, evaporated milk, and vanilla.","Strain mixture through cheesecloth twice into prepared molds.","Cover with foil and steam on low heat for 40 minutes until set. Chill before serving."],"note":"Utilizing coconut sugar lowers the glycemic index compared to white refined caramel.","id":"r401"},{"title":"Halo-Halo (Classic Filipino Shaved Ice)","category":"dessert","prep":"20 mins","cook":"0 mins","servings":"2","ingredients":["Shaved ice","1/2 cup low-fat evaporated milk","2 tbsp sweetened saba bananas","2 tbsp sweet potato cubes","2 tbsp red beans","2 tbsp nata de coco","1 tbsp kaong","1 slice leche flan","1 scoop ube halaya"],"steps":["Layer sweetened beans, saba bananas, sweet potatoes, nata de coco, and kaong at the bottom of a tall glass.","Fill the glass to top with finely shaved ice.","Pour evaporated milk over ice.","Crown with a slice of leche flan and a small scoop of ube halaya."],"note":"Rich in functional fibers from resistant-starch root crops and legumes.","id":"r402"},{"title":"Mango Float (Filipino Icebox Cake)","category":"dessert","prep":"25 mins","cook":"0 mins","servings":"10","ingredients":["3 large ripe Carabao mangoes (thinly sliced)","1 pack Graham crackers","1 cup light whipping cream","1/2 cup condensed milk"],"steps":["Whip light cream and condensed milk in a bowl until thickened.","Arrange a layer of Graham crackers at the bottom of a rectangular glass dish.","Spread a layer of cream mixture and top with sliced fresh mangoes.","Repeat layers twice, finishing with mangoes and crushed Grahams. Chill/freeze for 4 hours."],"note":"Fresh Carabao mangoes provide natural Vitamin A, C, and dietary enzymes.","id":"r403"},{"title":"Maja Blanca (Coconut Milk Pudding)","category":"dessert","prep":"10 mins","cook":"20 mins","servings":"8","ingredients":["2 cups coconut milk","1 cup sweet corn kernels","1/2 cup cornstarch","1/2 cup refined sugar or erythritol","1/2 cup fresh milk","latik (coconut curds) for topping"],"steps":["Combine coconut milk, sugar, and sweet corn in a pot; bring to a simmer.","Dissolve cornstarch in fresh milk and pour into simmering coconut milk, whisking continuously.","Cook over low heat, stirring constantly until thick and smooth.","Pour into a greased dish, flatten top, cool, and sprinkle with golden latik."],"note":"Naturally gluten-free dessert option utilizing cornstarch and coconut milk.","id":"r404"},{"title":"Ube Halaya (Purple Yam Jam)","category":"dessert","prep":"15 mins","cook":"45 mins","servings":"10","ingredients":["500g fresh purple yam (boiled and grated)","1 cup coconut milk","1/2 cup condensed milk","2 tbsp butter","1/3 cup sugar"],"steps":["Combine grated ube, coconut milk, condensed milk, and sugar in a heavy-bottomed skillet.","Cook over low heat, stirring continuously for 35–45 minutes until thick and pulling away from the sides.","Stir in butter until glossy. Transfer to greased molds and cool completely."],"note":"Purple yam contains powerful anthocyanin antioxidants responsible for its deep natural pigment.","id":"r405"},{"title":"Biko (Filipino Sticky Rice Cake)","category":"dessert","prep":"15 mins","cook":"40 mins","servings":"10","ingredients":["2 cups glutinous rice (malagkit)","1.5 cups water","2 cups coconut milk","1 cup dark muscovado sugar","latik topping"],"steps":["Cook glutinous rice with water in a rice cooker (slightly firm).","In a wide pan, simmer coconut milk and muscovado sugar until thick and syrupy.","Reserve 1/3 cup syrup. Fold cooked sticky rice into remaining syrup; stir over low heat until dense and sticky.","Transfer into a banana-leaf-lined tray, top with reserved syrup and latik, and bake/broil for 10 minutes."],"note":"Unrefined muscovado sugar preserves trace minerals like iron, potassium, and magnesium.","id":"r406"},{"title":"Ginataang Bilo-Bilo (Sticky Rice Balls in Coconut Cream)","category":"dessert","prep":"25 mins","cook":"25 mins","servings":"6","ingredients":["1 cup glutinous rice flour + 1/2 cup water (rolled into balls)","1 cup sweet potato (cubed)","1 cup saba banana (cubed)","1/2 cup jackfruit (langka, sliced)","2 cups coconut milk","1/2 cup sugar","1/2 cup tapioca pearls (sago)"],"steps":["Bring coconut milk and 1 cup water to a gentle boil.","Add sweet potatoes and saba bananas; cook for 8 minutes.","Drop glutinous rice balls into boiling liquid; cook until they float to the surface.","Stir in cooked sago, jackfruit, and sugar. Simmer for 5 minutes until thickened."],"note":"Energy-dense traditional snack/dessert featuring potassium-rich tropical roots and fruits.","id":"r407"},{"title":"Turon (Fried Banana Lumpia with Jackfruit)","category":"dessert","prep":"15 mins","cook":"15 mins","servings":"6","ingredients":["6 Saba bananas (halved lengthwise)","1/2 cup jackfruit strips","lumpia wrappers","3 tbsp brown sugar","oil for shallow frying"],"steps":["Roll banana slices lightly in brown sugar.","Place banana slices and jackfruit strips on lumpia wrapper; roll tightly and seal.","Pan-fry in medium heat, dusting a little sugar in the oil to caramelize the wrapper exterior.","Drain excess oil on a wire rack."],"note":"Saba bananas contain high resistant starch content when lightly cooked.","id":"r408"},{"title":"Minatamis na Saba (Sweetened Plantain)","category":"dessert","prep":"5 mins","cook":"20 mins","servings":"4","ingredients":["5 ripe Saba bananas (sliced into rounds)","1 cup water","1/2 cup raw cane sugar","1 tsp vanilla extract","pinch of salt"],"steps":["Combine water, cane sugar, vanilla, and salt in a pan; simmer until sugar dissolves.","Add sliced saba bananas.","Cover and cook over medium-low heat for 15 minutes until bananas are tender and syrup thickens."],"note":"Simple, un-refined whole food dessert free from processed additives.","id":"r409"},{"title":"Puto Bumbong (Purple Rice Cake)","category":"dessert","prep":"30 mins","cook":"10 mins","servings":"4","ingredients":["1 cup pirurutong (purple glutinous rice flour)","water","grated fresh coconut","muscovado sugar","butter/margarine"],"steps":["Moisten purple rice flour with water until grainy; steam in bamboo tubes (bumbong) or small steamer molds for 8 minutes.","Push steamed rice cakes out onto banana leaves.","Brush lightly with butter and top generously with fresh grated coconut and muscovado sugar."],"note":"Natural whole-grain purple rice delivers fiber and phytonutrients.","id":"r410"},{"title":"Kutsinta (Steamed Rice Cakes with Grated Coconut)","category":"dessert","prep":"15 mins","cook":"45 mins","servings":"10","ingredients":["1 cup rice flour","1/2 cup all-purpose flour","3/4 cup brown sugar","2 cups water","1 tsp lye water","1/2 tsp annatto seeds (soaked in 2 tbsp warm water for color)","1 cup fresh grated coconut for serving"],"steps":["In a large bowl, whisk together rice flour, all-purpose flour, and brown sugar.","Gradually pour in water while stirring continuously to prevent lumps.","Strain in the strained annatto water and lye water, mixing thoroughly until smooth.","Lightly grease small silicone or metal molds with oil. Pour the batter into molds, filling 3/4 full.","Steam over medium heat for 40–45 minutes until set and translucent.","Cool completely before unmolding. Top generously with fresh grated coconut."],"note":"A naturally low-fat, high-carbohydrate steamed snack. Pairing with fresh coconut adds medium-chain triglycerides (MCTs) and fiber.","id":"r411"},{"title":"Puto Leche Flan (Hybrid Steamed Cake)","category":"dessert","prep":"25 mins","cook":"25 mins","servings":"12","ingredients":["## Flan Layer","4 egg yolks","1/2 cup sweetened condensed milk","1/4 cup evaporated milk","1 tsp vanilla extract","## Puto Layer","1 cup all-purpose flour","1/2 cup white sugar","1 tbsp baking powder","1/2 cup water","1 egg","2 tbsp melted butter"],"steps":["Whisk flan ingredients until smooth; strain twice. Fill lightly greased puto molds 1/3 full with flan mixture.","Steam flan layer for 10 minutes over low heat until partially set.","Sift flour, sugar, and baking powder. Whisk in water, egg, and melted butter to create puto batter.","Pour puto batter over the partially cooked flan layer until molds are 4/5 full.","Steam for an additional 12–15 minutes until a toothpick inserted comes out clean. Cool before unmolding."],"note":"Portion-controlled hybrid dessert providing essential choline and vitamin A from egg yolks balanced with a light steamed base.","id":"r412"},{"title":"Suman sa Lihiya with Latik Sauce","category":"dessert","prep":"30 mins","cook":"1 hour 30 mins","servings":"10","ingredients":["2 cups glutinous rice (washed and soaked 2 hours)","1 tsp lye water","banana leaves (wilted over flame)","2 cups thick coconut caramel (coconut cream boiled with muscovado sugar for latik sauce)"],"steps":["Drain soaked glutinous rice thoroughly and mix in lye water until rice takes on a pale yellow hue.","Scoop 2–3 tablespoons of rice onto a wilted banana leaf, wrap tightly into a rectangle, and tie pairs together with string.","Submerge wrapped suman in a deep pot of water and boil continuously for 1 hour and 30 minutes.","Drain, unwrap, and drizzle generously with warm muscovado coconut latik sauce."],"note":"Glutinous rice offers quick-release energy for active recovery, while banana leaves yield beneficial plant polyphenols during steaming.","id":"r413"},{"title":"Sapin-Sapin (Layered Rice Cake)","category":"dessert","prep":"30 mins","cook":"50 mins","servings":"12","ingredients":["1.5 cups glutinous rice flour","1.5 cups coconut milk","3/4 cup sugar","1/2 cup condensed milk","1/2 tsp ube extract + purple food color","1/2 cup sweet corn puree + yellow food color","toasted latik for garnish"],"steps":["Whisk glutinous rice flour, coconut milk, sugar, and condensed milk until smooth; divide equally into 3 bowls.","Flavor bowl 1 with ube extract (purple), bowl 2 with sweet corn puree (yellow), and leave bowl 3 plain (white).","Pour purple mixture into a greased pan and steam for 15 minutes until firm.","Carefully pour white mixture on top and steam for 15 minutes.","Pour yellow mixture on top and steam for a final 20 minutes. Top with toasted coconut latik before slicing."],"note":"Complex native rice dessert providing dense plant carbohydrates; using real ube and corn adds natural micronutrients.","id":"r414"},{"title":"Cassava Cake (Baked Tapioca Root Cake)","category":"dessert","prep":"20 mins","cook":"1 hour","servings":"12","ingredients":["1 kg grated cassava (squeezed dry)","1.5 cups coconut milk","1/2 cup condensed milk","1/2 cup evaporated milk","2 eggs","1/2 cup melted butter","1/3 cup sugar","## Topping","1/2 cup coconut cream","1/4 cup condensed milk","1 egg yolk","grated cheddar cheese"],"steps":["Combine cassava, coconut milk, condensed milk, evaporated milk, eggs, melted butter, and sugar in a bowl.","Pour into a lined 9x13 inch baking pan and bake at 175°C (350°F) for 45 minutes until set.","Whisk topping ingredients (coconut cream, condensed milk, egg yolk) and pour over cooked cassava layer.","Sprinkle with grated cheese and broil for 15 minutes until the top is golden brown and caramelized."],"note":"Naturally gluten-free root crop cake packed with resistant starch and potassium.","id":"r415"},{"title":"Calamay (Sticky Coconut Jam Treat)","category":"dessert","prep":"15 mins","cook":"1 hour","servings":"10","ingredients":["2 cups glutinous rice flour","3 cups thick coconut milk","1.5 cups dark muscovado sugar","1/2 tsp vanilla extract"],"steps":["Dissolve glutinous rice flour in 1 cup of coconut milk to form a smooth slurry.","In a thick-bottomed wok, bring remaining coconut milk and muscovado sugar to a boil until sugar is fully dissolved.","Pour rice flour mixture into wok while stirring vigorously over low heat.","Cook continuously for 45–50 minutes, stirring constantly until thick, glossy, and pulling away cleanly from the pan."],"note":"Muscovado sugar provides unrefined minerals including magnesium, iron, and potassium alongside coconut fats.","id":"r416"},{"title":"Espasol (Toasted Rice Flour Cylinders)","category":"dessert","prep":"25 mins","cook":"35 mins","servings":"10","ingredients":["2 cups glutinous rice flour (sweet rice flour)","1.5 cups coconut milk","1 cup sugar","1 cup cooked grated young coconut (buko)","1/2 tsp vanilla"],"steps":["Dry-roast glutinous rice flour in a wide pan over medium-low heat until light golden and aromatic (about 15 mins). Reserve 1/2 cup for dusting.","In another pan, simmer coconut milk, sugar, grated young coconut, and vanilla until sugar dissolves.","Add toasted flour into the coconut mixture, stirring continuously until a stiff dough forms.","Transfer dough to a board dusted with reserved toasted flour. Dust top, roll into cylinders, and cut into 3-inch logs."],"note":"Toasting rice flour improves digestibility while whole young coconut provides dietary fiber.","id":"r417"},{"title":"Pastillas de Leche (Milk Candy)","category":"dessert","prep":"20 mins","cook":"0 mins","servings":"10","ingredients":["2 cups powdered full-cream milk","1 can (300ml) sweetened condensed milk","1 tbsp melted butter","white sugar for rolling"],"steps":["Sift powdered milk into a large mixing bowl.","Pour condensed milk and melted butter into the powdered milk.","Mix with a spatula until a smooth, pliable dough forms.","Pinch off small portions, roll into cylinders or small balls, and roll in white sugar. Wrap in cellophane or papel de japon."],"note":"Calcium-dense dairy candy serving as a quick source of fat-soluble vitamins and dietary protein.","id":"r418"},{"title":"Polvoron (Toasted Flour Shortbread)","category":"dessert","prep":"15 mins","cook":"15 mins","servings":"12","ingredients":["2 cups all-purpose flour","1 cup powdered milk","3/4 cup melted unsalted butter","3/4 cup sugar"],"steps":["Toast flour in a skillet over low heat, stirring constantly until lightly browned and fragrant (approx. 12 minutes). Let cool.","Sift toasted flour and powdered milk together into a bowl.","Stir in sugar, then pour in melted butter. Mix until fully combined and sandy in texture.","Compact mixture firmly into a polvoron mold and press out onto parchment paper. Wrap individually in tissue paper."],"note":"High-energy confectionery offering digestible dairy protein and balanced dietary fats.","id":"r419"},{"title":"Silvanas (Filipino Meringue Cookie Sandwiches)","category":"dessert","prep":"45 mins","cook":"20 mins","servings":"10","ingredients":["## Meringue","4 egg whites","1/2 tsp cream of tartar","1/2 cup fine sugar","1 cup finely ground roasted cashews","## Buttercream","1/2 cup unsalted butter","1/4 cup condensed milk","## Coating","1 cup crushed Graham crackers"],"steps":["Whip egg whites with cream of tartar, adding sugar gradually until stiff peaks form. Fold in ground cashews.","Pipe oval wafers onto parchment-lined trays and bake at 150°C (300°F) for 20 minutes until crisp. Cool completely.","Whip butter and condensed milk together until light and fluffy.","Sandwich buttercream between two cashew meringue wafers, coat outside completely with buttercream, and roll in Graham crumbs. Freeze 2 hours before serving."],"note":"Cashews contribute monounsaturated fatty acids and essential zinc to this low-moisture frozen confection.","id":"r420"},{"title":"Sans Rival (Cashew Meringue Layer Cake)","category":"dessert","prep":"50 mins","cook":"25 mins","servings":"12","ingredients":["## Layers","6 egg whites","1/2 tsp cream of tartar","3/4 cup caster sugar","1.5 cups chopped roasted cashews","## French Buttercream","6 egg yolks","3/4 cup sugar","1/4 cup water","1.5 cups softened unsalted butter"],"steps":["Whip egg whites and cream of tartar to soft peaks; gradually add sugar to stiff peaks. Fold in chopped cashews.","Spread evenly across 4 rectangular parchment-lined baking sheets. Bake at 150°C (300°F) for 20–25 minutes until crisp and golden.","Boil sugar and water to 118°C (240°F); slowly pour into beaten egg yolks while whipping. Beat in softened butter until silky.","Layer meringue wafers with French buttercream. Frost top and sides, then coat with extra chopped cashews. Chill overnight."],"note":"Naturally gluten-free layer cake rich in cashew plant lipids and clean dairy fats.","id":"r421"},{"title":"Buko Pandan Dessert Salad","category":"dessert","prep":"20 mins","cook":"10 mins","servings":"8","ingredients":["1 pack green unflavored agar-agar (gulaman)","2 cups water infused with pandan leaves","2 cups fresh young coconut (buko) strips","1 cup heavy cream","1/2 cup condensed milk","1/2 cup nata de coco"],"steps":["Dissolve agar-agar powder in pandan water, boil for 5 minutes, pour into a square dish, and let set. Dice into cubes.","In a large bowl, combine diced pandan jelly, buko strips, and nata de coco.","Pour heavy cream and condensed milk over mixture; toss gently to combine.","Chill in the refrigerator for at least 4 hours before serving cold."],"note":"High-moisture chilled dessert providing prebiotic fiber from nata de coco and buko meat.","id":"r422"},{"title":"Fruit Salad Tagalog Style","category":"dessert","prep":"15 mins","cook":"0 mins","servings":"8","ingredients":["1 large can (825g) fruit cocktail (drained thoroughly)","1 cup buko strips","1/2 cup maraschino cherries","1/2 cup cheese cubes","1 cup heavy cream","3/4 cup condensed milk"],"steps":["Drain fruit cocktail in a colander for 30 minutes to remove excess heavy syrup.","In a large bowl, combine drained fruit cocktail, buko strips, cherries, and cheese cubes.","Fold in heavy cream and condensed milk until ingredients are thoroughly coated.","Chill overnight in the freezer or cold refrigerator before serving."],"note":"Draining canning syrup reduces overall refined sugar while savory cheese provides balance and sodium regulation.","id":"r423"},{"title":"Cathedral Window Jelly Dessert","category":"dessert","prep":"40 mins","cook":"15 mins","servings":"10","ingredients":["## Colored Cubes","3 packs flavored agar-agar (red, green, yellow)","sugar","water","## Cream Base","1 tbsp unflavored gelatine powder dissolved in 1/4 cup warm water","1 cup heavy cream","1/2 cup condensed milk","1/2 cup pineapple juice"],"steps":["Prepare red, green, and yellow agar-agar separately according to package instructions. Let set and cut into uniform cubes.","Heat pineapple juice, dissolve gelatin mixture into it, then whisk into heavy cream and condensed milk; cool to room temp.","Arrange colored jelly cubes randomly in a bundt mold or rectangular pan.","Pour white cream mixture over jelly cubes. Refrigerate 4 hours until completely set before unmolding."],"note":"Gelatin and agar-agar provide dietary collagen and seaweed polysaccharides that aid gut motility.","id":"r424"},{"title":"Ginataang Corn at Sticky Rice (Champorado White)","category":"dessert","prep":"10 mins","cook":"30 mins","servings":"6","ingredients":["1 cup glutinous rice","1 can (400ml) coconut milk","2 cups water","1 can (400g) sweet kernel corn (with liquid)","1/2 cup sugar","coconut cream for drizzle"],"steps":["Combine glutinous rice, water, and 1 cup coconut milk in a pot; bring to a simmer.","Cook over medium-low heat for 20 minutes, stirring occasionally, until rice is soft.","Stir in sweet corn, remaining coconut milk, and sugar.","Simmer for an additional 10 minutes until thick and creamy. Serve warm with a drizzle of coconut cream."],"note":"Energy-dense breakfast or dessert offering complex carbs from sweet corn and glutinous rice.","id":"r425"},{"title":"Champorado (Chocolate Rice Porridge)","category":"dessert","prep":"10 mins","cook":"25 mins","servings":"4","ingredients":["1 cup glutinous rice","4 cups water","4 tablea tablets (pure cacao)","1/3 cup brown sugar","low-fat evaporated milk for drizzle","fried tinapa or salted fish (optional traditional pairing)"],"steps":["Boil water and glutinous rice in a pot; lower heat and simmer for 15 minutes, stirring frequently.","Add cacao tablea tablets and stir until completely dissolved into the porridge.","Stir in brown sugar and cook for 5–10 more minutes until rice grains are soft and thick.","Ladle into bowls, drizzle with evaporated milk, and serve warm with crispy salted fish on the side."],"note":"Cacao provides high concentrations of cocoa flavonoids and magnesium, offering cardiovascular benefits.","id":"r426"},{"title":"Tsokolate Ah Soufflé Pudding","category":"dessert","prep":"20 mins","cook":"20 mins","servings":"4","ingredients":["3 tablea cacao tablets (dissolved in 1/2 cup hot milk)","2 egg yolks","3 egg whites","2 tbsp flour","2 tbsp butter","3 tbsp sugar"],"steps":["Melt butter, whisk in flour, and gradually stir in dissolved cacao tablea milk until thick; cool slightly and beat in egg yolks.","Whip egg whites with sugar in a clean bowl until stiff peaks form.","Gently fold whipped egg whites into the cacao base in two batches.","Divide into buttered ramekins dusted with sugar. Bake at 190°C (375°F) for 18–20 minutes until puffed. Serve immediately."],"note":"Elevated application of native cacao yielding airy texture with controlled sugar and high antioxidant density.","id":"r427"},{"title":"Banana Cue (Skewered Caramelized Saba)","category":"dessert","prep":"5 mins","cook":"10 mins","servings":"4","ingredients":["8 ripe Saba bananas (peeled)","1/2 cup dark brown sugar","oil for shallow frying","bamboo skewers"],"steps":["Heat oil in a deep skillet over medium heat.","Add Saba bananas and sprinkle dark brown sugar directly over oil and bananas.","As sugar melts and caramelizes, gently turn bananas continuous to coat evenly in brown sugar glaze.","Drain on a rack and skewer two bananas per bamboo stick while warm."],"note":"Saba bananas are an outstanding source of potassium, vitamin B6, and resistant starch.","id":"r428"},{"title":"Kamote Cue (Caramelized Sweet Potato)","category":"dessert","prep":"10 mins","cook":"12 mins","servings":"4","ingredients":["2 large orange/purple sweet potatoes (peeled and sliced into 1/2 inch rounds)","1/2 cup brown sugar","oil for frying","bamboo skewers"],"steps":["Heat oil in a pan over medium heat; drop in sweet potato slices.","Add brown sugar; allow sugar to float and caramelize.","Turn sweet potato rounds frequently until soft on the inside and thoroughly coated in crispy caramel.","Skewer 3 rounds per stick and serve warm."],"note":"Rich source of beta-carotene (vitamin A precursor), plant fiber, and low-glycemic complex carbohydrates.","id":"r429"},{"title":"Carioca (Glutinous Rice Ball Skewers)","category":"dessert","prep":"20 mins","cook":"15 mins","servings":"5","ingredients":["## Dough","2 cups glutinous rice flour","1 cup sweetened shredded coconut","3/4 cup coconut milk","## Glaze","1/2 cup brown sugar","1/2 cup coconut cream"],"steps":["Mix glutinous rice flour, shredded coconut, and coconut milk until a soft dough forms. Roll into 1-inch balls.","Deep-fry or air-fry rice balls until light golden brown and floating; drain well.","In a separate skillet, boil brown sugar and coconut cream until thick and caramel-like.","Toss fried balls in coconut glaze, skewer onto bamboo sticks, and serve warm."],"note":"Combines plant fats and chewy rice starch; baking or air-frying cuts absorbed fats significantly.","id":"r430"},{"title":"Maruya (Banana Fritters)","category":"dessert","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["6 Saba bananas (sliced fan-style)","1 cup flour","1 egg","1/2 cup milk","1/4 cup sugar","1 tsp baking powder","pinch of salt","oil for pan-frying"],"steps":["Whisk flour, sugar, baking powder, salt, egg, and milk into a smooth batter.","Slice bananas lengthwise into connected fan shapes.","Dip fanned bananas into batter, coating evenly.","Shallow fry in hot pan until golden brown on both sides. Dust lightly with sugar before serving."],"note":"Energy-dense fruit snack providing natural potassium and digestible complex carbohydrates.","id":"r431"},{"title":"Inutak (Layered Baked Rice Cream)","category":"dessert","prep":"20 mins","cook":"35 mins","servings":"8","ingredients":["2 cups cooked glutinous rice","1.5 cups thick coconut milk","1/2 cup condensed milk","1/4 cup sugar","ube halaya layer (optional)","coconut cream for top layer"],"steps":["Mash cooked glutinous rice with coconut milk, condensed milk, and sugar over low heat until thick and sticky.","Spread half the rice mixture into a lined baking dish. Add a thin layer of ube halaya if desired.","Top with remaining rice mixture and pour heavy coconut cream evenly over the top surface.","Bake at 200°C (400°F) for 20 minutes, then broil the top until charred (\"utak\" or brain-like pattern)."],"note":"Traditional Tagalog baked rice pudding supplying rich coconut fats and starch energy.","id":"r432"},{"title":"Tibok-Tibok (Kapampangan Milk Pudding)","category":"dessert","prep":"15 mins","cook":"20 mins","servings":"6","ingredients":["4 cups fresh carabao's milk (or full-cream milk)","3/4 cup cornstarch","1/2 cup sugar","zest of 1 dayap (local lime)","latik for topping"],"steps":["Whisk cornstarch and sugar into cold milk until fully dissolved; add dayap zest.","Pour into a pot and cook over medium-low heat, stirring continuously with a wooden spoon.","Cook until mixture thickens into a glossy, smooth custard that bubbles gently (\"tibok-tibok\").","Pour into a greased dish, cool, and garnish with toasted latik."],"note":"High-protein, high-calcium dairy pudding using local citrus zest to enhance flavor without extra sodium.","id":"r433"},{"title":"Bayabay / Native Rice Truffles","category":"dessert","prep":"20 mins","cook":"15 mins","servings":"6","ingredients":["1.5 cups toasted glutinous rice flour","3/4 cup muscovado syrup","1/2 cup toasted sesame seeds","1/2 cup grated fresh coconut"],"steps":["Toast glutinous rice flour in a pan until golden and nutty; cool.","Slowly fold muscovado syrup into toasted flour until a firm, moldable paste forms.","Pinch small pieces and roll into bite-sized truffle balls.","Roll half the balls in toasted sesame seeds and the other half in fresh grated coconut."],"note":"Sesame seeds introduce essential calcium, healthy lignans, and zinc into a traditional sweet truffle.","id":"r434"},{"title":"Suman Malagkit with Fresh Mangoes","category":"dessert","prep":"20 mins","cook":"45 mins","servings":"6","ingredients":["2 cups glutinous rice","1.5 cups coconut milk","1/2 cup sugar","1/2 tsp salt","banana leaves","3 ripe Carabao mangoes (sliced)"],"steps":["Simmer glutinous rice, coconut milk, sugar, and salt in a pot until liquid is absorbed (half-cooked).","Scoop onto wilted banana leaves, roll into logs, and tie securely.","Steam for 35–40 minutes until rice is soft and cooked through.","Unwrap warm suman and serve alongside fresh, sweet Carabao mango slices."],"note":"Pairing sticky rice with fresh mango delivers vitamin C and digestive enzymes (mangiferin) to aid starch metabolism.","id":"r435"},{"title":"Puto Seco (Dry Coconut Cookies)","category":"dessert","prep":"15 mins","cook":"15 mins","servings":"10","ingredients":["2 cups cornstarch","1/2 cup powdered milk","1/2 cup unsalted butter (softened)","1/2 cup sugar","1 egg yolk","2 tbsp coconut milk"],"steps":["Cream butter, sugar, and egg yolk together until fluffy.","Sift in cornstarch and powdered milk; add coconut milk to form a dry, powdery dough.","Press dough firmly into traditional wooden puto seco molds to shape.","Bake on parchment-lined sheets at 160°C (325°F) for 12–15 minutes until set and dry."],"note":"Low-moisture, gluten-free snack made primarily of cornstarch, giving a crisp texture that melts easily.","id":"r436"},{"title":"Lengua de Gato (Filipino Butter Cookies)","category":"dessert","prep":"15 mins","cook":"10 mins","servings":"8","ingredients":["1/2 cup unsalted butter (softened)","1/2 cup confectioners' sugar","2 egg whites","1 cup all-purpose flour","1/2 tsp vanilla extract"],"steps":["Cream butter and confectioners' sugar until light and pale.","Add egg whites gradually while whipping, then stir in vanilla.","Fold in sifted flour until a smooth batter forms.","Pipe 3-inch thin strips (cat's tongue shape) onto parchment-lined baking sheets. Bake at 180°C (350°F) for 8–10 minutes until edges are golden."],"note":"Light, crispy cookie portioning minimal calorie density per crisp wafer.","id":"r437"},{"title":"Ube Macapuno Cake Portion","category":"dessert","prep":"35 mins","cook":"30 mins","servings":"10","ingredients":["## Cake","1.5 cups cake flour","1 tsp baking powder","4 eggs (separated)","1/2 cup sugar","1/3 cup oil","1/2 cup ube halaya","1 tsp ube extract","## Frosting & Filling","1 cup whipped cream","1 cup macapuno (sweetened coconut sport) preserves"],"steps":["Whisk egg yolks, oil, ube halaya, ube extract, and flour together.","Whip egg whites and sugar to stiff peaks; fold gently into ube mixture.","Bake in two 8-inch pans at 175°C (350°F) for 25–30 minutes; cool completely.","Layer cake with whipped cream and macapuno preserves. Frost exterior with ube whipped cream."],"note":"Yam anthocyanins combined with coconut sport provide antioxidants and unique dietary fibers.","id":"r438"},{"title":"Leche Flan Jelly Cups","category":"dessert","prep":"20 mins","cook":"15 mins","servings":"8","ingredients":["## Flan Layer","3 egg yolks","1/2 cup condensed milk","1/2 cup evaporated milk","1 tsp gelatin powder","## Jelly Layer","1 pack unflavored yellow agar-agar","2 cups water","1/3 cup caramel sugar"],"steps":["Whisk flan ingredients with gelatin over low heat until dissolved; pour into small serving cups 1/2 full and chill until set.","Boil agar-agar and sugar in water until dissolved; cool slightly.","Gently pour clear caramel jelly mixture over the set flan layer.","Chill in the refrigerator for 2 hours before serving."],"note":"Provides a light, portion-controlled flan alternative with lower overall fat per serving.","id":"r439"},{"title":"Avocado with Condensed Milk & Ice","category":"dessert","prep":"5 mins","cook":"0 mins","servings":"2","ingredients":["2 ripe avocados (cubed or scooped)","3 tbsp sweetened condensed milk or heavy cream","crushed ice"],"steps":["Scoop ripe avocado flesh into chilled serving bowls.","Top generously with clean crushed ice.","Drizzle condensed milk over crushed ice and avocado. Serve immediately with a spoon."],"note":"Outstanding source of monounsaturated fatty acids (oleic acid), potassium, vitamin E, and dietary fiber.","id":"r440"},{"title":"Melon Shreds with Coconut Cream Dessert","category":"dessert","prep":"15 mins","cook":"0 mins","servings":"4","ingredients":["1 ripe cantaloupe melon (scraped into long strands)","1 cup cold coconut cream","3 tbsp raw honey or palm sugar","crushed ice"],"steps":["Scrape cantaloupe flesh using a shredder into thin ribbons; place in a serving bowl.","Whisk cold coconut cream with honey until smooth.","Combine melon strands with coconut cream and serve over shaved ice."],"note":"Rich in vitamin A (beta-carotene), electrolytes, and hydrating plant fluids.","id":"r441"},{"title":"Ginataang Kamoteng Kahoy","category":"dessert","prep":"15 mins","cook":"30 mins","servings":"6","ingredients":["500g cassava (peeled and cut into bite-sized chunks)","2 cups coconut milk","1/2 cup brown sugar","1/2 tsp vanilla extract","pinch of salt"],"steps":["Place cassava chunks, coconut milk, and 1/2 cup water in a pot; bring to a simmer.","Cook over medium heat for 20 minutes until cassava is soft and fork-tender.","Stir in brown sugar, salt, and vanilla.","Simmer for an additional 10 minutes until liquid thickens into a rich coconut sauce."],"note":"Cassava root provides energy-dense carbohydrates and valuable minerals such as magnesium and copper.","id":"r442"},{"title":"Binignit (Visayan Sweet Stew)","category":"dessert","prep":"25 mins","cook":"35 mins","servings":"8","ingredients":["1 cup sweet potato (cubed)","1 cup taro/gabi (cubed)","1 cup saba banana (cubed)","1/2 cup cooked sago pearls","1/2 cup landang (native palm tapioca) or tapioca pearls","3 cups coconut milk","3/4 cup muscovado sugar"],"steps":["Bring coconut milk and 1 cup water to a gentle boil in a large pot.","Add sweet potato and taro cubes; simmer for 10 minutes.","Add saba bananas, landang, and cooked sago pearls; cook for another 10 minutes.","Stir in muscovado sugar and cook until all the tubers are tender and stew is thick."],"note":"Complex fiber-rich stew containing diverse prebiotic starches from regional tubers and plantains.","id":"r443"},{"title":"Landang (Sago Native Stew)","category":"dessert","prep":"15 mins","cook":"30 mins","servings":"6","ingredients":["1 cup landang (native sago palm starch flakes)","2 cups coconut milk","1/2 cup jackfruit (langka) strips","1/2 cup brown sugar","2 cups water"],"steps":["Soak landang flakes in 1 cup water for 15 minutes to soften.","In a pot, combine coconut milk, water, and soaked landang; bring to a boil.","Lower heat and simmer for 15–20 minutes, stirring occasionally until landang turns soft and translucent.","Add jackfruit strips and brown sugar; cook for 5 minutes until aromatic."],"note":"Traditional palm starch dessert offering easily digestible energy suitable for sensitive digestion.","id":"r444"},{"title":"Latik Coconut Caramel Fondue with Fruits","category":"dessert","prep":"10 mins","cook":"25 mins","servings":"6","ingredients":["## Fondue","1.5 cups coconut cream","3/4 cup dark muscovado sugar","pinch of sea salt","## Dippers","Fresh mango slices","saba banana rounds","sweet potato cubes"],"steps":["Combine coconut cream and muscovado sugar in a saucepan over medium heat.","Stir continuously until sauce boils, then reduce heat to low and simmer for 20 minutes until glossy and thick.","Pour caramel fondue into a warm ceramic bowl.","Serve alongside skewers of fresh mango, steamed saba bananas, and sweet potato cubes."],"note":"Whole-fruit dipping concept replaces refined baked goods with nutrient-dense fruits and unrefined minerals.","id":"r445"},{"title":"Sweet Potato Donuts Tagalog","category":"dessert","prep":"20 mins","cook":"15 mins","servings":"6","ingredients":["1 cup mashed cooked sweet potato","1.5 cups all-purpose flour","1 tsp instant yeast","2 tbsp sugar","1/4 cup warm milk","1 egg","cinnamon sugar for dusting","oil for frying"],"steps":["Dissolve yeast and sugar in warm milk; let bloom for 5 minutes.","Mix mashed sweet potato, egg, yeast mixture, and flour into a soft dough. Knead 5 minutes, cover, and let rise for 45 minutes.","Shape dough into ring donuts.","Fry or air-fry at 170°C (340°F) until golden brown. Toss immediately in cinnamon sugar."],"note":"Incorporating mashed sweet potato boosts dietary fiber and natural beta-carotene content over standard doughs.","id":"r446"},{"title":"Ube Crinkles","category":"dessert","prep":"20 mins","cook":"12 mins","servings":"12","ingredients":["2 cups all-purpose flour","1 tsp baking powder","1/2 cup sugar","1/4 cup oil","2 eggs","1/2 cup ube halaya","1 tsp ube extract","1 cup powdered sugar for rolling"],"steps":["Whisk flour and baking powder in a bowl.","In another bowl, beat oil, sugar, eggs, ube halaya, and ube extract until smooth.","Combine wet and dry ingredients into a sticky dough. Chill in refrigerator for 2 hours.","Scoop dough into balls, roll generously in powdered sugar, and bake at 175°C (350°F) for 10–12 minutes until crinkled."],"note":"Rich purple yam base provides plant-derived anthocyanins in a soft-baked cookie format.","id":"r447"},{"title":"Kalamay Hati","category":"dessert","prep":"15 mins","cook":"45 mins","servings":"10","ingredients":["2 cups glutinous rice flour","2 cups coconut milk","1.5 cups dark coconut sugar or muscovado","toasted sesame seeds or latik"],"steps":["Mix glutinous rice flour and 1 cup coconut milk until smooth.","Heat remaining coconut milk and muscovado sugar in a heavy skillet until boiling.","Pour rice slurry into the sugar mixture while stirring continuously over low heat.","Cook for 35–40 minutes until thick, smooth, and stretchy. Pour into coconut-shell halves or pan, top with sesame seeds/latik."],"note":"Concentrated native coconut-rice treat offering quick-release glycogen-replenishing carbohydrates.","id":"r448"},{"title":"Piyaya (Flatbread with Muscovado Filling)","category":"dessert","prep":"30 mins","cook":"15 mins","servings":"8","ingredients":["## Dough","2 cups all-purpose flour","1/3 cup shortening/oil","1/2 cup water","## Filling","3/4 cup dark muscovado sugar","2 tbsp flour","1 tbsp water. Sesame seeds for topping"],"steps":["Mix flour, shortening, and water to form a smooth flatbread dough; rest 15 minutes and divide into 8 balls.","Mix muscovado sugar, flour, and water to form a paste for filling.","Flatten dough balls, place a spoon of muscovado filling in center, seal edges, and roll out thinly with a rolling pin.","Sprinkle with sesame seeds and cook on a dry, hot griddle over medium heat for 3–4 minutes per side until toasted."],"note":"Muscovado flatbread providing iron, potassium, and chromium from unrefined sugarcane syrup.","id":"r449"},{"title":"Napoleones (Bacolod Pastry Slice)","category":"dessert","prep":"45 mins","cook":"25 mins","servings":"8","ingredients":["1 sheet puff pastry dough","1 cup custard filling (milk, sugar, egg yolks, cornstarch, vanilla)","3/4 cup sugar glaze (confectioners' sugar + warm milk)"],"steps":["Cut puff pastry into rectangular squares. Bake at 200°C (400°F) for 15–20 minutes until puffed and golden brown; let cool and slice horizontally.","Pipe smooth egg custard filling between puff pastry layers.","Spread a smooth white sugar glaze over the top layer of pastry.","Allow glaze to set before serving."],"note":"Regional Bacolod pastry pairing delicate puff layers with rich egg yolk custard for an indulgent treat. BEVERAGES:","id":"r450"},{"title":"Fresh Calamansi Juice with Honey","category":"beverage","prep":"5 mins","cook":"0 mins","servings":"4","ingredients":["10 fresh calamansi (juiced)","4 cups cold water","3 tbsp raw wild honey","ice cubes"],"steps":["Slice calamansi fruits and squeeze juice through a strainer to remove seeds.","Whisk honey into room temperature water until dissolved.","Add calamansi juice and cold water. Stir well and serve over ice."],"note":"Rich in immune-supporting Vitamin C and bioflavonoids; honey offers a lower glycemic response than refined white syrup.","id":"r451"},{"title":"Sago't Gulaman (Filipino Pearl and Jelly Drink)","category":"beverage","prep":"15 mins","cook":"20 mins","servings":"6","ingredients":["1/2 cup cooked tapioca pearls (sago)","1 cup grass jelly or agar-agar (gulaman, cubed)","4 cups water","1/2 cup arnibal (muscovado sugar syrup)","1 tsp banana extract","shaved ice"],"steps":["Dissolve muscovado sugar in boiling water to create arnibal syrup; cool.","Stir in banana extract.","In tall glasses, combine cooked sago and diced gulaman.","Pour arnibal syrup and cold water over ice. Stir before drinking."],"note":"Using unrefined muscovado for arnibal syrup retains natural chromium and trace minerals.","id":"r452"},{"title":"Fresh Buko Water (Young Coconut Refreshment)","category":"beverage","prep":"5 mins","cook":"0 mins","servings":"2","ingredients":["4 cups fresh young coconut water","1 cup fresh buko meat (shredded)","ice cubes"],"steps":["Pour fresh coconut water directly from green buko into a glass pitcher.","Scrape soft coconut meat into thin shreds using a coconut scraper and add to pitcher.","Chill or serve immediately over ice."],"note":"Nature’s premier isotonic electrolyte drink—rich in potassium, sodium, and magnesium.","id":"r453"},{"title":"Samalamig na Melon (Filipino Shredded Melon Drink)","category":"beverage","prep":"15 mins","cook":"0 mins","servings":"5","ingredients":["1 cantaloupe melon (shredded using melon scraper)","4 cups cold water","3 tbsp brown sugar or stevia","1/2 cup evaporated light milk (optional)","ice"],"steps":["Halve cantaloupe, seed, and scrape flesh into long thin strands.","Mix melon strands, melon juices, water, and sweetening agent in a pitcher.","Stir in light evaporated milk if desired. Serve well-chilled over ice."],"note":"Excellent hydration drink loaded with Vitamin A (beta-carotene) and hydration minerals.","id":"r454"},{"title":"Tsokolate Ah (Traditional Filipino Hot Chocolate)","category":"beverage","prep":"5 mins","cook":"10 mins","servings":"3","ingredients":["3 tablets pure cacao tablea","2 cups water or low-fat milk","1 tbsp raw sugar","pinch of cinnamon (optional)"],"steps":["Bring water/milk to a gentle simmer in a chocolatiera or saucepan.","Drop in cacao tablea tablets and allow to soften for 3 minutes.","Froth vigorously using a wooden whisk (molinillo) or handheld milk frother until rich and creamy.","Sweeten lightly and serve hot."],"note":"Pure cacao tablea delivers powerful cocoa polyphenols, flavonoids, and magnesium.","id":"r455"},{"title":"Kapeng Barako (Batangas Liberica Coffee)","category":"beverage","prep":"3 mins","cook":"7 mins","servings":"4","ingredients":["4 tbsp coarsely ground Kapeng Barako (Coffea liberica)","4 cups water","raw sugar or coconut sugar to taste"],"steps":["Bring water to a rolling boil in a pot.","Add ground Barako coffee, turn down heat, and simmer for 4 minutes.","Remove from heat and let the grounds settle for 3 minutes. Strain through a fine mesh or cloth filter.","Serve hot black, or sweeten with coconut sugar."],"note":"Rich in chlorogenic acids and dietary antioxidants with zero calories when consumed black.","id":"r456"},{"title":"Salabat (Traditional Ginger Tea)","category":"beverage","prep":"5 mins","cook":"15 mins","servings":"4","ingredients":["50g fresh ginger root (bruised/sliced)","4 cups water","2 tbsp calamansi juice","2 tbsp honey"],"steps":["Boil bruised ginger in 4 cups of water for 15 minutes to extract active gingerols.","Strain tea into cups.","Stir in fresh calamansi juice and honey to taste."],"note":"Time-tested therapeutic infusion for soothing upper respiratory discomfort and aiding digestion.","id":"r457"},{"title":"Guyabano (Soursop) Nectar Drink","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["2 cups fresh guyabano pulp (seeded)","2 cups cold water","1 tbsp honey or calamansi juice","ice"],"steps":["Blend fresh guyabano pulp with cold water until smooth.","Strain through a coarse mesh if a smoother texture is preferred.","Add honey or a squeeze of calamansi for balance. Serve chilled."],"note":"Rich in dietary fiber, Vitamin C, and bioactive acetogenins.","id":"r458"},{"title":"Dalandan Juice Refreshment","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["8 fresh Dalandan oranges (juiced)","3 cups cold water","2 tbsp raw cane sugar","ice"],"steps":["Slice dalandan oranges and extract juice using a citrus press.","Combine fresh juice with cold water and sweeten lightly.","Stir well and pour over ice."],"note":"Local citrus packed with natural bioflavonoids and immune-boosting Vitamin C.","id":"r459"},{"title":"Pineapple Buko Cooler","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["2 cups unsweetened pineapple juice","2 cups buko water","1/2 cup buko meat strips","ice"],"steps":["Combine fresh pineapple juice and buko water in a beverage pitcher.","Add buko meat strips and stir.","Serve chilled over ice cubes."],"note":"Provides bromelain enzymes from pineapple to aid digestion alongside coconut electrolytes.","id":"r460"},{"title":"Kamias Infused Iced Tea","category":"beverage","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["10 fresh kamias (bilimbi, sliced)","4 cups water","2 black tea bags","3 tbsp honey or raw sugar","ice cubes"],"steps":["Boil sliced kamias in 4 cups of water for 10 minutes, lightly mashing the fruit to release its natural sour juices.","Remove from heat, add black tea bags, and steep for 5 minutes.","Strain the mixture through a fine mesh strainer into a pitcher.","Stir in honey until fully dissolved. Allow to cool, then serve over ice."],"note":"Kamias provides a natural tartness high in vitamin C, reducing the need for artificial flavorings or high quantities of refined sugars.","id":"r461"},{"title":"Tanglad (Lemongrass) Tea","category":"beverage","prep":"5 mins","cook":"15 mins","servings":"4","ingredients":["4 stalks fresh tanglad (lemongrass, washed and bruised)","5 cups water","2 tbsp raw honey or coco sugar","calamansi wedges (optional)"],"steps":["Cut tanglad stalks into 3-inch pieces and crush the base with the back of a knife to release aromatic oils.","Bring water to a boil in a pot, add tanglad, and simmer over low heat for 15 minutes.","Strain the liquid into cups or a heat-proof pitcher.","Sweeten with raw honey and add a squeeze of calamansi if desired. Serve hot or chilled."],"note":"Lemongrass contains citral and geraniol, compounds noted for their mild digestive-soothing and antioxidant properties.","id":"r462"},{"title":"Pandan Infused Cold Brew","category":"beverage","prep":"10 mins","cook":"0 mins (Steep 12 hrs)","servings":"4","ingredients":["1 cup coarsely ground Kapeng Barako or Arabica coffee","4 cups cold filtered water","3 fresh pandan leaves (tied into a knot)"],"steps":["In a large pitcher or jar, combine ground coffee, cold water, and the bruised pandan knot.","Stir gently, cover, and refrigerate for 12 to 16 hours.","Strain the cold brew through a cheesecloth or fine coffee filter.","Pour over ice and serve plain or with a splash of low-fat milk."],"note":"Cold brewing yields a lower-acidity coffee, while natural pandan infusion imparts a vanilla-like aroma without added caloric sweeteners.","id":"r463"},{"title":"Buko Pandan Drink","category":"beverage","prep":"15 mins","cook":"10 mins","servings":"6","ingredients":["4 cups fresh young coconut water","1 cup buko meat (shredded)","1 cup green unflavored gulaman (agar-agar, cooked with pandan and cubed)","1/2 cup low-fat evaporated milk","2 tbsp condensed milk or coconut sugar"],"steps":["Prepare gulaman according to package directions, adding boiled pandan leaves to the water; let set and cut into small cubes.","In a pitcher, combine fresh buko water, shredded buko meat, and pandan gulaman cubes.","Stir in low-fat evaporated milk and sweeten lightly with condensed milk.","Chill in the refrigerator for at least 1 hour before serving over ice."],"note":"Combining hydrating coconut water with agar-agar (gulaman) adds soluble fiber, helping to moderate nutrient absorption.","id":"r464"},{"title":"Ube Milk Shake (Low-Fat)","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"2","ingredients":["1/2 cup cooked real ube (steamed and mashed purple yam)","1.5 cups unsweetened almond milk or low-fat milk","1 tbsp honey or maple syrup","1 cup crushed ice","1/4 tsp vanilla extract"],"steps":["Combine mashed ube, low-fat milk, honey, vanilla extract, and crushed ice in a blender.","Blend on high speed for 1 to 2 minutes until completely smooth and frothy.","Pour into chilled glasses and serve immediately."],"note":"Using real purple yam delivers rich dietary fiber and anthocyanin antioxidants rather than artificial ube flavorings and syrups.","id":"r465"},{"title":"Mango Milkshake (Carabao Mango)","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"2","ingredients":["2 ripe Philippine Carabao mangoes (scooped)","1 cup low-fat milk or skim milk","1/2 cup ice cubes","1 tsp chia seeds (optional)"],"steps":["Add the fresh mango pulp, low-fat milk, and ice into a high-speed blender.","Blend until smooth, thick, and creamy.","Pour into tall glasses and top with chia seeds for added texture and fiber."],"note":"Naturally sweet Carabao mangoes eliminate the need for added sugar while providing high levels of Vitamin A and C.","id":"r466"},{"title":"Calamansi Iced Tea","category":"beverage","prep":"10 mins","cook":"10 mins","servings":"5","ingredients":["10 fresh calamansi","4 cups water","3 black tea bags","3 tbsp honey","ice cubes"],"steps":["Steep black tea bags in 2 cups of hot water for 5 minutes; remove tea bags.","Cut calamansi and extract juice, discarding seeds.","Dissolve honey into the warm tea, then pour in remaining cold water and calamansi juice.","Stir well and serve in glasses filled with ice."],"note":"Black tea polyphenols paired with fresh calamansi juice offer a dual boost of antioxidants and immune-supporting vitamin C.","id":"r467"},{"title":"Guyabano Mint Tea","category":"beverage","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["1 cup fresh guyabano (soursop) pulp (seeded)","4 fresh mint leaves","3 cups green tea (brewed and chilled)","1 tbsp honey","ice"],"steps":["Muddle fresh mint leaves gently in the bottom of a pitcher.","Blend guyabano pulp with 1/2 cup of chilled green tea until smooth, then strain into the pitcher.","Pour in the remaining chilled green tea and honey; stir thoroughly.","Serve over ice garnished with fresh mint sprigs."],"note":"Guyabano offers dietary fiber and micronutrients, while green tea provides epigallocatechin gallate (EGCG) for metabolic support.","id":"r468"},{"title":"Buko Juice with Lychee","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["4 cups fresh buko (young coconut) water","1 cup buko meat (shredded)","1/2 cup fresh or unsweetened canned lychees (chopped)","ice cubes"],"steps":["Pour fresh buko water into a pitcher and mix in the shredded coconut meat.","Stir in the chopped lychees along with their natural juice.","Mix well and serve over ice."],"note":"Provides an isotonic balance of electrolytes with tropical fruit flavor, suitable for post-workout rehydration.","id":"r469"},{"title":"Tsokolate Eh (Concentrated Dark Cacao Shot)","category":"beverage","prep":"5 mins","cook":"10 mins","servings":"2","ingredients":["4 tablets pure dark cacao tablea","1 cup water or low-fat milk","1 tsp coconut sugar"],"steps":["Heat water or milk in a small saucepan over medium-low heat.","Add cacao tablea tablets and let them melt, stirring continuously.","Use a wooden batidor or milk frother to churn the liquid into a thick, velvety consistency.","Sweeten lightly with coconut sugar and serve hot in small espresso cups."],"note":"High-density dark cacao delivers rich cocoa flavanols and magnesium; keeping portions small controls total caloric density.","id":"r470"},{"title":"Kape at Tsokolate (Filipino Mocha)","category":"beverage","prep":"5 mins","cook":"8 mins","servings":"2","ingredients":["2 tablets cacao tablea","1 cup freshly brewed Kapeng Barako (hot)","1 cup low-fat milk","1 tbsp raw sugar"],"steps":["Dissolve cacao tablea into hot Kapeng Barako in a small saucepan over low heat.","Froth low-fat milk in a separate pitcher.","Pour the coffee-cacao mixture into mugs, top with frothed milk, and stir in raw sugar."],"note":"Combines central nervous system stimulation from coffee caffeine with the cardiovascular benefits of unrefined cacao.","id":"r471"},{"title":"Salabat with Turmeric (Luyang Dilaw)","category":"beverage","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["30g fresh ginger root (sliced)","20g fresh turmeric root (sliced)","4 cups water","1 pinch black pepper","2 tbsp honey","calamansi juice to taste"],"steps":["Boil sliced ginger and turmeric roots in water for 15 minutes.","Add a tiny pinch of black pepper during the last minute of boiling (enhances curcumin absorption).","Strain the tea into cups.","Stir in honey and fresh calamansi juice before serving warm."],"note":"Turmeric's curcumin combined with gingerol provides potent anti-inflammatory effects; black pepper boosts bioavailability significantly.","id":"r472"},{"title":"Sampalok (Tamarind) Juice","category":"beverage","prep":"15 mins","cook":"20 mins","servings":"5","ingredients":["1 cup ripe tamarind pods (shelled)","5 cups water","1/4 cup raw cane sugar or honey","ice cubes"],"steps":["Boil shelled tamarind pods in 2 cups of water for 15 minutes until soft.","Mash the tamarind with a fork, then press through a sieve to extract pulp and juice while discarding seeds and fibers.","Mix the extracted pulp with remaining cold water and cane sugar until fully dissolved.","Serve thoroughly chilled over ice."],"note":"Tamarind contains tartaric acid, a potent antioxidant that also aids in smooth digestion.","id":"r473"},{"title":"Suha (Pomelo) Pink Juice","category":"beverage","prep":"15 mins","cook":"0 mins","servings":"4","ingredients":["2 cups fresh pink pomelo pulp (pulped/separated)","3 cups cold water","2 tbsp honey","ice cubes"],"steps":["Muddle half of the pomelo pulp in a pitcher to release juice; leave the remaining pulp in whole vesicles for texture.","Pour in cold water and honey, stirring until the sweetening agent dissolves.","Add the remaining pomelo pulp and serve cold over ice."],"note":"Rich in lycopene, potassium, and vitamin C, supporting cardiovascular and metabolic health.","id":"r474"},{"title":"Duhat (Java Plum) Fruit Drink","category":"beverage","prep":"15 mins","cook":"5 mins","servings":"4","ingredients":["2 cups ripe duhat (Java plum)","3 cups water","2 tbsp rock salt (for astringency removal)","3 tbsp raw sugar","ice"],"steps":["Toss duhat fruit with salt in a bowl, shaking vigorously for 2 minutes to soften and reduce astringency; rinse thoroughly.","Mash fruit pulp, removing hard seeds.","Simmer pulp with 1 cup of water and sugar for 5 minutes, then strain.","Dilute extracted juice with remaining cold water and serve over ice."],"note":"Duhat contains jamboline and anthocyanins, traditional compounds studied for supporting healthy blood sugar levels.","id":"r475"},{"title":"Santol Cold Infusion","category":"beverage","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["2 ripe santol fruits (peeled, seeds removed, flesh chopped)","4 cups water","3 tbsp honey or stevia","ice"],"steps":["Simmer chopped santol flesh in 2 cups of water for 10 minutes until tender.","Mash flesh and strain juice into a pitcher, discarding hard pulp.","Add remaining cold water and sweeten with honey.","Chill in the refrigerator and serve over ice."],"note":"Provides pectin and soluble fiber along with a distinct tangy taste that reduces reliance on heavy sugars.","id":"r476"},{"title":"Tuba (Fresh Coconut Nectar - Non-alcoholic)","category":"beverage","prep":"5 mins","cook":"0 mins","servings":"4","ingredients":["4 cups unfermented fresh coconut sap/nectar (tuba)","calamansi juice to taste","ice cubes"],"steps":["Ensure fresh coconut sap is unfermented and kept thoroughly chilled.","Pour cold coconut sap into glasses filled with ice.","Add a quick squeeze of fresh calamansi juice to cut sweetness if desired."],"note":"Unfermented coconut sap is naturally sweet with a low glycemic index, packed with amino acids, B-vitamins, and minerals.","id":"r477"},{"title":"Lambanog Citrus Mocktail Base","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["2 cups sparkling mineral water","1/2 cup fresh calamansi juice","1/2 cup fresh dalandan juice","2 tbsp honey","fresh mint leaves","ice"],"steps":["Whisk honey into fresh calamansi and dalandan juices until dissolved.","Muddle mint leaves in serving glasses.","Divide citrus base into glasses, top with cold sparkling mineral water, and fill with ice."],"note":"A zero-alcohol alternative to traditional cocktails, providing hydration, carbonation, and high vitamin C content.","id":"r478"},{"title":"Pineapple Mint Cooler","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["3 cups fresh Formosa pineapple (cubed)","6 fresh mint leaves","1 cup cold water","ice cubes"],"steps":["Combine fresh pineapple cubes, mint leaves, and cold water in a blender.","Blend on high speed until light and frothy.","Strain into a pitcher if a clearer beverage is desired, or serve unstrained for full fiber benefits over ice."],"note":"Pineapple provides natural bromelain enzymes to aid digestion, complemented by cooling, digestive-supportive mint.","id":"r479"},{"title":"Watermelon Shake Tagalog","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"2","ingredients":["3 cups fresh red watermelon (seeded and cubed)","1 tbsp calamansi juice","1/2 cup crushed ice","1 tsp fresh mint (garnish)"],"steps":["Place seeded watermelon cubes, calamansi juice, and crushed ice into a blender.","Blend until smooth and slushy.","Pour into glasses and garnish with mint leaves."],"note":"Exceptionally high in water content and lycopene, offering superior hydration with minimal caloric load.","id":"r480"},{"title":"Avocado Smoothie with Condensed Milk Substitute","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"2","ingredients":["1 large ripe Hass or local avocado (scooped)","1 cup unsweetened almond milk","2 tbsp pure honey or coconut nectar","1/2 cup crushed ice"],"steps":["Scoop avocado flesh directly into a blender jar.","Add almond milk, honey (substituting heavy condensed milk), and crushed ice.","Blend until silky, thick, and uniform. Serve immediately."],"note":"Substituting condensed milk with honey and nut milk retains avocado's heart-healthy monounsaturated fats while dramatically lowering refined sugar intake.","id":"r481"},{"title":"Guyabano Green Tea","category":"beverage","prep":"10 mins","cook":"5 mins","servings":"4","ingredients":["1 cup soursop (guyabano) pulp","3 cups freshly brewed green tea","2 tbsp raw sugar or honey","ice cubes"],"steps":["Brew green tea bags in hot water for 3 minutes, then chill.","Puree guyabano pulp with 1/2 cup of chilled tea and strain.","Combine tea, guyabano puree, and honey in a pitcher; stir vigorously.","Serve cold over ice."],"note":"Blends dietary fiber and vitamin C from guyabano with the potent antioxidant epigallocatechin gallate (EGCG) found in green tea.","id":"r482"},{"title":"Calamansi Ginger Detox Brew","category":"beverage","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["1/2 cup fresh calamansi juice","3 tbsp crushed ginger","4 cups water","2 tbsp honey","1/4 tsp cayenne pepper (optional)"],"steps":["Simmer crushed ginger in water for 10 minutes; strain liquid into a pitcher.","Stir in calamansi juice, honey, and optional cayenne pepper.","Serve warm or chill in the refrigerator to serve over ice."],"note":"Gingerol and capsaicin stimulate circulation and thermogenesis while calamansi provides essential micronutrients.","id":"r483"},{"title":"Mango-Banana Smoothie","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"2","ingredients":["1 ripe Carabao mango","1 ripe Saba banana (steamed and cooled)","1 cup low-fat yogurt or milk","1/2 cup ice"],"steps":["Scoop mango flesh and cut steamed saba banana into rounds.","Place fruit, low-fat yogurt, and ice into a blender.","Process until thick and creamy."],"note":"Saba bananas provide resistant starch and potassium, while yogurt adds probiotics and high-quality protein.","id":"r484"},{"title":"Buko-Carrot Hydration Juice","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"3","ingredients":["2 cups fresh buko water","1 cup fresh carrot juice (extruded)","1 tbsp calamansi juice","ice"],"steps":["Extract fresh juice from carrots using a juicer.","Mix carrot juice with fresh buko water and calamansi juice in a pitcher.","Stir thoroughly and serve over ice."],"note":"Combines beta-carotene and Vitamin A from carrots with the essential mineral electrolytes of coconut water.","id":"r485"},{"title":"Hibiscus (Gumamela) Herbal Infusion","category":"beverage","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["1/2 cup dried edible hibiscus (gumamela) petals","4 cups water","3 tbsp honey","1 cinnamon stick"],"steps":["Bring water and cinnamon stick to a boil in a saucepan.","Add dried hibiscus petals, turn off heat, cover, and steep for 10 minutes.","Strain into a pitcher, discard solids, and stir in honey.","Serve hot or chilled over ice."],"note":"Hibiscus tea is rich in organic acids and anthocyanins, which clinical studies suggest aid in supporting healthy blood pressure levels.","id":"r486"},{"title":"Banaba Leaf Herbal Tea","category":"beverage","prep":"5 mins","cook":"15 mins","servings":"4","ingredients":["4 fresh or dried Banaba leaves (Lagerstroemia speciosa)","5 cups water","lemon or calamansi slices"],"steps":["Wash banaba leaves thoroughly.","Boil leaves in water for 15 minutes, then reduce heat and let steep for an additional 5 minutes.","Strain tea into cups and serve warm with a slice of calamansi."],"note":"Banaba contains corosolic acid, a natural compound known for its role in enhancing insulin sensitivity and glucose transport.","id":"r487"},{"title":"Sambong Herbal Tea","category":"beverage","prep":"5 mins","cook":"15 mins","servings":"4","ingredients":["6 fresh Sambong leaves (Blumea balsamifera)","5 cups water","honey to taste"],"steps":["Clean sambong leaves under running water and chop coarsely.","Boil in water for 15 minutes.","Strain liquid into cups and sweeten lightly with honey if desired. Serve warm."],"note":"Recognized by traditional and clinical pharmacopeia in the Philippines for its diuretic properties and support of renal fluid balance.","id":"r488"},{"title":"Kapa-Kapa Berry Iced Tea","category":"beverage","prep":"10 mins","cook":"10 mins","servings":"4","ingredients":["1 cup native Kapa-Kapa / indigenous wild berries (or local black plums)","4 cups water","2 tbsp raw sugar","2 tea bags (black or hibiscus tea)","ice"],"steps":["Simmer berries in 2 cups of water for 10 minutes, lightly mashing to release color and tartness.","Add tea bags and steep for 5 minutes; strain completely.","Mix with remaining cold water and sugar; stir well.","Serve cold over ice."],"note":"Indigenous berries offer high concentrations of flavonoids and polyphenols for cellular protection.","id":"r489"},{"title":"Benguet Coffee French Press Brew","category":"beverage","prep":"5 mins","cook":"5 mins","servings":"3","ingredients":["4 tbsp coarse-ground Benguet blend coffee (Arabica/Robusta blend)","3 cups hot water (93°C)"],"steps":["Place coarse coffee grounds into the bottom of a French press.","Pour hot water over grounds, ensuring all coffee is saturated.","Let steep for 4 minutes, then press plunger down slowly and smoothly.","Pour into mugs and serve black or with milk."],"note":"Unfiltered French press coffee retains natural coffee oils and antioxidants with zero added sugars.","id":"r490"},{"title":"Sagada Arabica Pour-Over Coffee","category":"beverage","prep":"5 mins","cook":"4 mins","servings":"2","ingredients":["3 tbsp medium-ground Sagada Arabica coffee beans","2 cups hot water (90°C)"],"steps":["Place a paper filter in a pour-over cone and rinse with hot water; discard rinse water.","Add ground coffee to filter.","Slowly pour hot water in circular motions over coffee grounds in 3 stages, allowing it to drip through completely.","Serve clean hot coffee immediately."],"note":"Paper filtration traps cafestol and kahweol diterpenes, producing a clean, heart-friendly brew with distinct floral notes.","id":"r491"},{"title":"Kalinga Dark Roast Cold Brew","category":"beverage","prep":"10 mins","cook":"0 mins (Steep 16 hrs)","servings":"4","ingredients":["1 cup coarsely ground Kalinga Robusta coffee","4 cups cold filtered water","ice"],"steps":["Combine ground Robusta coffee and cold water in a large glass jar.","Cover and steep in the refrigerator for 16 hours.","Strain thoroughly through a fine mesh sieve lined with a coffee filter.","Serve concentrated cold brew over ice, diluted with water or milk to taste."],"note":"High-altitude Robusta delivers nearly double the antioxidant capacity and caffeine concentration of standard Arabica varieties.","id":"r492"},{"title":"Tsokolate Granita","category":"beverage","prep":"15 mins","cook":"10 mins","servings":"4","ingredients":["3 tablets cacao tablea","3 cups water","3 tbsp coconut sugar","1/2 tsp cinnamon"],"steps":["Boil water with tablea, coconut sugar, and cinnamon for 8 minutes until tablea dissolves completely.","Pour mixture into a shallow metal pan and let cool to room temperature.","Freeze pan; every 30 minutes, scrape frozen edges with a fork to form fluffy ice crystals. Repeat for 3 hours.","Scoop shaved cacao granita into chilled glasses and serve."],"note":"A refreshing, low-fat alternative to dairy ice creams, leveraging pure cacao for rich flavor and flavanols.","id":"r493"},{"title":"Mais con Yelo Drinkable Cup","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"2","ingredients":["1 cup sweet yellow corn kernels (creamed or whole)","1.5 cups crushed ice","1 cup low-fat milk","1 tbsp raw sugar or erythritol"],"steps":["Layer sweet corn kernels at the bottom of tall glasses.","Fill glasses with crushed ice.","Pour low-fat milk and sweetening agent over ice, stirring gently before consuming with a wide straw."],"note":"Sweet corn delivers lutein and zeaxanthin for eye health along with complex carbohydrates.","id":"r494"},{"title":"Saba Banana Shake","category":"beverage","prep":"10 mins","cook":"10 mins","servings":"2","ingredients":["2 ripe Saba bananas (steamed, cooled, and sliced)","1 cup low-fat milk","1/2 cup ice","1/4 tsp nutmeg"],"steps":["Steam Saba bananas for 10 minutes to soften and enhance sweetness; cool.","Place steamed banana slices, low-fat milk, ice, and nutmeg into a blender.","Blend on high until completely smooth."],"note":"Steaming Saba bananas converts starches into easily digestible carbohydrates rich in prebiotic fiber and potassium.","id":"r495"},{"title":"Ripe Papaya Calamansi Smoothie","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"2","ingredients":["2 cups ripe solo papaya (cubed)","2 tbsp fresh calamansi juice","1/2 cup cold water or coconut water","1/2 cup ice"],"steps":["Combine ripe papaya cubes, fresh calamansi juice, water, and ice in a blender.","Blend until smooth and velvety.","Pour into glasses and serve chilled."],"note":"Papaya contains papain enzymes to support digestion, paired with high doses of Vitamin C and folate.","id":"r496"},{"title":"Dalanghita Limeade","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["6 fresh dalanghita (Filipino green oranges, juiced)","1 fresh dayap (lime, juiced)","3 cups cold water","2 tbsp honey","ice"],"steps":["Extract juices from fresh dalanghita oranges and dayap lime, discarding seeds.","Whisk honey into room-temperature water in a pitcher until dissolved.","Add extracted citrus juices and remaining cold water. Stir and serve over ice."],"note":"Native citrus fruits provide bioflavonoids that enhance vitamin C absorption and support immune function.","id":"r497"},{"title":"Calamansi Cucumber Mint Cooler","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["1 medium cucumber (sliced)","1/4 cup fresh calamansi juice","6 fresh mint leaves","3 cups cold water","2 tbsp honey","ice"],"steps":["Muddle cucumber slices and mint leaves gently in a pitcher.","Stir in calamansi juice, honey, and cold water until sweetening agent is fully dissolved.","Fill glasses with ice, pour cooler over top, and serve."],"note":"Hydrating and anti-inflammatory beverage rich in silica, potassium, and active antioxidant compounds.","id":"r498"},{"title":"Buko-Lychee Sparkler","category":"beverage","prep":"10 mins","cook":"0 mins","servings":"4","ingredients":["2 cups fresh buko water","1 cup unsweetened lychee juice","1 cup sparkling mineral water","shredded buko meat","ice"],"steps":["Combine fresh buko water, lychee juice, and shredded coconut meat in a pitcher.","Divide into glasses filled with ice.","Top each glass with sparkling mineral water right before serving for a light fizz."],"note":"Naturally carbonated hydration option low in sodium and free of high-fructose corn syrup.","id":"r499"},{"title":"Spiced Cold Salabat with Honey","category":"beverage","prep":"10 mins","cook":"15 mins","servings":"4","ingredients":["40g fresh ginger (thinly sliced)","1 cinnamon stick","2 star anise","4 cups water","3 tbsp raw honey","calamansi wedges","ice"],"steps":["Boil ginger, cinnamon stick, and star anise in water for 15 minutes to infuse spices.","Strain liquid into a container and stir in honey while warm.","Allow the mixture to cool completely, then refrigerate.","Serve cold over ice with fresh calamansi wedges."],"note":"Spices such as cinnamon and star anise add natural sweetness and antimicrobial properties without contributing extra calories.","id":"r500"}];
